import React, { lazy, Suspense } from 'react';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { PanelProvider } from './context/PanelContext';
import PanelLayout from './layouts/PanelLayout';
import LandingPage from './pages/LandingPage';
import ErrorBoundary from './components/ui/ErrorBoundary';
import { captureSource } from './utils/attribution';
import './index.css';
import './App.css';

// Atribución first-touch: registrar el canal de origen al cargar la app.
captureSource();

const InicioPage = lazy(() => import('./pages/InicioPage'));
const VentasPage = lazy(() => import('./pages/VentasPage'));
const PlanPage = lazy(() => import('./pages/PlanPage'));
const AdminPage = lazy(() => import('./pages/AdminPage'));
const SoportePage = lazy(() => import('./pages/SoportePage'));
const ConfigPage = lazy(() => import('./pages/ConfigPage'));
const Onboarding = lazy(() => import('./pages/Onboarding'));
const NosotrosPage = lazy(() => import('./pages/NosotrosPage'));
const ContactoPage = lazy(() => import('./pages/ContactoPage'));
const SoportePublicoPage = lazy(() => import('./pages/SoportePublicoPage'));
const StockModule = lazy(() => import('./features/StockModule'));
const PurchasesModule = lazy(() => import('./features/PurchasesModule'));
const FiadoModule = lazy(() => import('./features/FiadoModule'));
const ProveedoresModule = lazy(() => import('./features/ProveedoresModule'));
const CatalogoModule = lazy(() => import('./features/CatalogoModule'));
const ReportsModule = lazy(() => import('./features/ReportsModule'));
const PromotionModule = lazy(() => import('./features/PromotionModule'));
const RecomendacionesModule = lazy(() => import('./features/RecomendacionesModule'));
const UsuariosModule = lazy(() => import('./features/UsuariosModule'));
const AuditModule = lazy(() => import('./features/AuditModule'));
const PreviewPage = lazy(() => import('./pages/PreviewPage'));
const PublicCatalog = lazy(() => import('./pages/PublicCatalog'));
const TermsPage = lazy(() => import('./pages/TermsPage'));
const PrivacyPage = lazy(() => import('./pages/PrivacyPage'));

function PanelSuspense({ children }) {
  return (
    <Suspense fallback={
      <div style={{ padding: 40, color: 'var(--text-secondary)', fontSize: '1.1rem', fontWeight: 600 }}>
        Cargando...
      </div>
    }>
      {children}
    </Suspense>
  );
}

function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/" element={<LandingPage />} />
        <Route path="/nosotros" element={<PanelSuspense><NosotrosPage /></PanelSuspense>} />
        <Route path="/contacto" element={<PanelSuspense><ContactoPage /></PanelSuspense>} />
        <Route path="/soporte" element={<PanelSuspense><SoportePublicoPage /></PanelSuspense>} />
        <Route path="/register" element={<PanelSuspense><Onboarding /></PanelSuspense>} />
        <Route path="/login" element={<Navigate to="/" replace />} />

        <Route path="/panel" element={
          <ErrorBoundary>
            <PanelProvider>
              <PanelLayout />
            </PanelProvider>
          </ErrorBoundary>
        }>
          <Route index element={<Navigate to="inicio" replace />} />
          <Route path="inicio" element={<PanelSuspense><InicioPage /></PanelSuspense>} />
          <Route path="ventas" element={<PanelSuspense><VentasPage /></PanelSuspense>} />
          <Route path="inventario" element={<PanelSuspense><StockModule /></PanelSuspense>} />
          <Route path="compras" element={<PanelSuspense><PurchasesModule /></PanelSuspense>} />
          <Route path="clientes" element={<PanelSuspense><FiadoModule /></PanelSuspense>} />
          <Route path="proveedores" element={<PanelSuspense><ProveedoresModule /></PanelSuspense>} />
          <Route path="catalogo-web" element={<PanelSuspense><CatalogoModule /></PanelSuspense>} />
          <Route path="reportes" element={<PanelSuspense><ReportsModule /></PanelSuspense>} />
          <Route path="promociones" element={<PanelSuspense><PromotionModule /></PanelSuspense>} />
          <Route path="recomendaciones" element={<PanelSuspense><RecomendacionesModule /></PanelSuspense>} />
          <Route path="usuarios" element={<PanelSuspense><UsuariosModule /></PanelSuspense>} />
          <Route path="auditoria" element={<PanelSuspense><AuditModule /></PanelSuspense>} />
          <Route path="configuracion" element={<PanelSuspense><ConfigPage /></PanelSuspense>} />
          <Route path="soporte" element={<PanelSuspense><SoportePage /></PanelSuspense>} />
          <Route path="plan" element={<PanelSuspense><PlanPage /></PanelSuspense>} />
        </Route>

        <Route path="/admin" element={<PanelSuspense><AdminPage /></PanelSuspense>} />
    <Route path="/t/:slug" element={<PanelSuspense><PublicCatalog /></PanelSuspense>} />
        <Route path="/preview" element={<PanelSuspense><PreviewPage /></PanelSuspense>} />
        <Route path="/terminos" element={<PanelSuspense><TermsPage /></PanelSuspense>} />
        <Route path="/privacidad" element={<PanelSuspense><PrivacyPage /></PanelSuspense>} />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </BrowserRouter>
  );
}

export default App;

import React, { useState, useEffect } from 'react';

const FIELDS = [
  { key: 'nombre',         label: 'Nombre del negocio',    placeholder: 'Kiosco Don Julio' },
  { key: 'subtitulo',      label: 'Subtítulo / Slogan',    placeholder: 'Atención 7 días de la semana' },
  { key: 'direccion',      label: 'Dirección',             placeholder: 'Av. Corrientes 1234, CABA' },
  { key: 'telefono',       label: 'Teléfono',              placeholder: '011-4855-0000' },
  { key: 'cuit',           label: 'CUIT / CUIL',           placeholder: '20-12345678-9' },
  { key: 'condicion_iva',  label: 'Condición IVA',         placeholder: 'Monotributista', options: ['Monotributista', 'Responsable Inscripto', 'Exento', 'Consumidor Final'] },
  { key: 'numero_caja',    label: 'Nombre de la caja',     placeholder: 'CAJA 1' },
  { key: 'mensaje_ticket', label: 'Mensaje final del ticket', placeholder: '¡Gracias por su compra!' },
  { key: 'iva_rate',       label: 'IVA % por defecto',     placeholder: '21', options: ['21', '10.5', '27', '0'] },
  { key: 'mp_access_token',label: 'Access Token de Mercado Pago', placeholder: 'APP_USR-...' },
];

export default function ConfigModal({ onClose, onSave, operators, onOperatorsUpdate, serverUrl }) {
  const [config, setConfig] = useState({});
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    fetch(`${serverUrl}/config`)
      .then(r => r.json())
      .then(d => { setConfig(d); setLoading(false); })
      .catch(() => {
        setConfig({
          nombre: 'Kiosco El Barrio', subtitulo: 'Atención 7 días',
          direccion: '', telefono: '', cuit: '', condicion_iva: 'Monotributista',
          numero_caja: 'CAJA 1', mensaje_ticket: '¡Gracias por su compra!',
        });
        setLoading(false);
      });
  }, [serverUrl]);

  const handleSave = async () => {
    setSaving(true);
    try {
      await Promise.all([
        fetch(`${serverUrl}/config`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(config),
        }),
        fetch(`${serverUrl}/operators`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(operators),
        }),
      ]);
      onSave?.(config);
      onOperatorsUpdate(operators);
      setSaved(true);
      setTimeout(() => setSaved(false), 2000);
    } catch { console.error('Error al guardar configuración u operadores'); }
    setSaving(false);
  };

  const inputStyle = {
    width: '100%', background: 'var(--bg-main)', border: '1px solid var(--border-color)',
    color: 'var(--text-primary)', padding: '12px 16px', borderRadius: '8px',
    fontSize: '1rem', outline: 'none', fontFamily: 'var(--font-main)',
  };

  return (
    <div style={{ padding: '32px 40px', width: '100%', height: '100%', overflowY: 'auto', boxSizing: 'border-box' }}>
      <div style={{ maxWidth: '800px', margin: '0 auto', background: 'var(--bg-card)', padding: '32px', borderRadius: '16px', boxShadow: '0 4px 20px rgba(30,58,95,0.2)', border: '1px solid var(--border-color)' }}>
        <h2 style={{ fontSize: '1.8rem', color: 'var(--text-primary)', marginBottom: '8px' }}>⚙️ Ajustes y Configuración</h2>
        <p style={{ color: 'var(--text-secondary)', textAlign: 'center', marginBottom: '24px', fontSize: '0.9rem' }}>
          Estos datos aparecen en los tickets impresos y en el encabezado del sistema.
        </p>

        {loading ? (
          <div style={{ textAlign: 'center', padding: '32px', color: 'var(--text-secondary)' }}>Cargando...</div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
            {FIELDS.map(f => (
              <div key={f.key}>
                <label style={{ display: 'block', fontSize: '0.875rem', fontWeight: 600, color: 'var(--text-secondary)', marginBottom: '6px' }}>
                  {f.label}
                </label>
                {f.options ? (
                  <select
                    value={config[f.key] || ''}
                    onChange={e => setConfig(prev => ({ ...prev, [f.key]: e.target.value }))}
                    style={{ ...inputStyle, cursor: 'pointer' }}
                  >
                    {f.options.map(o => <option key={o} value={o}>{o}</option>)}
                  </select>
                ) : (
                  <input
                    type={f.key === 'mp_access_token' ? 'password' : 'text'}
                    value={config[f.key] || ''}
                    placeholder={f.key === 'mp_access_token' && config.mp_access_token_set
                      ? '•••••••• ya configurado (dejá vacío para no cambiarlo)'
                      : f.placeholder}
                    onChange={e => setConfig(prev => ({ ...prev, [f.key]: e.target.value }))}
                    style={inputStyle}
                  />
                )}
              </div>
            ))}

            {/* Preview del encabezado */}
            <div style={{ background: 'var(--bg-main)', border: '1px dashed var(--border-color)', borderRadius: '8px', padding: '16px', marginTop: '8px' }}>
              <div style={{ fontSize: '0.75rem', color: 'var(--text-secondary)', marginBottom: '8px', textTransform: 'uppercase', letterSpacing: '1px' }}>
                Preview del ticket (encabezado)
              </div>
              <pre style={{ fontFamily: 'var(--font-mono)', fontSize: '0.75rem', color: 'var(--text-primary)', lineHeight: 1.6, margin: 0 }}>
{`══════════════════════════════════════════
${(config.nombre || 'NOMBRE').toUpperCase().padStart(21 + Math.floor((config.nombre || '').length / 2))}
${(config.subtitulo || '').padStart(21 + Math.floor((config.subtitulo || '').length / 2))}
${(config.direccion || '').padStart(21 + Math.floor((config.direccion || '').length / 2))}
Tel: ${config.telefono || '---'}
══════════════════════════════════════════
CUIT: ${config.cuit || '---'}  ${config.condicion_iva || '---'}`}
              </pre>
            </div>

            {/* 👥 Operadores */}
            <div style={{ marginTop: '24px', borderTop: '1px solid var(--border-color)', paddingTop: '20px' }}>
              <h3 style={{ fontSize: '1.1rem', fontWeight: 700, marginBottom: '16px', color: 'var(--text-primary)' }}>👥 Operadores</h3>
              {operators && operators.map((op, i) => (
                <div key={i} style={{ display: 'flex', gap: '12px', marginBottom: '12px', alignItems: 'center' }}>
                  <div style={{ flex: 1 }}>
                    <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 600, color: 'var(--text-secondary)', marginBottom: '4px' }}>Nombre</label>
                    <input
                      type="text"
                      value={op.name}
                      onChange={e => {
                        const nuevos = [...operators];
                        nuevos[i] = { ...nuevos[i], name: e.target.value };
                        onOperatorsUpdate(nuevos);
                      }}
                      style={inputStyle}
                    />
                  </div>
                  <div style={{ width: '120px' }}>
                    <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 600, color: 'var(--text-secondary)', marginBottom: '4px' }}>PIN</label>
                    <input
                      type="text"
                      maxLength={4}
                      value={op.pin}
                      onChange={e => {
                        const nuevos = [...operators];
                        nuevos[i] = { ...nuevos[i], pin: e.target.value.replace(/[^0-9]/g, '').slice(0, 4) };
                        onOperatorsUpdate(nuevos);
                      }}
                      style={{ ...inputStyle, fontFamily: 'var(--font-mono)', textAlign: 'center' }}
                    />
                  </div>
                  <span style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', whiteSpace: 'nowrap' }}>({op.role})</span>
                </div>
              ))}
            </div>
          </div>
        )}

        <div style={{ marginTop: '32px', display: 'flex', justifyContent: 'flex-end' }}>
          <button
            className="btn btn-modal-confirm"
            onClick={handleSave}
            disabled={saving}
            style={{ width: '200px', opacity: saving ? 0.7 : 1 }}
          >
            {saved ? '✅ Guardado' : saving ? 'Guardando...' : 'Guardar Cambios'}
          </button>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { apiGet, apiPost } from '../services/apiClient';

export default function SetupWizard({ onComplete }) {
  const [step, setStep] = useState(0);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [form, setForm] = useState({
    business_name: '',
    admin_name: 'Dueño',
    admin_pin: '',
    admin_pin_confirm: '',
  });

  useEffect(() => {
    apiGet('/setup/status')
      .then(r => r.json())
      .then(d => {
        if (!d.needs_setup) return onComplete();
        setLoading(false);
      })
      .catch(() => { setLoading(false); setError('No se puede conectar con el servidor'); });
  }, [onComplete]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.business_name.trim()) return setError('Ingresá el nombre del negocio');
    if (form.admin_pin.length < 4) return setError('El PIN debe tener al menos 4 dígitos');
    if (form.admin_pin !== form.admin_pin_confirm) return setError('Los PIN no coinciden');
    setSaving(true);
    setError('');
    try {
      const res = await apiPost('/setup/init', {
        business_name: form.business_name.trim(),
        admin_name: form.admin_name.trim() || 'Dueño',
        admin_pin: form.admin_pin,
      });
      if (res.ok) {
        onComplete();
      } else {
        const d = await res.json();
        setError(d.detail || 'Error al guardar');
      }
    } catch {
      setError('Error de conexión con el servidor');
    } finally {
      setSaving(false);
    }
  };

  if (loading) return null;

  return (
    <div className="layout" style={{ justifyContent: 'center', alignItems: 'center' }}>
      <div style={{ maxWidth: 420, width: '100%', padding: 40 }}>
        <div style={{ textAlign: 'center', marginBottom: 32 }}>
          <h1 style={{ fontSize: '1.8rem', marginBottom: 8 }}>Configuración Inicial</h1>
          <p style={{ color: 'var(--text-secondary)' }}>Completá los datos para empezar a usar MiNegocio</p>
        </div>

        <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          <div>
            <label style={{ display: 'block', marginBottom: 4, color: 'var(--text-secondary)', fontSize: '0.9rem' }}>Nombre del negocio</label>
            <input type="text" value={form.business_name} onChange={e => setForm(f => ({ ...f, business_name: e.target.value }))}
              placeholder="Ej: Kiosco Don Julio" autoFocus
              style={{ width: '100%', padding: '12px 16px', borderRadius: 8, border: '1px solid var(--border-color)', background: 'var(--bg-card)', color: 'var(--text-primary)', fontSize: '1rem', outline: 'none' }} />
          </div>

          <div>
            <label style={{ display: 'block', marginBottom: 4, color: 'var(--text-secondary)', fontSize: '0.9rem' }}>Nombre del administrador</label>
            <input type="text" value={form.admin_name} onChange={e => setForm(f => ({ ...f, admin_name: e.target.value }))}
              placeholder="Dueño"
              style={{ width: '100%', padding: '12px 16px', borderRadius: 8, border: '1px solid var(--border-color)', background: 'var(--bg-card)', color: 'var(--text-primary)', fontSize: '1rem', outline: 'none' }} />
          </div>

          <div>
            <label style={{ display: 'block', marginBottom: 4, color: 'var(--text-secondary)', fontSize: '0.9rem' }}>PIN de administrador (4+ dígitos)</label>
            <input type="password" value={form.admin_pin} onChange={e => setForm(f => ({ ...f, admin_pin: e.target.value.replace(/[^0-9]/g, '').slice(0, 6) }))}
              placeholder="••••" maxLength={6}
              style={{ width: '100%', padding: '12px 16px', borderRadius: 8, border: '1px solid var(--border-color)', background: 'var(--bg-card)', color: 'var(--text-primary)', fontSize: '1.5rem', letterSpacing: '4px', textAlign: 'center', outline: 'none' }} />
          </div>

          <div>
            <label style={{ display: 'block', marginBottom: 4, color: 'var(--text-secondary)', fontSize: '0.9rem' }}>Confirmar PIN</label>
            <input type="password" value={form.admin_pin_confirm} onChange={e => setForm(f => ({ ...f, admin_pin_confirm: e.target.value.replace(/[^0-9]/g, '').slice(0, 6) }))}
              placeholder="••••" maxLength={6}
              style={{ width: '100%', padding: '12px 16px', borderRadius: 8, border: '1px solid var(--border-color)', background: 'var(--bg-card)', color: 'var(--text-primary)', fontSize: '1.5rem', letterSpacing: '4px', textAlign: 'center', outline: 'none' }} />
          </div>

          {error && <div style={{ color: 'var(--accent-danger)', textAlign: 'center', padding: 8, background: 'rgba(239,68,68,0.1)', borderRadius: 8 }}>{error}</div>}

          <button type="submit" disabled={saving}
            style={{ background: 'var(--gradient-primary)', border: 'none', color: 'white', padding: '14px', borderRadius: 12, fontSize: '1rem', fontWeight: 700, cursor: 'pointer', opacity: saving ? 0.6 : 1, marginTop: 8 }}>
            {saving ? 'Guardando...' : 'Comenzar'}
          </button>
        </form>
      </div>
    </div>
  );
}

import React, { useEffect, useRef } from 'react';
import QRCode from 'qrcode';

/*
  TicketPrint — Ticket térmico estilo Coto/supermercado (80mm)
  Se muestra oculto en la pantalla y aparece al imprimir (Ctrl+P / window.print())
  El ancho real de la ticketera es ~42 chars en fuente monospace 12px.
*/

const LINE = '─'.repeat(42);
const DLINE = '═'.repeat(42);

function center(text, width = 42) {
  const pad = Math.max(0, Math.floor((width - text.length) / 2));
  return ' '.repeat(pad) + text;
}

function formatRow(name, qty, price, total, width = 42) {
  // "2x Coca Cola 500ml         $2.400"
  const qtyStr = `${qty}x `;
  const totalStr = `$${total.toLocaleString('es-AR')}`;
  const maxName = width - qtyStr.length - totalStr.length - 1;
  const truncName = name.length > maxName ? name.slice(0, maxName - 1) + '…' : name.padEnd(maxName);
  return qtyStr + truncName + ' ' + totalStr;
}

function rAlign(label, value, width = 42) {
  const v = `$${typeof value === 'number' ? value.toLocaleString('es-AR') : value}`;
  const pad = Math.max(1, width - label.length - v.length);
  return label + ' '.repeat(pad) + v;
}

export default function TicketPrint({ cart, total, payment, change, operator, ticketNumber, config, isClosingShift, shiftData, tipoFactura, afip, paymentMethod }) {
  const ivaRate = parseFloat(config?.iva_rate) ?? 21;
  const ivaMultiplier = 1 + ivaRate / 100;
  const subtotal = total / ivaMultiplier;
  const iva = total - subtotal;
  const now = new Date();
  const fecha = now.toLocaleDateString('es-AR', { day: '2-digit', month: '2-digit', year: 'numeric' });
  const hora = now.toLocaleTimeString('es-AR', { hour: '2-digit', minute: '2-digit' });

  const nombre = config?.nombre || 'KIOSCO';
  const subtitulo = config?.subtitulo || '';
  const direccion = config?.direccion || '';
  const telefono = config?.telefono || '';
  const cuit = config?.cuit || '';
  const condicion = config?.condicion_iva || 'Monotributista';
  const mensaje = config?.mensaje_ticket || '¡Gracias por su compra!';
  const numeroCaja = config?.numero_caja || 'CAJA 1';
  
  const isFacturaA = tipoFactura === 'A';

  const qrCanvasRef = useRef(null);

  useEffect(() => {
    if (afip?.cae && qrCanvasRef.current) {
      const qrUrl = `https://afip.gob.ar/fe/comprobante?cae=${afip.cae}`;
      QRCode.toCanvas(qrCanvasRef.current, qrUrl, {
        width: 140,
        margin: 2,
        color: { dark: '#1E3A5F', light: '#fff' }
      });
    }
  }, [afip]);

  return (
    <div className="ticket-print-area">
      {!isClosingShift ? (
        /* ═══════════════════════════════ TICKET DE VENTA ═══════════════════════════════ */
        <pre className="ticket-body">
{DLINE}
{center(nombre.toUpperCase())}
{subtitulo ? center(subtitulo) : ''}
{direccion ? center(direccion) : ''}
{telefono ? center(`Tel: ${telefono}`) : ''}
{DLINE}
{`CUIT: ${cuit}`}
{`Cond. IVA: ${condicion}`}
{LINE}
{`CAJERO: ${operator || 'Sistema'}`}
{`${numeroCaja}   TICKET: #${String(ticketNumber || 1).padStart(5, '0')}`}
{`FECHA: ${fecha}   HORA: ${hora}`}
{LINE}
{'CANT  DESCRIPCIÓN                  PRECIO'}
{LINE}
{(cart || []).map(item =>
  formatRow(item.name, item.qty, item.price, item.price * item.qty)
).join('\n')}
{LINE}
{isFacturaA ? (
  <>
{rAlign('SUBTOTAL NETO:', subtotal.toFixed(2))}
{rAlign(`IVA (${ivaRate}%):`, iva.toFixed(2))}
{LINE}
  </>
) : (
  <>
{center('El precio incluye IVA')}
  </>
)}
{rAlign('*** TOTAL:', total)}
{LINE}
{rAlign(`${(paymentMethod || 'EFECTIVO').toUpperCase()}:`, payment)}
{rAlign('VUELTO:', change >= 0 ? change : 0)}
{LINE}
{center(mensaje)}
{center('¡Vuelva pronto!')}
{afip && afip.cae ? (
  <>
{DLINE}
{center('DATOS AFIP (Punto 34)')}
{`CAE: ${afip.cae}`}
{`Vto CAE: ${afip.vto}`}
{`Comprobante: ${tipoFactura} N° ${afip.cbte}`}
{DLINE}
<div style={{ textAlign: 'center', margin: '8px 0' }}>
  <canvas ref={qrCanvasRef} style={{ width: 140, height: 140 }} />
</div>
  </>
) : null}
{DLINE}
{center(`MiNegocio v1.0`)}
        </pre>
      ) : (
        /* ═══════════════════════════════ REPORTE DE CIERRE ═══════════════════════════════ */
        <pre className="ticket-body">
{DLINE}
{center('** CIERRE DE TURNO **')}
{center(nombre.toUpperCase())}
{LINE}
{`OPERADOR: ${shiftData?.operator || operator}`}
{`FECHA:    ${fecha}   HORA: ${hora}`}
{`APERTURA: ${shiftData?.opened_at ? new Date(shiftData.opened_at).toLocaleTimeString('es-AR', {hour:'2-digit',minute:'2-digit'}) : '--:--'}`}
{LINE}
{'RESUMEN DE VENTAS'}
{LINE}
{rAlign('Total tickets:', shiftData?.total_tickets || 0, 42).replace('$', ' ')}
{rAlign('Ventas efectivo:', shiftData?.total_efectivo || 0)}
{shiftData?.total_fiado > 0 ? rAlign('Ventas fiado:', shiftData.total_fiado) : ''}
