        </label>
        <label style={{ display: 'flex', alignItems: 'center', gap: '8px', color: 'var(--text-primary)', fontSize: '0.9rem' }}>
          <input type="checkbox" checked={printConfig.auto_print_ticket} onChange={e => setPrintConfig({...printConfig, auto_print_ticket: e.target.checked})} />
          Imprimir ticket automáticamente
        </label>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px', color: 'var(--text-primary)', fontSize: '0.9rem' }}>
          <span>Modo:</span>
          <select value={printConfig.mode} onChange={e => setPrintConfig({...printConfig, mode: e.target.value})} style={{ background: 'rgba(255,255,255,0.05)', border: '1px solid var(--border-color)', color: 'var(--text-primary)', padding: '6px 12px', borderRadius: '6px', outline: 'none' }}>
            <option value="window_print">window.print()</option>
            <option value="qz_tray">QZ Tray</option>
            <option value="agent">Agente Python</option>
          </select>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px', color: 'var(--text-primary)', fontSize: '0.9rem' }}>
          <span>Impresora:</span>
          <input type="text" value={printConfig.printer_name} onChange={e => setPrintConfig({...printConfig, printer_name: e.target.value})} placeholder="Nombre de impresora (opcional)" style={{ flex: 1, background: 'rgba(255,255,255,0.05)', border: '1px solid var(--border-color)', color: 'var(--text-primary)', padding: '6px 12px', borderRadius: '6px', outline: 'none' }} />
        </div>
      </div>
      <div style={{ marginTop: '16px', display: 'flex', gap: '12px' }}>
        <button onClick={async () => {
          try {
            await apiPut('/config/printing', printConfig);
            addToast('Configuración de impresión guardada', 'success');
          } catch { addToast('Error al guardar', 'error'); }
        }} style={{ background: 'var(--gradient-primary)', border: 'none', color: 'white', padding: '10px 20px', borderRadius: '8px', fontWeight: 700, cursor: 'pointer' }}>
          Guardar Configuración
        </button>
        <button onClick={async () => {
          try {
            await QZTray.connectQZTray(5000);
            setQzConnected(true);
            addToast('QZ Tray conectado', 'success');
          } catch {
            setQzConnected(false);
            addToast('QZ Tray no disponible', 'error');
          }
        }} style={{ background: 'rgba(255,255,255,0.05)', border: '1px solid var(--border-color)', color: 'var(--text-primary)', padding: '10px 20px', borderRadius: '8px', fontWeight: 700, cursor: 'pointer' }}>
          Probar Conexión QZ Tray
        </button>
        <button onClick={async () => {
          try {
            await QZTray.openCashDrawer(printConfig.printer_name);
            addToast('Cajón abierto', 'success');
          } catch (e) {
            try {
              await QZTray.openDrawerViaAgent('http://127.0.0.1:8199', printConfig.printer_name);
              addToast('Cajón abierto (vía agente)', 'success');
            } catch {
              addToast('No se pudo abrir el cajón', 'error');
            }
          }
        }} style={{ background: 'rgba(16,185,129,0.1)', border: '1px solid rgba(16,185,129,0.3)', color: 'var(--accent-success)', padding: '10px 20px', borderRadius: '8px', fontWeight: 700, cursor: 'pointer' }}>
          Probar Cajón
        </button>
      </div>
    </div>
  );
}

import React from 'react';

function DuplicateCodeModal({ showDuplicateCodeModal, setShowDuplicateCodeModal, duplicateCodeMatches, setDuplicateCodeMatches, setCart, playBeep, searchRef }) {
  if (!showDuplicateCodeModal) return null;
  return (
    <div className="modal-overlay" onClick={() => setShowDuplicateCodeModal(false)}>
      <div className="modal-content" onClick={e => e.stopPropagation()} style={{ width: '500px' }}>
        <h2 className="modal-title" style={{ color: 'var(--accent-warning)', fontSize: '1.4rem' }}>⚠️ Código de Barras Duplicado</h2>
        <p style={{ textAlign: 'center', color: 'var(--text-secondary)', marginBottom: '16px' }}>¿Cuál querés agregar?</p>
        {duplicateCodeMatches.map((p, idx) => (
          <button key={p.id} autoFocus={idx === 0} onClick={() => {
            setCart(prev => { const ex = prev.find(item => item.id === p.id); if (ex) return prev.map(item => item.id === p.id ? { ...item, qty: item.qty + 1 } : item); return [...prev, { ...p, qty: 1 }]; });
            playBeep(); setShowDuplicateCodeModal(false); setDuplicateCodeMatches([]); searchRef.current?.focus();
          }} style={{ display: 'flex', justifyContent: 'space-between', padding: '16px', width: '100%', background: 'var(--bg-main)', border: '1px solid var(--border-color)', borderRadius: '8px', color: 'var(--text-primary)', cursor: 'pointer', textAlign: 'left', fontWeight: 600, marginBottom: '8px' }}>
            <span>{p.name}</span><span style={{ color: 'var(--accent-success)', fontWeight: 800 }}>${p.price.toLocaleString('es-AR')}</span>
          </button>
        ))}
        <div className="modal-actions"><button className="btn btn-modal-cancel" onClick={() => { setShowDuplicateCodeModal(false); setDuplicateCodeMatches([]); searchRef.current?.focus(); }}>Cancelar</button></div>
      </div>
    </div>
  );
}

export default DuplicateCodeModal;

import React from 'react';

export default function EgresoModal({ showEgreso, setShowEgreso, egresoType, setEgresoType, egresoMonto, setEgresoMonto, egresoMotivo, setEgresoMotivo, submitEgreso }) {
  if (!showEgreso) return null;
  return (
    <div className="modal-overlay" onClick={() => setShowEgreso(false)}>
      <div className="modal-content" onClick={e => e.stopPropagation()}>
        <h2 className="modal-title" style={{ fontSize: '1.5rem', color: 'var(--accent-warning)' }}>💸 Registrar Egreso / Retiro</h2>
        <p style={{ color: 'var(--text-secondary)', textAlign: 'center', marginBottom: '24px' }}>Registrá acá la plata que saques de la caja para que no te dé faltante en el cierre.</p>
        <div className="input-group"><label>Tipo de Operación</label>
          <div style={{ display: 'flex', gap: '8px', marginBottom: '16px' }}>
            <button onClick={() => setEgresoType('gasto')} style={{ flex: 1, padding: '12px', borderRadius: '8px', border: '1px solid', borderColor: egresoType === 'gasto' ? 'var(--accent-danger)' : 'var(--border-color)', background: egresoType === 'gasto' ? 'rgba(239,68,68,0.15)' : 'transparent', color: egresoType === 'gasto' ? 'var(--text-primary)' : 'var(--text-secondary)', fontWeight: 700, cursor: 'pointer' }}>📉 Gasto (Afecta Ganancia)</button>
            <button onClick={() => setEgresoType('retiro')} style={{ flex: 1, padding: '12px', borderRadius: '8px', border: '1px solid', borderColor: egresoType === 'retiro' ? 'var(--accent-primary)' : 'var(--border-color)', background: egresoType === 'retiro' ? 'rgba(20,187,166,0.15)' : 'transparent', color: egresoType === 'retiro' ? 'var(--text-primary)' : 'var(--text-secondary)', fontWeight: 700, cursor: 'pointer' }}>💼 Sangría / Retiro (Dueño)</button>
          </div>
