        <h2 className="modal-title" style={{ color: 'var(--accent-danger)' }}>📅 ¡Alerta de Vencimiento!</h2>
        <p style={{ color: 'var(--text-secondary)', marginBottom: '16px' }}>Productos próximos a vencer o ya vencidos:</p>
