          {[
            { key: 'Enter', label: 'Cobrar — Procesar la venta si estás en la caja' },
            { key: 'Doble Enter', label: 'Procesar Venta — Cobra automáticamente' },
            { key: 'Supr', label: 'Quitar — Elimina el último producto del carrito' },
            { key: 'Esc', label: 'Salir — Cierra modales o limpia la búsqueda' },
          ].map(s => (
            <div key={s.key} style={{ display: 'flex', alignItems: 'center', gap: '16px', background: 'var(--bg-main)', borderRadius: '8px', padding: '10px 16px', marginBottom: '8px' }}>
              <span style={{ background: 'var(--accent-primary)', color: 'white', borderRadius: '6px', padding: '4px 12px', fontWeight: 800, fontSize: '1rem', minWidth: '80px', textAlign: 'center' }}>{s.key}</span>
              <span style={{ color: 'var(--text-secondary)', fontSize: '1rem' }}>{s.label}</span>
            </div>
          ))}
        </div>
        <div style={{ borderTop: '1px solid var(--border-color)', paddingTop: '20px' }}>
          <h3 style={{ fontSize: '1.2rem', marginBottom: '12px', color: 'var(--text-primary)' }}>❓ Preguntas Frecuentes</h3>
          {[
            { q: 'No encuentro un producto', a: 'Escribí el nombre o código de barras en el buscador.' },
            { q: 'Me equivoqué de precio', a: 'Antes de cobrar, tocá "Ajustar total" en la pantalla de pago.' },
            { q: 'No anda el lector de códigos', a: 'Escribí el código a mano y presioná Enter.' },
            { q: 'La pantalla se ve mal', a: 'Presioná F11 para pantalla completa.' },
          ].map((faq, i) => (
            <details key={i} style={{ background: 'var(--bg-main)', borderRadius: '8px', padding: '8px 16px', marginBottom: '8px' }}>
              <summary style={{ fontWeight: 700, cursor: 'pointer', color: 'var(--text-primary)' }}>{faq.q}</summary>
              <p style={{ color: 'var(--text-secondary)', marginTop: '8px', paddingLeft: '8px', borderLeft: '2px solid var(--accent-primary)' }}>{faq.a}</p>
            </details>
          ))}
        </div>
        <div className="modal-actions" style={{ marginTop: '24px' }}><button className="btn btn-modal-confirm" onClick={() => setShowHelp(false)}>Cerrar (Esc)</button></div>
      </div>
    </div>
  );
}

import React from 'react';
import { Icons } from '../ui/Icons';
import { apiPost, apiPut } from '../../services/apiClient';
import { formatMoney } from '../../utils/format';

export default function PaymentPanel({
  cart, total, adjustedTotal, effectiveTotal, subtotal, iva, discount, ivaRate, change, payment, paymentMethod,
  useSplitPayment, splitPayments, setSplitPayments, clientCuit, setClientCuit,
  emitirFactura, setEmitirFactura, tipoFactura, setTipoFactura,
  vueltoEnCuenta, setVueltoEnCuenta, clienteVuelto, setClienteVuelto,
  editingTotal, setEditingTotal, setAdjustedTotal,
  setPayment, setPaymentMethod, setUseSplitPayment,
  isProcessing, setIsCharging, confirmCharge,
  isFiadoOpen, setIsFiadoOpen, lastSale,
  setShowDevolucionItems, setDevolucionQtys,
  setIsCancelConfirm, searchRef,
  autoPrint, setAutoPrint,
  saleConfirm,
  mpQrData, setMpQrData, mpPaymentUrl, setMpPaymentUrl,
  mpLoading, setMpLoading, mpPaymentStatus, setMpPaymentStatus, setMpIntentId,
  businessConfig, setBusinessConfig, addToast, currentOperator,
  promotionSavings,
  handleQuickAdd
}) {
  const ivaActual = String(businessConfig?.iva_rate ?? '0');

  const cambiarIva = async (nuevoIva) => {
    const updated = { ...businessConfig, iva_rate: nuevoIva };
    setBusinessConfig?.(updated); // recalcula al instante
    try {
      await apiPut('/config', updated);
      try { new BroadcastChannel('minegocio-sync').postMessage('config-changed'); } catch {}
      addToast(nuevoIva === '0' ? 'IVA desactivado: precios finales sin discriminar' : `IVA configurado en ${nuevoIva}%`, 'success');
    } catch {
      addToast('No se pudo guardar el IVA', 'error');
    }
  };
  const defaultQuickButtons = [
    { id: 1, name: 'Carga SUBE', price: 1000 },
    { id: 2, name: 'Saldo Virtual', price: 500 },
    { id: 3, name: 'Agua Hervida', price: 100 },
    { id: 4, name: 'Fotocopias', price: 50 },
    { id: 5, name: 'Impresiones', price: 80 },
    { id: 6, name: 'Varios', price: 100 }
  ];
  const [quickButtons, setQuickButtons] = React.useState(() => {
    try { const saved = localStorage.getItem('minegocio_quick_buttons'); return saved ? JSON.parse(saved) : defaultQuickButtons; } catch { return defaultQuickButtons; }
  });
  const [isEditingQuick, setIsEditingQuick] = React.useState(false);

  const saveQuickButtons = (newBtns) => {
    setQuickButtons(newBtns);
    localStorage.setItem('minegocio_quick_buttons', JSON.stringify(newBtns));
  };
  return (
    <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div style={{ background: 'var(--bg-card)', padding: '12px 16px', borderRadius: '12px', border: '1px solid var(--border-color)' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
          <h2 style={{ fontSize: '1.3rem', fontWeight: 800, margin: 0, color: 'var(--text-primary)', letterSpacing: '-0.2px' }}>Resumen</h2>
          <span style={{ background: 'rgba(255,255,255,0.05)', border: '1px solid var(--border-color)', color: 'var(--text-primary)', padding: '4px 12px', borderRadius: '12px', fontSize: '0.8rem', fontWeight: 600 }}>{cart.length} items</span>
        </div>

        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '16px', fontSize: '0.95rem', color: 'var(--text-secondary)' }}>
          <span>Subtotal:</span>
          <span style={{ color: 'var(--text-primary)', fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}>{formatMoney(subtotal)}</span>
        </div>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px', fontSize: '0.95rem', color: 'var(--text-secondary)' }}>
          <span>IVA{iva > 0 ? ` (${ivaRate}%)` : ''}:</span>
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            {iva > 0 && <span style={{ color: 'var(--text-primary)', fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}>{formatMoney(iva)}</span>}
            <select value={ivaActual} onChange={e => cambiarIva(e.target.value)} title="Cambiar el IVA del negocio"
              style={{ background: 'rgba(255,255,255,0.04)', border: '1px solid var(--border-color)', color: ivaActual === '0' ? 'var(--text-secondary)' : 'var(--accent-primary)', borderRadius: '6px', padding: '3px 6px', fontSize: '0.78rem', fontWeight: 700, cursor: 'pointer', outline: 'none' }}>
              <option value="0">No discrimina</option>
              <option value="21">21%</option>
              <option value="10.5">10,5%</option>
              <option value="27">27%</option>
            </select>
          </div>
        </div>
        {discount > 0 && (
          <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '16px', fontSize: '0.95rem', color: 'var(--accent-success)' }}>
            <span>{promotionSavings > 0 ? 'Descuento + Promo:' : 'Descuento:'}</span>
            <span style={{ fontWeight: 600 }}>-{formatMoney(discount)}</span>
          </div>
        )}

        <div style={{ height: '1px', background: 'var(--border-color)', margin: '12px 0' }}></div>

        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', marginBottom: '18px' }}>
          <span style={{ fontSize: '0.78rem', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.6px', color: 'var(--text-secondary)' }}>Total a cobrar</span>
          <span style={{ fontSize: '1.9rem', fontWeight: 800, lineHeight: 1, color: 'var(--text-primary)', fontFamily: 'var(--font-mono)', fontVariantNumeric: 'tabular-nums', letterSpacing: '-0.5px' }}>{formatMoney(adjustedTotal ?? total)}</span>
        </div>

        <button
          onClick={() => setIsCharging(true)}
          disabled={cart.length === 0 || isProcessing}
          style={{ width: '100%', background: 'var(--gradient-primary)', color: 'white', border: 'none', padding: '18px 16px', borderRadius: '12px', fontSize: '1.1rem', fontWeight: 800, cursor: cart.length === 0 ? 'not-allowed' : 'pointer', opacity: cart.length === 0 ? 0.5 : 1, transition: 'all 0.2s', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px', boxShadow: cart.length === 0 ? 'none' : '0 8px 24px rgba(20,187,166,0.3)' }}
        >
          <Icons.Check /> {isProcessing ? 'Procesando...' : 'Procesar Venta'}
        </button>

        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px', marginTop: '16px' }}>
          <button style={{ width: '100%', background: 'rgba(255,255,255,0.02)', border: '1px solid rgba(255,255,255,0.08)', color: 'var(--text-primary)', fontWeight: 700, fontSize: '0.85rem', cursor: 'pointer', padding: '12px', borderRadius: '12px', transition: 'all 0.2s' }} onMouseEnter={e=>e.target.style.background='rgba(255,255,255,0.05)'} onMouseLeave={e=>e.target.style.background='rgba(255,255,255,0.02)'} onClick={() => setIsFiadoOpen(true)}>
            Anotar Fiado
          </button>
          {lastSale && (
            <button style={{ width: '100%', background: 'rgba(239,68,68,0.05)', border: '1px solid rgba(239,68,68,0.15)', color: 'var(--accent-danger)', fontWeight: 700, fontSize: '0.85rem', cursor: 'pointer', padding: '12px', borderRadius: '12px', transition: 'all 0.2s' }} onMouseEnter={e=>e.target.style.background='rgba(239,68,68,0.1)'} onMouseLeave={e=>e.target.style.background='rgba(239,68,68,0.05)'} onClick={() => { setDevolucionQtys({}); setShowDevolucionItems(true); }}>
              ↩ Devolver ítems (última venta)
            </button>
          )}
          {cart.length > 0 && (
            <button style={{ width: '100%', background: 'transparent', border: 'none', color: 'var(--accent-danger)', fontWeight: 700, fontSize: '0.85rem', cursor: 'pointer', padding: '8px' }} onClick={() => setIsCancelConfirm(true)}>
              Anular Venta
            </button>
          )}
        </div>
      </div>

      <div style={{ marginTop: '0', background: 'var(--bg-card)', padding: '12px 16px', borderRadius: '12px', border: '1px solid var(--border-color)' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
          <h3 style={{ margin: 0, fontSize: '0.9rem', color: 'var(--text-primary)', fontWeight: 700 }}>Accesos Rápidos</h3>
          <button onClick={() => setIsEditingQuick(!isEditingQuick)} style={{ background: isEditingQuick ? 'var(--accent-primary)' : 'rgba(255,255,255,0.05)', color: isEditingQuick ? 'white' : 'var(--text-secondary)', border: 'none', borderRadius: '6px', width: '28px', height: '28px', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', transition: 'all 0.2s' }}>
            <Icons.Edit style={{ width: '16px', height: '16px' }} />
          </button>
        </div>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '8px' }}>
          {quickButtons.map((btn, idx) => (
            <div key={btn.id} style={{ background: 'rgba(255,255,255,0.02)', border: '1px solid rgba(255,255,255,0.05)', borderRadius: '8px', padding: '8px', display: 'flex', flexDirection: 'column', gap: '4px', position: 'relative' }}>
              {isEditingQuick ? (
                <>
                  <input type="text" value={btn.name} onChange={e => {
                    const newBtns = [...quickButtons];
                    newBtns[idx].name = e.target.value;
                    saveQuickButtons(newBtns);
                  }} style={{ width: '100%', background: 'rgba(0,0,0,0.2)', border: '1px solid var(--border-color)', color: 'white', fontSize: '0.75rem', padding: '4px', borderRadius: '4px', textAlign: 'center', boxSizing: 'border-box' }} />
                  <input type="number" value={btn.price} onChange={e => {
                    const newBtns = [...quickButtons];
                    newBtns[idx].price = Number(e.target.value);
                    saveQuickButtons(newBtns);
                  }} style={{ width: '100%', background: 'rgba(0,0,0,0.2)', border: '1px solid var(--border-color)', color: 'var(--accent-success)', fontSize: '0.75rem', padding: '4px', borderRadius: '4px', textAlign: 'center', fontFamily: 'var(--font-mono)', boxSizing: 'border-box' }} />
                </>
              ) : (
                <div onClick={() => handleQuickAdd('BTN_' + btn.id, btn.name, btn.price, { is_virtual: true })} style={{ cursor: 'pointer', textAlign: 'center', transition: 'all 0.15s' }} onMouseEnter={e=>e.currentTarget.style.transform='scale(1.02)'} onMouseLeave={e=>e.currentTarget.style.transform='none'}>
                  <div style={{ fontSize: '0.75rem', color: 'var(--text-secondary)', fontWeight: 600, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{btn.name}</div>
                  <div style={{ fontSize: '0.85rem', color: 'var(--accent-success)', fontWeight: 800, fontFamily: 'var(--font-mono)' }}>${btn.price.toLocaleString('es-AR')}</div>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>

      <div style={{ marginTop: '0', display: 'flex', justifyContent: 'center' }}>
        <label style={{ display: 'flex', alignItems: 'center', gap: '8px', color: 'var(--text-secondary)', fontSize: '0.85rem', cursor: 'pointer', fontWeight: 600 }}>
          <input type="checkbox" checked={autoPrint} onChange={e => setAutoPrint(e.target.checked)} style={{ width: '16px', height: '16px' }} />
          Imprimir ticket automáticamente tras cobrar
        </label>
      </div>

      {saleConfirm && (
        <div style={{ position: 'absolute', inset: 0, background: 'rgba(34, 197, 94, 0.95)', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', zIndex: 10, borderRadius: '16px' }}>
          <div style={{ background: 'white', color: 'var(--accent-success)', borderRadius: '50%', width: 100, height: 100, display: 'flex', alignItems: 'center', justifyContent: 'center', marginBottom: 24 }}>
            <Icons.Check />
          </div>
          <h2 style={{ fontSize: '3rem', color: 'white', fontWeight: 800 }}>¡VENTA OK!</h2>
          <p style={{ fontSize: '1.5rem', color: 'white', opacity: 0.9, marginTop: 16 }}>Imprimiendo ticket...</p>
        </div>
      )}
    </div>
  );
}

import React from 'react';
import { Icons } from '../ui/Icons';

function ResumenModal({ showResumen, setShowResumen, resumenData, businessConfig, addToast }) {
  if (!showResumen) return null;

  const fmt = (n) => '$' + (n || 0).toLocaleString('es-AR', { minimumFractionDigits: 0 });

  const rows = [
    ['💰 Total Vendido',          fmt(resumenData?.total_vendido),       'var(--accent-success)'],
    ['🎫 Cantidad de Tickets',    String(resumenData?.total_tickets || 0), ''],
    ['📊 Ticket Promedio',        fmt((resumenData?.total_vendido || 0) / Math.max(1, resumenData?.total_tickets || 1)), ''],
    ['💵 Efectivo en Caja',       fmt(resumenData?.total_efectivo),      'var(--accent-primary)'],
    ['💳 Tarjeta Débito',         fmt(resumenData?.total_tarjeta),       'var(--text-primary)'],
    ['🏦 Transferencias',         fmt(resumenData?.total_transferencia), 'var(--text-primary)'],
    ['📋 Fiado Pendiente',        fmt(resumenData?.total_fiado),         'var(--accent-warning)'],
  ];

  return (
    <div className="modal-overlay" onClick={() => setShowResumen(false)}>
      <div className="modal-content" onClick={e => e.stopPropagation()} style={{ maxWidth: '500px', width: '100%' }}>
        <h2 className="modal-title" style={{ fontSize: '1.4rem', display: 'flex', alignItems: 'center', gap: '8px' }}>
          <Icons.Activity /> Resumen del Día
        </h2>
        <p style={{ color: 'var(--text-secondary)', fontSize: '0.85rem', margin: '4px 0 16px' }}>
          {new Date().toLocaleDateString('es-AR', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
        </p>

        {resumenData && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            {rows.map(([label, val, color]) => (
              <div key={label} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '10px 14px', background: 'var(--bg-main)', borderRadius: '8px' }}>
                <span style={{ color: 'var(--text-secondary)', fontSize: '0.9rem' }}>{label}</span>
                <span style={{ fontWeight: 800, fontSize: '1.2rem', fontFamily: 'var(--font-mono)', color: color || 'var(--text-primary)' }}>{val}</span>
              </div>
            ))}
          </div>
        )}

        <div className="modal-actions" style={{ marginTop: '20px' }}>
          <button className="btn btn-modal-cancel" onClick={() => setShowResumen(false)}>Cerrar</button>
          <button className="btn btn-modal-confirm" onClick={() => {
            const w = window.open('', '_blank');
            if (!w) { addToast('Permití ventanas emergentes para imprimir', 'error'); return; }
            const d = w.document;
            d.write('<!DOCTYPE html><html><head><meta charset="utf-8"><title>Resumen</title><style>body{font-family:monospace;font-size:14px;padding:40px}h1,h2{text-align:center}table{width:100%;border-collapse:collapse;margin-top:20px}td{padding:10px 12px;border-bottom:1px solid #ddd}.val{text-align:right;font-weight:bold}footer{text-align:center;margin-top:40px;color:#999;font-size:11px}</style></head><body></body></html>');
            d.close();
            const h1 = d.createElement('h1'); h1.textContent = businessConfig?.nombre || 'Mi Negocio'; d.body.appendChild(h1);
            const h2 = d.createElement('h2'); h2.textContent = new Date().toLocaleDateString('es-AR', { weekday:'long', year:'numeric', month:'long', day:'numeric' }); d.body.appendChild(h2);
            const table = d.createElement('table');
            const tbody = d.createElement('tbody');
            rows.forEach(([label, val]) => {
              const tr = d.createElement('tr');
              const td1 = d.createElement('td'); td1.textContent = label; tr.appendChild(td1);
              const td2 = d.createElement('td'); td2.textContent = val; td2.className = 'val'; tr.appendChild(td2);
              tbody.appendChild(tr);
            });
            table.appendChild(tbody); d.body.appendChild(table);
            const footer = d.createElement('footer'); footer.textContent = 'Generado por MiNegocio'; d.body.appendChild(footer);
            setTimeout(() => { w.focus(); w.print(); }, 300);
          }} style={{ background: 'var(--accent-primary)' }}>
            <Icons.Printer /> Imprimir Resumen
          </button>
        </div>
      </div>
    </div>
  );
}

export default ResumenModal;

import React, { useMemo, useState } from 'react';
import { Icons } from '../ui/Icons';
import AddAmountModal from './AddAmountModal';

export default function SearchBar({
  search, setSearch, searchRef, searchError, flash,
  productsDB, handleQuickAdd, setShowPriceCheck, addToast, handleEmptyEnter
}) {
  const [showAddAmountModal, setShowAddAmountModal] = useState(false);
  const autocomplete = useMemo(() => {
    if (!search.trim() || !productsDB) return [];
    return productsDB
      .filter(p => p.code?.startsWith(search) || p.name?.toLowerCase().startsWith(search.toLowerCase()))
      .slice(0, 5);
  }, [search, productsDB]);

  return (
    <div style={{ background: 'var(--bg-card)', padding: '12px 16px', borderRadius: '12px', border: '1px solid var(--border-color)' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '16px' }}>
        <div>
          <h2 style={{ fontSize: '1.3rem', fontWeight: 800, margin: '0 0 2px 0', letterSpacing: '-0.2px' }}>Buscar Producto</h2>
          <p style={{ color: 'var(--text-secondary)', fontSize: '0.85rem', margin: 0 }}>Escanee código de barras o escriba el nombre del producto</p>
        </div>

        <div style={{ display: 'flex', gap: '8px' }}>
          <button onClick={() => setShowPriceCheck(true)} style={{ background: 'var(--bg-hover)', color: 'var(--text-primary)', border: '1px solid var(--border-color)', padding: '8px 12px', borderRadius: '8px', fontSize: '0.85rem', fontWeight: 600, cursor: 'pointer', transition: 'all 0.2s' }} onMouseEnter={e => e.target.style.background='rgba(255,255,255,0.1)'} onMouseLeave={e => e.target.style.background='var(--bg-hover)'}>
            Consultar Precio
          </button>
          <button onClick={() => setShowAddAmountModal(true)} style={{ background: 'var(--bg-hover)', color: 'var(--text-primary)', border: '1px solid var(--border-color)', padding: '8px 12px', borderRadius: '8px', fontSize: '0.85rem', fontWeight: 600, cursor: 'pointer', transition: 'all 0.2s' }} onMouseEnter={e => e.target.style.background='rgba(255,255,255,0.1)'} onMouseLeave={e => e.target.style.background='var(--bg-hover)'}>
            Agregar Monto
          </button>
        </div>
      </div>

      <div className={`search-bar ${flash ? 'flash' : ''}`} style={{ margin: 0, position: 'relative', borderColor: searchError ? 'var(--accent-danger)' : 'var(--border-color)', borderWidth: searchError ? '2px' : '1px' }}>
        <Icons.Search />
        <input
          ref={searchRef}
          type="text"
          placeholder="Buscar producto... (Enter para agregar)"
          aria-label="Buscar producto por código o nombre"
          value={search}
          onChange={e => {
            setSearch(e.target.value);
            if (e.target.value.trim().length > 0 && e.target.value.trim().length < 3) {
              const term = e.target.value.trim();
              const codeMatch = autocomplete.find(p => p.code === term);
              if (codeMatch) { handleQuickAdd(codeMatch.code, codeMatch.name, codeMatch.price); setSearch(''); searchRef.current?.focus(); }
            }
          }}
          onKeyDown={e => {
            if (e.key === 'ArrowDown') { e.preventDefault(); document.getElementById('autocomplete-0')?.focus(); }
            if (e.key === 'Enter') {
              const term = e.target.value.trim();
              if (!term) {
                if (handleEmptyEnter) handleEmptyEnter();
                return;
              }
              // Detectar código de barras de balanza (EAN-13 que empieza con "20")
              if (/^20\d{11}$/.test(term)) {
                const productCode = term.slice(2, 7);
                const priceCents = parseInt(term.slice(7, 12), 10);
                const scalePrice = priceCents / 100;
                const match = productsDB?.find(p => p.code === productCode);
                if (match) {
                  addToast(`Balanza: ${match.name} - $${scalePrice.toFixed(2)}`, 'info');
                  handleQuickAdd(match.code, match.name, scalePrice);
                  setSearch('');
                  searchRef.current?.focus();
                  return;
                } else {
                  addToast(`Código de balanza ${productCode} no encontrado`, 'error');
                  setSearch('');
                  return;
                }
              }
              // Búsqueda normal por código exacto
              const exact = productsDB?.find(p => p.code === term);
              if (exact) {
                handleQuickAdd(exact.code, exact.name, exact.price);
                setSearch('');
                searchRef.current?.focus();
              } else if (autocomplete.length === 1) {
                handleQuickAdd(autocomplete[0].code, autocomplete[0].name, autocomplete[0].price);
                setSearch('');
                searchRef.current?.focus();
              }
            }
          }}
          autoFocus
        />
        {search.trim().length > 0 && autocomplete.length > 0 && (
          <div role="listbox" aria-label="Resultados de búsqueda" style={{ position: 'absolute', top: '100%', left: 0, right: 0, background: 'var(--bg-card)', border: '1px solid var(--border-color)', borderRadius: '8px', zIndex: 100, marginTop: '4px', boxShadow: '0 4px 12px rgba(30,58,95,0.2)' }}>
            {autocomplete.map((p, i) => (
              <button
                id={`autocomplete-${i}`}
                key={p.id}
                onClick={() => { handleQuickAdd(p.code, p.name, p.price); setSearch(''); searchRef.current?.focus(); }}
                onKeyDown={e => {
                  if (e.key === 'Enter') { handleQuickAdd(p.code, p.name, p.price); setSearch(''); searchRef.current?.focus(); }
                  if (e.key === 'ArrowDown') document.getElementById(`autocomplete-${i + 1}`)?.focus();
                  if (e.key === 'ArrowUp') { if (i === 0) searchRef.current?.focus(); else document.getElementById(`autocomplete-${i - 1}`)?.focus(); }
                }}
                style={{ display: 'flex', justifyContent: 'space-between', width: '100%', padding: '12px 16px', background: 'transparent', border: 'none', borderBottom: '1px solid var(--border-color)', color: 'var(--text-primary)', cursor: 'pointer', textAlign: 'left', outline: 'none' }}
                onFocus={e => e.target.style.background = 'var(--bg-hover)'}
                onBlur={e => e.target.style.background = 'transparent'}
                onMouseEnter={e => e.target.style.background = 'var(--bg-hover)'}
                onMouseLeave={e => e.target.style.background = 'transparent'}
              >
                <span style={{ fontWeight: 600 }}>{p.name}</span>
                <div style={{ display: 'flex', gap: '16px', color: 'var(--text-secondary)' }}>
                  <span>${p.price}</span>
                  <span style={{ color: p.stock > 0 ? 'var(--accent-success)' : 'var(--accent-danger)' }}>Stock: {p.stock}</span>
                </div>
              </button>
            ))}
          </div>
        )}
      </div>
      <AddAmountModal show={showAddAmountModal} setShow={setShowAddAmountModal} handleQuickAdd={handleQuickAdd} />
    </div>
  );
}

