import React from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { Icons } from '../ui/Icons';
import Tooltip from '../ui/Tooltip';
import LogoPrincipal from '../../assets/images/MiNegocio_transparente_real.png';
import { usePanelContext } from '../../context/PanelContext';

const PLAN_WEIGHT = { trial: 1, simple: 1, pro: 2, ia: 3 };

const NAV_ITEMS = [
  {
    category: 'OPERACIÓN',
    items: [
      { label: 'Inicio', path: '/panel/inicio', icon: 'Home', roles: ['admin', 'manager', 'operator'] },
      { label: 'Punto de Venta', path: '/panel/ventas', icon: 'ShoppingCart', roles: ['admin', 'manager', 'operator'] },
      { label: 'Compras', path: '/panel/compras', icon: 'Truck', roles: ['admin', 'manager'], minPlan: 'simple' },
      { label: 'Fiados', path: '/panel/clientes', icon: 'Book', roles: ['admin', 'manager', 'operator'] },
    ],
  },
  {
    category: 'CATÁLOGO',
    items: [
      { label: 'Inventario', path: '/panel/inventario', icon: 'Box', roles: ['admin', 'manager'] },
      { label: 'Catálogo Web', path: '/panel/catalogo-web', icon: 'Edit', roles: ['admin', 'manager'], minPlan: 'pro' },
      { label: 'Proveedores', path: '/panel/proveedores', icon: 'Truck', roles: ['admin', 'manager'], minPlan: 'simple' },
    ],
  },
  {
    category: 'ANÁLISIS',
    roles: ['admin'],
    items: [
      { label: 'Reportes', path: '/panel/reportes', icon: 'Chart' },
      { label: 'Promociones', path: '/panel/promociones', icon: 'Tag' },
      { label: 'Sugerencias IA', path: '/panel/recomendaciones', icon: 'AI', minPlan: 'ia' },
    ],
  },
  {
    category: 'SISTEMA',
    roles: ['admin'],
    items: [
      { label: 'Auditoría', path: '/panel/auditoria', icon: 'Clipboard', minPlan: 'pro' },
      { label: 'Configuración', path: '/panel/configuracion', icon: 'Settings' },
      { label: 'Usuarios', path: '/panel/usuarios', icon: 'Users' },
    ],
  },
  {
    category: 'SOPORTE',
    items: [
      { label: 'Soporte', path: '/panel/soporte', icon: 'Help' },
      { label: 'Mi Plan', path: '/panel/plan', icon: 'Crown' },
    ],
  },
];

const Home = () => <svg width="20" height="20" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="2"><path strokeLinecap="round" strokeLinejoin="round" d="M3 9.5L12 3l9 6.5V20a1 1 0 01-1 1h-5v-6H9v6H4a1 1 0 01-1-1V9.5z" /></svg>;

const ICON_MAP = {
  Home,
  ShoppingCart: Icons.ShoppingCart,
  Truck: Icons.Truck,
  Book: Icons.Book,
  Box: Icons.Box,
  Edit: Icons.Edit,
  Users: Icons.Users,
  Lock: Icons.Lock,
  Chart: Icons.Chart,
  Tag: Icons.Tag,
  AI: Icons.Sparkles,
  Clipboard: Icons.Clipboard,
  Settings: Icons.Settings,
  Help: Icons.Help,
  Crown: Icons.Crown,
};

export default function Sidebar({
  currentOperator, pendingSync, setShowPendingModal,
  todaySalesTotal, setShowResumen, setShowEgreso, setIsClosingCaja, currentTurnId, turnOpenedAt, initialCash
}) {
  const navigate = useNavigate();
  const location = useLocation();
  const { currentPlan, addToast } = usePanelContext();
  const currentPath = location.pathname;

  const role = currentOperator?.role || 'admin';

  const isActive = (path) => currentPath === path;

  return (
    <aside className="sidebar">
      <div className="brand" style={{ cursor: 'pointer', display: 'flex', justifyContent: 'center', padding: '4px 0', borderBottom: 'none', boxShadow: 'none' }} onClick={() => navigate('/panel/ventas')}>
        <img src={LogoPrincipal} alt="MiNegocio" style={{ width: '80%', maxWidth: '140px', height: 'auto', objectFit: 'contain' }} />
      </div>

      <nav className="nav-menu" style={{ overflowY: 'auto', flex: 1 }}>
        {NAV_ITEMS.map((section) => {
          if (section.roles && !section.roles.includes(role)) return null;
          const items = section.items.filter(item => {
            if (item.roles && !item.roles.includes(role)) return false;
            return true;
          });

          if (items.length === 0) return null;

          return (
            <React.Fragment key={section.category}>
              <div className="nav-section-label">{section.category}</div>
              {items.map((item) => {
                const isLocked = item.minPlan && PLAN_WEIGHT[currentPlan] < PLAN_WEIGHT[item.minPlan];
                return (
                  <div
                    key={item.path}
                    className={`nav-item ${isActive(item.path) && !isLocked ? 'active' : ''}`}
                    onClick={() => navigate(item.path)}
                    style={{
                      ...(item.label === 'Punto de Venta' ? { fontSize: '0.9rem', padding: '10px 14px', marginBottom: '4px' } : {}),
                      opacity: isLocked ? 0.5 : 1,
                      cursor: isLocked ? 'not-allowed' : 'pointer'
                    }}
                  >
                    <div style={{ display: 'flex', alignItems: 'center', gap: '10px', flex: 1 }}>
                      {ICON_MAP[item.icon] ? React.createElement(ICON_MAP[item.icon], item.label === 'Punto de Venta' ? { style: { width: 22, height: 22 } } : {}) : <span style={{ width: 22, height: 22, display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Icons.File /></span>}
                      {item.label}
                    </div>
                  </div>
                );
              })}
            </React.Fragment>
          );
        })}
      </nav>

      <div style={{ padding: '10px', borderTop: '1px solid var(--border-color)', background: 'var(--gradient-card)', backdropFilter: 'blur(8px)', marginTop: 'auto' }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '6px' }}>
          <span style={{ fontSize: '0.8rem', fontWeight: 700, display: 'flex', alignItems: 'center', gap: '6px', color: 'var(--text-primary)' }}>
            <Icons.Lock style={{ width: 14, height: 14 }} /> Mi Caja
          </span>
          {currentTurnId ? (
            <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: '2px' }}>
              <span style={{ background: 'var(--gradient-primary)', color: 'white', padding: '2px 6px', borderRadius: '6px', fontSize: '0.65rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.5px' }}>Abierta</span>
              {turnOpenedAt && (() => {
                const hours = Math.max(0, (Date.now() - new Date(turnOpenedAt).getTime()) / 3600000);
                const h = Math.floor(hours);
                const m = Math.floor((hours - h) * 60);
                return (
                  <span style={{ color: 'var(--text-secondary)', fontSize: '0.65rem', fontWeight: 500 }}>
                    {h > 0 ? `${h}h ${m}m` : `${m}m`}
                  </span>
                );
              })()}
            </div>
          ) : (
            <span style={{ background: 'rgba(239, 68, 68, 0.2)', color: 'var(--accent-danger)', padding: '2px 6px', borderRadius: '6px', fontSize: '0.65rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.5px' }}>Cerrada</span>
          )}
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontWeight: 700 }}>
            <span style={{ color: 'var(--text-secondary)', fontSize: '0.75rem' }}>Vendido hoy</span>
            <span style={{ color: 'var(--accent-success)', fontSize: '1.1rem', fontFamily: 'var(--font-mono)', fontWeight: 800 }}>
              ${(todaySalesTotal || 0).toLocaleString('es-AR')}
            </span>
          </div>
          {initialCash > 0 && (
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontWeight: 700 }}>
              <span style={{ color: 'var(--text-secondary)', fontSize: '0.75rem' }}>Caja inicial</span>
              <span style={{ color: 'var(--text-secondary)', fontSize: '0.8rem', fontFamily: 'var(--font-mono)', fontWeight: 600 }}>
                ${(initialCash || 0).toLocaleString('es-AR')}
              </span>
            </div>
          )}
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontWeight: 700 }}>
            <span style={{ color: 'var(--text-secondary)', fontSize: '0.75rem' }}>Operador</span>
            <span style={{ color: 'var(--text-primary)', fontWeight: 800, fontSize: '0.75rem' }}>{currentOperator?.name || 'Invitado'}</span>
          </div>
          {pendingSync > 0 && (
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontWeight: 700 }}>
              <span style={{ color: 'var(--accent-warning)', fontSize: '0.85rem', cursor: 'pointer' }} onClick={() => setShowPendingModal(true)}>Pendientes</span>
              <span style={{ color: 'var(--accent-warning)', fontWeight: 800, fontSize: '0.85rem' }}>{pendingSync}</span>
            </div>
          )}
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: '4px', marginTop: '10px' }}>
          <Tooltip text="Registrar salida de efectivo" block>
            <button onClick={() => setShowEgreso(true)} style={{ width: '100%', background: 'rgba(245, 158, 11, 0.1)', border: '1px solid var(--border-color)', color: 'var(--accent-warning)', padding: '6px 10px', borderRadius: '8px', fontWeight: 700, cursor: 'pointer', fontSize: '0.75rem', transition: 'all 0.2s', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '6px' }}>
              <Icons.DollarSign style={{ width: 14, height: 14 }} /> Registrar Egreso
            </button>
          </Tooltip>
          <Tooltip text="Ver ventas del día" block>
            <button onClick={() => setShowResumen(true)} style={{ width: '100%', background: 'rgba(20,187,166, 0.1)', border: '1px solid var(--border-color)', color: 'var(--accent-primary)', padding: '6px 10px', borderRadius: '8px', fontWeight: 700, cursor: 'pointer', fontSize: '0.75rem', transition: 'all 0.2s', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '6px' }}>
              <Icons.Chart style={{ width: 14, height: 14 }} /> Resumen del Día
            </button>
          </Tooltip>
          {currentTurnId ? (
            <Tooltip text="F2 - Cerrar turno y cuadrar caja" block>
              <button onClick={() => setIsClosingCaja(true)} style={{ width: '100%', background: 'rgba(239, 68, 68, 0.1)', border: '1px solid var(--border-color)', color: 'var(--accent-danger)', padding: '6px 10px', borderRadius: '8px', fontWeight: 700, cursor: 'pointer', fontSize: '0.75rem', transition: 'all 0.2s', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '6px' }}>
                <Icons.Lock style={{ width: 14, height: 14 }} /> Cerrar Turno
              </button>
            </Tooltip>
          ) : (
            <Tooltip text="Abrir caja para vender" block>
              <button onClick={() => { localStorage.setItem('minegocio_onboarding_pending', 'true'); window.location.reload(); }} style={{ width: '100%', background: 'var(--gradient-primary)', border: 'none', color: 'white', padding: '8px 10px', borderRadius: '8px', fontWeight: 800, cursor: 'pointer', fontSize: '0.8rem', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '6px', boxShadow: '0 4px 12px rgba(20, 187, 166, 0.3)' }}>
                Abrir Caja
              </button>
            </Tooltip>
          )}
        </div>

        {/* Legal footer */}
        <div style={{ marginTop: 12, paddingTop: 10, borderTop: '1px solid var(--border-color)', display: 'flex', justifyContent: 'center', gap: 12 }}>
          <a href="/terminos" target="_blank" rel="noopener noreferrer" style={{ fontSize: '0.65rem', color: 'var(--text-secondary)', textDecoration: 'none', opacity: 0.6 }} onMouseEnter={e => e.target.style.opacity = '1'} onMouseLeave={e => e.target.style.opacity = '0.6'}>Términos</a>
          <span style={{ fontSize: '0.65rem', color: 'var(--text-secondary)', opacity: 0.3 }}>·</span>
          <a href="/privacidad" target="_blank" rel="noopener noreferrer" style={{ fontSize: '0.65rem', color: 'var(--text-secondary)', textDecoration: 'none', opacity: 0.6 }} onMouseEnter={e => e.target.style.opacity = '1'} onMouseLeave={e => e.target.style.opacity = '0.6'}>Privacidad</a>
        </div>
      </div>
    </aside>
  );
}

import React from 'react';

export default function StockAlertsModal({ stockAlerts, setStockAlerts }) {
  if (!stockAlerts || !((stockAlerts.stock?.total > 0 || stockAlerts.margin?.total > 0))) return null;
  return (
    <div className="modal-overlay" onClick={() => setStockAlerts(null)}>
      <div className="modal-content" onClick={e => e.stopPropagation()} style={{ maxWidth: '600px' }}>
        <h2 className="modal-title" style={{ color: 'var(--accent-warning)' }}>⚠️ ¡Alertas Importantes del Negocio!</h2>
        <div style={{ maxHeight: '400px', overflowY: 'auto' }}>
          {stockAlerts.stock?.total > 0 && (<div style={{ marginBottom: '24px' }}>
            <h3 style={{ color: 'var(--text-primary)', marginBottom: '8px', fontSize: '1.1rem' }}>📦 Stock Crítico</h3>
            <div style={{ background: 'rgba(30,58,95,0.2)', padding: '12px', borderRadius: '8px' }}>
              {stockAlerts.stock.empty?.map(p => <div key={p.id} style={{ display: 'flex', justifyContent: 'space-between', padding: '6px 0', borderBottom: '1px solid rgba(255,255,255,0.05)', color: 'var(--accent-danger)' }}><span>{p.name}</span><strong>SIN STOCK</strong></div>)}
              {stockAlerts.stock.low?.map(p => <div key={p.id} style={{ display: 'flex', justifyContent: 'space-between', padding: '6px 0', borderBottom: '1px solid rgba(255,255,255,0.05)', color: 'var(--accent-warning)' }}><span>{p.name}</span><span>Bajo Mínimo ({p.stock} de {p.min_stock})</span></div>)}
            </div>
          </div>)}
          {stockAlerts.margin?.total > 0 && (<div>
            <h3 style={{ color: 'var(--text-primary)', marginBottom: '8px', fontSize: '1.1rem' }}>💰 Alertas de Rentabilidad</h3>
            <p style={{ color: 'var(--text-secondary)', fontSize: '0.85rem', marginBottom: '8px' }}>Productos que estás vendiendo a pérdida.</p>
            <div style={{ background: 'rgba(30,58,95,0.2)', padding: '12px', borderRadius: '8px' }}>
              {stockAlerts.margin.no_cost?.map(p => <div key={p.id} style={{ display: 'flex', justifyContent: 'space-between', padding: '6px 0', borderBottom: '1px solid rgba(255,255,255,0.05)', color: 'var(--accent-danger)' }}><span>{p.name}</span><strong>COSTO $0</strong></div>)}
              {stockAlerts.margin.low_margin?.map(p => { const margin = ((p.price - p.cost_price) / p.cost_price * 100).toFixed(1); return <div key={p.id} style={{ display: 'flex', justifyContent: 'space-between', padding: '6px 0', borderBottom: '1px solid rgba(255,255,255,0.05)', color: 'var(--accent-warning)' }}><span>{p.name}</span><span>Margen muy bajo ({margin}%)</span></div>; })}
            </div>
          </div>)}
        </div>
        <div className="modal-actions" style={{ marginTop: '20px' }}><button className="btn btn-modal-confirm" onClick={() => setStockAlerts(null)}>Entendido</button></div>
      </div>
    </div>
  );
}

import React from 'react';

export default function ToastContainer({ toasts }) {
  return (
    <div role="alert" aria-live="polite" style={{ position:'fixed', top:'24px', right:'24px', display:'flex', flexDirection:'column', gap:'12px', zIndex:9999, pointerEvents:'none', maxWidth:'500px' }}>
      {toasts.map(t => (
        <div key={t.id} style={{ background: t.type==='success'?'var(--accent-success)':(t.type==='error'?'var(--accent-danger)':'var(--bg-card)'), color:'white', padding:'20px 32px', borderRadius:'12px', boxShadow:'0 10px 25px rgba(30,58,95,0.5)', fontWeight:700, fontSize:'1.25rem', animation:'slideInRight 0.3s ease', pointerEvents:'auto' }}>
          {t.message}
        </div>
      ))}
    </div>
  );
}

import React from 'react';

export default function TopBar({ currentOperator, sucursales, currentSucursalId, setCurrentSucursalId, backendStatus, addToast, setShowHelp }) {
  const isCashier = currentOperator?.role === 'cashier' || currentOperator?.role === 'employee';

  return (
    <header className="topbar" style={{ padding: '16px 24px 0 24px', background: 'transparent', borderBottom: 'none', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
      <div className="topbar-title">
        <div style={{ display: 'flex', flexDirection: 'column' }}>
          <span style={{ fontSize: '1.6rem', fontWeight: 800, color: 'var(--text-primary)', letterSpacing: '-0.5px' }}>Punto de Venta</span>
          <span style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', fontWeight: 500, marginTop: '2px' }}>Sistema POS - {currentOperator?.name || 'Dueño'}</span>
        </div>

        {sucursales.length > 1 && !isCashier && (
          <select value={currentSucursalId} onChange={e => setCurrentSucursalId(parseInt(e.target.value))}
            style={{ marginLeft: '24px', background: 'var(--bg-card)', border: '1px solid var(--border-color)', color: 'var(--text-primary)', padding: '8px 16px', borderRadius: '8px', fontSize: '0.9rem', fontWeight: 600, cursor: 'pointer', outline: 'none' }}>
            {sucursales.map(s => <option key={s.id} value={s.id}>🏪 {s.name}</option>)}
          </select>
        )}
      </div>
      <div className="status-indicators" style={{ display: 'flex', gap: '12px', alignItems: 'center' }}>
        <button onClick={() => setShowHelp?.(true)} style={{ background: 'transparent', color: 'var(--text-primary)', border: '1px solid var(--border-color)', padding: '10px 16px', borderRadius: '8px', fontSize: '0.95rem', cursor: 'pointer', fontWeight: 600, transition: 'all 0.2s' }} onMouseEnter={e=>e.target.style.background='rgba(255,255,255,0.05)'} onMouseLeave={e=>e.target.style.background='transparent'}>
          Ayuda
        </button>

        {backendStatus?.status === 'ok' ? (
          <span style={{ background: 'rgba(16, 185, 129, 0.1)', color: '#10B981', border: '1px solid rgba(16, 185, 129, 0.2)', padding: '6px 16px', borderRadius: '8px', fontSize: '0.85rem', fontWeight: 700, marginLeft: '8px' }}>
            <span style={{ background: '#10B981', boxShadow: '0 0 10px #10B981', marginRight: '8px', width: 8, height: 8, borderRadius: '50%', display: 'inline-block' }}></span>
            Conectado
          </span>
        ) : (
          <span style={{ background: 'rgba(239, 68, 68, 0.1)', color: '#EF4444', border: '1px solid rgba(239, 68, 68, 0.2)', padding: '6px 16px', borderRadius: '8px', fontSize: '0.85rem', fontWeight: 700, marginLeft: '8px' }}>
            <span style={{ background: '#EF4444', boxShadow: '0 0 10px #EF4444', marginRight: '8px', width: 8, height: 8, borderRadius: '50%', display: 'inline-block' }}></span>
            Sin conexion
          </span>
        )}

        {(() => {
          const isPreview = new URLSearchParams(window.location.search).get('preview') === 'true' || localStorage.getItem('saas_mode') === 'true';
          if (isPreview) {
            return (
              <button onClick={() => { localStorage.removeItem('saas_token'); localStorage.removeItem('saas_mode'); window.location.href = '/'; }} style={{ background: 'var(--gradient-primary)', color: 'white', border: 'none', padding: '10px 16px', borderRadius: '8px', fontSize: '0.95rem', fontWeight: 700, cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '6px' }}>
                Salir de Preview
              </button>
            );
          }
          return (
            <button onClick={() => { localStorage.removeItem('saas_token'); window.location.href = '/'; }} style={{ background: 'transparent', border: '1px solid rgba(255,255,255,0.2)', color: 'var(--text-secondary)', padding: '10px 16px', borderRadius: '8px', fontSize: '0.95rem', fontWeight: 700, cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '6px' }}>
               Cerrar Sesión
            </button>
          );
        })()}
      </div>
    </header>
  );
}

import React from 'react';
import { Icons } from './Icons';

export default class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true, error };
  }

  componentDidCatch(error, info) {
    console.error('ErrorBoundary caught:', error, info);
  }

  handleReset = () => {
    this.setState({ hasError: false, error: null });
  };

  render() {
    if (this.state.hasError) {
      return (
        <div style={{
          display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
          height: '100vh', padding: 40, textAlign: 'center', background: 'var(--bg-main)',
        }}>
          <div style={{ fontSize: '4rem', marginBottom: 16, color: 'var(--accent-danger)' }}>
            <svg width="64" height="64" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
            </svg>
          </div>
          <h2 style={{ fontSize: '1.8rem', fontWeight: 800, margin: '0 0 8px 0', color: 'var(--text-primary)' }}>
            Algo salió mal
          </h2>
          <p style={{ color: 'var(--text-secondary)', fontSize: '1rem', margin: '0 0 24px 0', maxWidth: 400 }}>
            Ocurrió un error inesperado al cargar esta sección. No se perdieron datos.
          </p>
          <div style={{ display: 'flex', gap: 12 }}>
            <button onClick={this.handleReset}
              style={{
                background: 'var(--gradient-primary)', color: 'white', border: 'none',
                padding: '12px 32px', borderRadius: 10, fontWeight: 700, fontSize: '1rem',
                cursor: 'pointer',
              }}>
              Reintentar
            </button>
            <button onClick={() => window.location.href = '/panel/ventas'}
              style={{
                background: 'var(--bg-card)', color: 'var(--text-primary)', border: '1px solid var(--border-color)',
                padding: '12px 32px', borderRadius: 10, fontWeight: 700, fontSize: '1rem',
                cursor: 'pointer',
              }}>
              Volver al inicio
            </button>
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}

