  Download: () => <svg width="24" height="24" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>,
  Wifi: () => <svg width="24" height="24" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8.111 16.404a5.5 5.5 0 017.778 0M12 20h.01m-7.08-7.071c3.904-3.905 10.236-3.905 14.141 0M1.394 9.393c5.857-5.858 15.355-5.858 21.213 0" /></svg>,
  Package: () => <svg width="24" height="24" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" /></svg>,
};

function AlertAccordion({ icon: Icon, title, subtitle, data, isOpen, onToggle, columns, renderRow }) {
  return (
    <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border-color)', borderRadius: '8px', marginBottom: '6px', overflow: 'hidden' }}>
      <div onClick={onToggle} style={{ padding: '5px 12px', display: 'flex', alignItems: 'center', justifyContent: 'space-between', cursor: 'pointer', transition: 'background 0.2s' }} onMouseEnter={e=>e.currentTarget.style.background='var(--bg-hover)'} onMouseLeave={e=>e.currentTarget.style.background='transparent'}>
        <div style={{ display: 'flex', alignItems: 'baseline', gap: '8px' }}>
          <div style={{ color: 'var(--text-secondary)', transform: 'scale(0.6)', alignSelf: 'center' }}><Icon /></div>
          <div style={{ fontWeight: 700, color: 'var(--text-primary)', fontSize: '0.82rem' }}>{title}</div>
          <div style={{ color: 'var(--text-secondary)', fontSize: '0.7rem' }}>{subtitle}</div>
        </div>
        <div style={{ color: 'var(--text-secondary)' }}>
          {isOpen ? <Icons.ChevronUp /> : <Icons.ChevronDown />}
        </div>
      </div>
      {isOpen && data.length > 0 && (
        <div style={{ borderTop: '1px solid var(--border-color)', overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
            <thead>
              <tr style={{ borderBottom: '1px solid var(--border-color)' }}>
                {columns.map((c, i) => <th key={i} style={{ padding: '8px 16px', color: 'var(--text-primary)', fontSize: '0.8rem', fontWeight: 600 }}>{c}</th>)}
              </tr>
            </thead>
            <tbody>
              {data.map((item, idx) => (
                <tr key={idx} style={{ borderBottom: '1px solid rgba(255,255,255,0.03)' }}>
                  {renderRow(item)}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

function ToggleSwitch({ isOn }) {
  return (
    <div style={{ width: '36px', height: '20px', background: isOn ? 'var(--gradient-primary)' : 'rgba(255,255,255,0.1)', borderRadius: '20px', position: 'relative', cursor: 'pointer', transition: 'all 0.3s' }}>
      <div style={{ width: '16px', height: '16px', background: 'white', borderRadius: '50%', position: 'absolute', top: '2px', left: isOn ? '18px' : '2px', transition: 'all 0.3s' }} />
    </div>
  );
}

const CACHE_KEY = 'minegocio_inventario_cache';

function loadCache() {
  try {
    const raw = localStorage.getItem(CACHE_KEY);
    if (raw) return JSON.parse(raw);
  } catch (e) { console.error(e) }
  return null;
}

function saveCache(products, deadStock) {
  try {
    const limited = products.slice(0, 2000);
    const payload = JSON.stringify({ products: limited, deadStock, ts: Date.now() });
    if (payload.length > 4_000_000) {
      const furtherLimited = products.slice(0, Math.floor(2000 * 4_000_000 / payload.length));
      localStorage.setItem(CACHE_KEY, JSON.stringify({ products: furtherLimited, deadStock, ts: Date.now() }));
    } else {
      localStorage.setItem(CACHE_KEY, payload);
    }
  } catch (e) {
    console.error('Error guardando cache de inventario:', e);
  }
}

const VirtuosoTable = forwardRef(({ style, ...props }, ref) => <table ref={ref} style={{ ...style, width: '100%', borderCollapse: 'collapse', textAlign: 'left' }} {...props} />);
const VirtuosoTableHead = forwardRef((props, ref) => <thead ref={ref} style={{ position: 'sticky', top: 0, background: 'var(--bg-main)', zIndex: 1 }} {...props} />);
const VirtuosoTableRow = forwardRef(({ item, ...props }, ref) => <tr ref={ref} {...props} style={{ borderBottom: '1px solid rgba(255,255,255,0.03)', transition: 'background 0.2s' }} onMouseEnter={e => e.currentTarget.style.background='rgba(255,255,255,0.02)'} onMouseLeave={e => e.currentTarget.style.background='transparent'} />);

export default function StockModule() {
  const { backend, addToast, currentSucursalId, backendError } = usePanelContext();
  const onProductsUpdated = backend.fetchProductsDB;
  const [products, setProducts] = useState([]);
  const [query, setQuery] = useState('');
  const [loading, setLoading] = useState(false);
  const [openAccordion, setOpenAccordion] = useState(null);
  const [deadStock, setDeadStock] = useState([]);
  const [offline, setOffline] = useState(false);
  const { sorted: sortedProducts, toggleSort, SortIcon } = useSortable(products, 'name');



  const [showAumentoMasivo, setShowAumentoMasivo] = useState(false);
  const [aumentoPorcentaje, setAumentoPorcentaje] = useState('');
  const fileInputRef = useRef(null);
  const [showFilters, setShowFilters] = useState(false);
  const [filterCategory, setFilterCategory] = useState('');
  const [filterStock, setFilterStock] = useState('all');
  const [filterPriceMin, setFilterPriceMin] = useState('');
  const [filterPriceMax, setFilterPriceMax] = useState('');

  const [showNuevoProducto, setShowNuevoProducto] = useState(false);
  const [categories, setCategories] = useState([]);
  const [newProduct, setNewProduct] = useState({ code: '', name: '', price: '', cost_price: '', stock: '', min_stock: '5', iva: '21%', category_id: '' });
  const [confirmState, setConfirmState] = useState({ isOpen: false, title: '', message: '', onConfirm: null, confirmLabel: 'Confirmar', variant: 'danger' });
  const [showNewCategory, setShowNewCategory] = useState(false);
  const [newCategoryName, setNewCategoryName] = useState('');
  const [promptState, setPromptState] = useState({ isOpen: false, title: '', value: '', onConfirm: null });

  const handleCreateCategory = async () => {
    if(!newCategoryName.trim()) return;
    try {
      const res = await apiPost('/categories', { name: newCategoryName });
      if(res.ok) {
        const cat = await res.json();
        setCategories([...categories, cat]);
        setNewProduct({...newProduct, category_id: cat.id});
        setShowNewCategory(false);
        setNewCategoryName('');
      }
    } catch (e) {
      console.error('Stock: no se pudo crear la categoría:', e);
      if (addToast) addToast('No se pudo crear la categoría. Revisá la conexión.', 'error');
    }
  };

  useEffect(() => {
    apiGet('/categories').then(r => r.ok ? r.json() : []).then(d => setCategories(Array.isArray(d) ? d : [])).catch(() => {});
  }, []);

  const handleCreateProduct = async () => {
    if (!newProduct.code || !newProduct.name) {
      if (addToast) addToast('Código y nombre son obligatorios.', 'error');
      return;
    }
    const price = parseFloat(newProduct.price) || 0;
    const cost = parseFloat(newProduct.cost_price) || 0;
    const stock = parseInt(newProduct.stock) || 0;
    if (price < 0 || cost < 0 || stock < 0) {
      if (addToast) addToast('Precio, costo y stock no pueden ser negativos.', 'error');
      return;
    }
    try {
      const res = await apiPost('/products', {
        code: newProduct.code,
        name: newProduct.name,
        price,
        cost_price: cost,
        stock,
        min_stock: parseInt(newProduct.min_stock) || 5,
        iva: newProduct.iva || '21%',
        category_id: newProduct.category_id ? parseInt(newProduct.category_id) : null,
      });
      if (res.ok) {
        if (addToast) addToast('Producto creado exitosamente.', 'success');
        setShowNuevoProducto(false);
        setNewProduct({ code: '', name: '', price: '', cost_price: '', stock: '', min_stock: '5', iva: '21%', category_id: '' });
        fetchProducts();
        if (onProductsUpdated) onProductsUpdated();
      } else {
        const data = await res.json().catch(()=>({}));
        if (addToast) addToast(data.detail || 'Error al crear producto.', 'error');
      }
    } catch {
      if (addToast) addToast('Error de conexión.', 'error');
    }
  };

  const handleUnpack = async (productId) => {
    try {
      const res = await apiPost(`/products/${productId}/unpack?operator=Admin`, {});
      if (res.ok) {
        if (addToast) addToast("Bulto desarmado con éxito.", "success");
        fetchProducts();
        if (onProductsUpdated) onProductsUpdated();
      } else {
        const data = await res.json().catch(()=>({}));
        if (addToast) addToast(data.detail || "Error al abrir bulto", "error");
      }
    } catch {
      if (addToast) addToast("Error de conexión", "error");
    }
  };

  const handleAumentoMasivo = async () => {
    const pct = parseFloat(aumentoPorcentaje);
    if (aumentoPorcentaje === '' || isNaN(pct) || pct <= 0) {
      if (addToast) addToast('Ingresá un porcentaje mayor a 0.', 'error');
      return;
    }
    setConfirmState({
      isOpen: true,
      title: 'Confirmar Aumento Masivo',
      message: `Vas a aumentar TODOS los precios un ${pct}%. Un producto de $1.000 pasara a costar $${Math.round(1000 * (1 + pct / 100)).toLocaleString('es-AR')}. No se puede deshacer. Continuar?`,
      confirmLabel: 'Sí, Aumentar',
      variant: 'danger',
      onConfirm: async () => {
        setConfirmState(prev => ({...prev, isOpen: false}));
        try {
          const body = { percentage: pct };
          if (filterCategory) body.category_id = parseInt(filterCategory);
          const res = await apiPost('/products/batch-increase', body);
          if (res.ok) {
            addToast(`Precios aumentados ${pct}% con éxito`, 'success');
            setShowAumentoMasivo(false);
            setAumentoPorcentaje('');
            fetchProducts();
            onProductsUpdated();
          } else {
            addToast('Error al aumentar precios', 'error');
          }
        } catch {
          addToast('Error de conexión', 'error');
        }
      }
    });
    return;

    try {
      const payload = { percentage: pct };
      if (filterCategory) payload.category_id = parseInt(filterCategory);
      await apiPost('/products/batch-increase', payload);
      if (addToast) addToast(`Precios aumentados un ${aumentoPorcentaje}% exitosamente.`, 'success');
      setShowAumentoMasivo(false);
      setAumentoPorcentaje('');
      setFilterCategory('');
      fetchProducts();
      if (onProductsUpdated) onProductsUpdated();
    } catch(e) {
      if (addToast) addToast('Error al aumentar precios.', 'error');
    }
  };

  const handleImportCsv = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    if (addToast) addToast(`Importando ${file.name}...`, 'info');
    try {
      const text = await file.text();
      const res = await fetch(`${SERVER_URL}/products/import`, {
        method: 'POST',
        headers: { 'Content-Type': 'text/plain' },
        body: text,
      });
      const data = await res.json();
      if (res.ok) {
        if (addToast) addToast(`${data.imported} productos importados exitosamente.`, 'success');
        fetchProducts();
        if (onProductsUpdated) onProductsUpdated();
      } else {
        if (addToast) addToast(data.detail || 'Error al importar archivo.', 'error');
      }
    } catch {
      if (addToast) addToast('Error de conexión al importar archivo.', 'error');
    }
    e.target.value = '';
  };

  const fetchProducts = async (q = '') => {
    setLoading(true);
    setOffline(false);

    const isPreview = new URLSearchParams(window.location.search).get('preview') === 'true' || localStorage.getItem('saas_mode') === 'true';
    if (isPreview) {
      const MOCK_PRODUCTS = [
        { id: 1, name: 'Coca Cola 2.25L Retornable', code: '7790895000997', price: 2500, cost_price: 1800, stock: 24, min_stock: 12, category_name: 'Bebidas', category_id: 1, iva: '21%' },
        { id: 2, name: 'Alfajor Jorgito Chocolate', code: '7791234567890', price: 800, cost_price: 500, stock: 45, min_stock: 15, category_name: 'Golosinas', category_id: 2, iva: '21%' },
        { id: 3, name: 'Yerba Playadito 1Kg', code: '7791234567891', price: 3500, cost_price: 2600, stock: 10, min_stock: 5, category_name: 'Almacén', category_id: 3, iva: '21%' },
        { id: 4, name: 'Papas Lays Clásicas 145g', code: '7791234567892', price: 1800, cost_price: 1200, stock: 2, min_stock: 10, category_name: 'Snacks', category_id: 4, iva: '21%' },
        { id: 5, name: 'Cerveza Quilmes 1L Retornable', code: '7791234567893', price: 1900, cost_price: 1400, stock: 36, min_stock: 24, category_name: 'Bebidas Alcoholicas', category_id: 5, iva: '21%' },
        { id: 6, name: 'Chocolate Block 170g', code: '7791234567894', price: 2200, cost_price: 1500, stock: 0, min_stock: 10, category_name: 'Golosinas', category_id: 2, iva: '21%' },
        { id: 7, name: 'Galletitas Oreo 117g', code: '7791234567895', price: 900, cost_price: 600, stock: 20, min_stock: 15, category_name: 'Almacén', category_id: 3, iva: '21%' }
      ];
      setTimeout(() => {
        setProducts(q ? MOCK_PRODUCTS.filter(p => p.name.toLowerCase().includes(q.toLowerCase())) : MOCK_PRODUCTS);
        setDeadStock([MOCK_PRODUCTS[1]]);
        setLoading(false);
      }, 400);
      return;
    }

    try {
      let path = `/products?limit=3500`;
      if (q) path += `&q=${encodeURIComponent(q)}`;
      const res = await apiGet(path);
      const data = await res.json();
      const productList = Array.isArray(data) ? data : [];
      setProducts(productList);

      let deadList = [];
      try {
        const deadRes = await apiGet('/products/dead-stock?days=30');
        const deadData = await deadRes.json();
        deadList = Array.isArray(deadData) ? deadData : [];
      } catch (e) { console.error(e) }
      setDeadStock(deadList);

      saveCache(productList, deadList);
    } catch (e) {
      const cached = loadCache();
      if (cached && cached.products?.length > 0) {
        setProducts(cached.products);
        setDeadStock(cached.deadStock || []);
        setOffline(true);
        if (addToast) addToast('Mostrando datos guardados. Sin conexión al servidor.', 'info');
      } else {
        setProducts([]);
        setDeadStock([]);
        if (addToast) addToast('Error al cargar inventario. Verificá la conexión.', 'error');
      }
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchProducts();
  }, []);

  const filteredProducts = sortedProducts.filter(p => {
    if (p.price == null) return false;
    if (filterCategory && String(p.category_id) !== String(filterCategory)) return false;
    if (filterStock === 'out_stock' && p.stock > 0) return false;
    if (filterStock === 'in_stock' && p.stock <= 0) return false;
    if (filterStock === 'low_stock' && p.stock > p.min_stock) return false;
    return true;
  });

  const handleSearch = (e) => {
    if (e.key === 'Enter') fetchProducts(query);
  };

  // derived data
  const emptyStock = products.filter(p => p.stock === 0);
  const lowStock = products.filter(p => p.stock > 0 && p.stock <= p.min_stock);
  const nearExpiry = products.filter(p => p.expiry_date && new Date(p.expiry_date) <= new Date(Date.now() + 15 * 86400000) && new Date(p.expiry_date) >= new Date());

  const toggleAccordion = (name) => {
    setOpenAccordion(openAccordion === name ? null : name);
  };

  return (
    <div style={{ padding: '12px 20px', width: '100%', height: '100%', display: 'flex', flexDirection: 'column', boxSizing: 'border-box', overflowY: 'auto' }}>

      {/* HEADER */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px', flexShrink: 0 }}>
        <h2 style={{ fontSize: '1.1rem', fontWeight: 800, margin: 0, color: 'var(--text-primary)', letterSpacing: '-0.3px' }}>Inventario</h2>
        <div style={{ display: 'flex', gap: '8px' }}>
           <button onClick={() => setShowNuevoProducto(true)} style={{ background: 'var(--gradient-primary)', color: 'white', border: 'none', borderRadius: '8px', padding: '10px 20px', fontSize: '0.95rem', fontWeight: 700, cursor: 'pointer', boxShadow: '0 4px 16px rgba(20,187,166,0.35)', whiteSpace: 'nowrap' }}>
              + Nuevo Producto
            </button>
            <button onClick={() => setShowAumentoMasivo(true)} style={{ background: 'rgba(239, 68, 68, 0.1)', border: '1px solid rgba(239, 68, 68, 0.3)', color: 'var(--accent-danger)', padding: '10px 16px', borderRadius: '8px', fontSize: '0.95rem', fontWeight: 700, cursor: 'pointer', display: 'inline-flex', alignItems: 'center', gap: '6px', whiteSpace: 'nowrap' }}>
              <Icons.Chart /> Aumento Masivo
            </button>
            <input type="file" ref={fileInputRef} accept=".csv" style={{ display: 'none' }} onChange={handleImportCsv} />
            <button onClick={() => fileInputRef.current?.click()} style={{ background: 'var(--bg-card)', border: '1px solid var(--border-color)', color: 'var(--text-primary)', padding: '10px 16px', borderRadius: '8px', fontSize: '0.95rem', fontWeight: 600, cursor: 'pointer', display: 'inline-flex', alignItems: 'center', gap: '6px', whiteSpace: 'nowrap' }}>
              <Icons.Download /> Importar CSV
            </button>
        </div>
      </div>

      {/* OFFLINE BANNER */}
      {offline && (
        <div style={{ background: 'rgba(245,158,11,0.1)', border: '1px solid rgba(245,158,11,0.2)', borderRadius: 10, padding: '12px 20px', marginBottom: 16, display: 'flex', alignItems: 'center', gap: 12, flexShrink: 0 }}>
          <Icons.Wifi style={{ width: '20px', height: '20px', color: 'var(--accent-warning)', flexShrink: 0 }} />
          <span style={{ flex: 1, color: 'var(--text-secondary)', fontSize: '0.9rem' }}>
            Sin conexión al servidor. Mostrando datos guardados.
          </span>
          <button onClick={() => fetchProducts()} style={{ background: 'var(--gradient-primary)', color: 'white', border: 'none', padding: '6px 16px', borderRadius: 6, fontWeight: 600, cursor: 'pointer', fontSize: '0.85rem' }}>
            Reintentar
          </button>
        </div>
      )}

      {/* SEARCH BAR FULL WIDTH */}
      <div style={{ display: 'flex', gap: '12px', marginBottom: '12px', flexShrink: 0 }}>
        <div style={{ flex: 1, position: 'relative' }}>
          <span style={{ position: 'absolute', left: '16px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-secondary)' }}><Icons.Search /></span>
          <input 
            type="text" 
            placeholder="Buscar por nombre o código..." 
            value={query}
            onChange={e => { setQuery(e.target.value); if(e.target.value==='') fetchProducts(''); }}
            onKeyDown={handleSearch}
            style={{ width: '100%', background: 'var(--bg-main)', border: '1px solid var(--border-color)', color: 'var(--text-primary)', padding: '12px 16px 12px 48px', borderRadius: '8px', fontSize: '0.95rem', outline: 'none' }} 
          />
        </div>
        <button onClick={() => setShowFilters(!showFilters)} style={{ background: 'var(--bg-card)', border: '1px solid var(--border-color)', color: 'var(--text-primary)', padding: '0 16px', borderRadius: '8px', fontSize: '0.95rem', fontWeight: 600, cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '8px' }}>
          <Icons.Filter /> Filtros
        </button>
      </div>

      {showFilters && (
        <div style={{ display: 'flex', gap: 12, marginBottom: 24, padding: 16, background: 'var(--bg-card)', borderRadius: 12, border: '1px solid var(--border-color)', flexWrap: 'wrap', alignItems: 'flex-end', flexShrink: 0 }}>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
            <label style={{ fontSize: '0.75rem', color: 'var(--text-secondary)', fontWeight: 600 }}>Categoria</label>
            <select value={filterCategory} onChange={e => setFilterCategory(e.target.value)} style={{ padding: '8px 12px', background: 'var(--bg-main)', border: '1px solid var(--border-color)', color: 'var(--text-primary)', borderRadius: 6, fontSize: '0.85rem', outline: 'none' }}>
              <option value="">Todas</option>
              {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
            <label style={{ fontSize: '0.75rem', color: 'var(--text-secondary)', fontWeight: 600 }}>Stock</label>
            <select value={filterStock} onChange={e => setFilterStock(e.target.value)} style={{ padding: '8px 12px', background: 'var(--bg-main)', border: '1px solid var(--border-color)', color: 'var(--text-primary)', borderRadius: 6, fontSize: '0.85rem', outline: 'none' }}>
              <option value="all">Todos</option>
              <option value="in_stock">Con stock</option>
              <option value="out_stock">Sin stock</option>
              <option value="low_stock">Stock bajo</option>
            </select>
          </div>
          <button onClick={() => { setShowFilters(false); setFilterCategory(''); setFilterStock('all'); }} style={{ padding: '8px 16px', background: 'transparent', border: '1px solid var(--border-color)', color: 'var(--text-secondary)', borderRadius: 6, fontWeight: 600, cursor: 'pointer', fontSize: '0.85rem' }}>Limpiar</button>
        </div>
      )}

      {/* MAIN TABLE */}
      <div style={{ flex: 1, background: 'var(--bg-card)', borderRadius: '16px', border: '1px solid var(--border-color)', display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
        <div style={{ padding: '10px 20px', borderBottom: '1px solid var(--border-color)', display: 'flex', alignItems: 'center', gap: 8 }}>
          <span style={{ fontSize: '0.75rem', fontWeight: 700, color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '0.5px' }}>Productos</span>
          <span style={{ fontSize: '0.75rem', color: 'var(--text-secondary)' }}>·</span>
          <span style={{ fontSize: '0.75rem', color: 'var(--text-secondary)' }}>{filteredProducts.length} resultados</span>
        </div>

        <div style={{ flex: 1 }}>
          {filteredProducts.length > 0 ? (
            <TableVirtuoso
              data={filteredProducts}
              style={{ height: '100%' }}
              className="virtuoso-stock-table"
              fixedHeaderContent={() => (
                <tr style={{ color: 'var(--text-primary)', fontSize: '0.8rem', fontWeight: 700, borderBottom: '1px solid var(--border-color)' }}>
                  <th style={{ padding: '10px 16px', width: '64px', background: 'var(--bg-main)' }}>Imagen</th>
                  <th style={{ padding: '10px 16px', background: 'var(--bg-main)', cursor: 'pointer' }} onClick={() => toggleSort('name')}>Producto<SortIcon columnKey="name" /></th>
                  <th style={{ padding: '10px 16px', background: 'var(--bg-main)', cursor: 'pointer' }} onClick={() => toggleSort('category_name')}>Categoría<SortIcon columnKey="category_name" /></th>
                  <th style={{ padding: '10px 16px', background: 'var(--bg-main)', cursor: 'pointer' }} onClick={() => toggleSort('price')}>Precio<SortIcon columnKey="price" /></th>
                  <th style={{ padding: '10px 16px', background: 'var(--bg-main)' }}>Estado</th>
                  <th style={{ padding: '10px 16px', background: 'var(--bg-main)', cursor: 'pointer' }} onClick={() => toggleSort('stock')}>Stock<SortIcon columnKey="stock" /></th>
                  <th style={{ padding: '10px 16px', background: 'var(--bg-main)' }}>Proveedor</th>
                  <th style={{ padding: '10px 16px', textAlign: 'center', background: 'var(--bg-main)' }}>Acciones</th>
                </tr>
              )}
              itemContent={(index, p) => (
                <>
                  <td style={{ padding: '8px 16px' }}>
                    <div style={{ width: '40px', height: '40px', background: 'rgba(255,255,255,0.05)', borderRadius: '10px', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--text-secondary)' }}>
                      <Icons.Image />
                    </div>
                  </td>
                  <td style={{ padding: '8px 16px' }}>
                    <div style={{ fontWeight: 600, fontSize: '0.95rem', color: 'var(--text-primary)', marginBottom: '2px' }}>{p.name}</div>
                    <div style={{ color: 'var(--text-secondary)', fontSize: '0.72rem', fontFamily: 'var(--font-mono)' }}>{p.code}</div>
                  </td>
                  <td style={{ padding: '8px 16px' }}>
                    <span style={{ background: 'rgba(255,255,255,0.05)', color: 'var(--text-secondary)', borderRadius: '10px', padding: '3px 8px', fontSize: '0.72rem', fontWeight: 600 }}>
                      {p.category_name || 'Sin categoría'}
                    </span>
                  </td>
                  <td style={{ padding: '8px 16px', fontFamily: 'var(--font-mono)', fontWeight: 700, fontSize: '0.9rem' }}>
                    ${(p.price ?? 0).toLocaleString('es-AR')}
                  </td>
                  <td style={{ padding: '8px 16px' }}>
                    <span style={{ background: p.stock > 0 ? 'rgba(16, 185, 129, 0.15)' : 'rgba(239, 68, 68, 0.15)', color: p.stock > 0 ? 'var(--accent-success)' : 'var(--accent-danger)', padding: '3px 8px', borderRadius: '10px', fontSize: '0.72rem', fontWeight: 700, whiteSpace: 'nowrap' }}>
                      {p.stock > 0 ? 'Con Stock' : 'Sin Stock'}
                    </span>
                  </td>
                  <td style={{ padding: '8px 16px' }}>
                    <div style={{ fontWeight: 800, fontSize: '0.9rem', color: (p.stock ?? 0) === 0 ? 'var(--accent-danger)' : 'var(--text-primary)', marginBottom: '1px' }}>{p.stock ?? 0} u</div>
                    <div style={{ color: 'var(--text-secondary)', fontSize: '0.7rem' }}>Alerta: {p.min_stock ?? 0} u</div>
                  </td>
                  <td style={{ padding: '8px 16px', color: 'var(--text-secondary)', fontSize: '0.8rem' }}>
                    Sin proveedor
                  </td>
                  <td style={{ padding: '16px 24px', textAlign: 'center' }}>
                    <div style={{ display: 'flex', gap: '4px', justifyContent: 'center', flexWrap: 'wrap' }}>
                      <button onClick={() => {
                        setPromptState({
                          isOpen: true,
                          title: `Nuevo precio para ${p.name} (actual: $${p.price})`,
                          value: p.price ?? '',
                          onConfirm: async (newPrice) => {
                            setPromptState(prev => ({...prev, isOpen: false}));
                            if (newPrice !== null && newPrice !== '' && !isNaN(newPrice) && parseFloat(newPrice) >= 0) {
                              try {
                                const res = await apiPatch(`/products/${p.id}/price`, { price: parseFloat(newPrice) });
                                if (res.ok) {
                                  if (addToast) addToast(`Precio de ${p.name} actualizado.`, 'success');
                                  fetchProducts();
                                  if (onProductsUpdated) onProductsUpdated();
                                } else {
                                  if (addToast) addToast('Error al actualizar precio.', 'error');
                                }
                              } catch {
                                if (addToast) addToast('Error de conexión.', 'error');
                              }
                            }
                          }
                        });
                      }} style={{ background: 'rgba(20, 187, 166, 0.15)', color: '#14BBA6', border: '1px solid rgba(20, 187, 166, 0.45)', padding: '6px 12px', borderRadius: '6px', fontSize: '0.82rem', cursor: 'pointer', fontWeight: 700, whiteSpace: 'nowrap' }}>$ Precio</button>
                      <button onClick={() => {
                        setPromptState({
                          isOpen: true,
                          title: `Nuevo stock para ${p.name} (actual: ${p.stock})`,
                          value: p.stock ?? '',
                          onConfirm: async (newStock) => {
                            setPromptState(prev => ({...prev, isOpen: false}));
                            if (newStock !== null && newStock !== '' && !isNaN(newStock) && parseInt(newStock) >= 0) {
                              try {
                                const res = await apiPatch(`/products/${p.id}/stock`, { stock: parseInt(newStock) });
                                if (res.ok) {
                                  if (addToast) addToast(`Stock de ${p.name} actualizado.`, 'success');
                                  fetchProducts();
                                  if (onProductsUpdated) onProductsUpdated();
                                } else {
                                  if (addToast) addToast('Error al actualizar stock.', 'error');
                                }
                              } catch {
                                if (addToast) addToast('Error de conexión.', 'error');
                              }
                            }
                          }
                        });
                      }} style={{ background: 'rgba(59, 130, 246, 0.15)', color: '#60A5FA', border: '1px solid rgba(59, 130, 246, 0.45)', padding: '6px 12px', borderRadius: '6px', fontSize: '0.82rem', cursor: 'pointer', fontWeight: 700, whiteSpace: 'nowrap' }}>Stock</button>
                      <button onClick={() => {
                        setPromptState({
                          isOpen: true,
                          title: `Nuevo nombre para ${p.name}`,
                          value: p.name,
                          onConfirm: async (newName) => {
                            setPromptState(prev => ({...prev, isOpen: false}));
                            if (newName !== null && newName.trim()) {
                              try {
                                const res = await apiPut(`/products/${p.id}`, { name: newName.trim() });
                                if (res.ok) {
                                  if (addToast) addToast(`Nombre de ${p.name} actualizado.`, 'success');
                                  fetchProducts();
                                  if (onProductsUpdated) onProductsUpdated();
                                } else {
                                  if (addToast) addToast(`Error al actualizar nombre (${res.status}).`, 'error');
                                }
                              } catch {
                                if (addToast) addToast('Error de conexión.', 'error');
                              }
                            }
                          }
                        });
                      }} style={{ background: 'rgba(168, 85, 247, 0.15)', color: '#C084FC', border: '1px solid rgba(168, 85, 247, 0.45)', padding: '6px 12px', borderRadius: '6px', fontSize: '0.82rem', cursor: 'pointer', fontWeight: 700, whiteSpace: 'nowrap' }}>Nombre</button>
                      {p.is_virtual === 1 && p.stock > 0 && (
                        <button onClick={() => handleUnpack(p.id)} style={{ background: 'rgba(59, 130, 246, 0.1)', color: 'var(--accent-primary)', border: '1px solid rgba(59, 130, 246, 0.2)', padding: '6px 12px', borderRadius: '6px', fontSize: '0.8rem', cursor: 'pointer', fontWeight: 600, display: 'inline-flex', alignItems: 'center', gap: '4px' }}><Icons.Package style={{ width: '14px', height: '14px' }} /> Desarmar</button>
                      )}
                    </div>
                  </td>
                </>
              )}
            />
          ) : loading ? (
            <SkeletonTable rows={6} cols={6} />
          ) : (
            <EmptyState icon="Package" title={offline ? 'Sin conexión' : 'Inventario vacío'}
              description={offline ? 'No se pudieron cargar los datos guardados. Verificá la conexión al servidor.' : 'No hay productos en el inventario. Creá tu primer producto o importá un archivo CSV.'}
              actionLabel={offline ? 'Reintentar' : undefined} actionOnClick={offline ? () => fetchProducts() : undefined} />
          )}
        </div>
      </div>

      {/* ACCORDIONS ALERTAS */}
      <div style={{ marginTop: '10px', flexShrink: 0 }}>
        <AlertAccordion
          icon={Icons.Clock} title="Productos por vencer" subtitle={`${nearExpiry.length} alerta dentro de los próximos 15 días`}
          isOpen={openAccordion === 'vencer'} onToggle={() => toggleAccordion('vencer')}
          data={nearExpiry} columns={['Producto', 'Código', 'Cantidad', 'Vence', 'Estado', 'Acción']}
          renderRow={(p) => (
            <>
              <td style={{ padding: '16px 24px', fontWeight: 600 }}>{p.name}</td>
              <td style={{ padding: '16px 24px', color: 'var(--text-secondary)', fontFamily: 'var(--font-mono)' }}>{p.code}</td>
              <td style={{ padding: '16px 24px' }}>{p.stock ?? 0} u</td>
              <td style={{ padding: '16px 24px' }}>{new Date(p.expiry_date).toLocaleDateString('es-AR')}</td>
              <td style={{ padding: '16px 24px' }}><span style={{ background: 'rgba(234,179,8,0.1)', color: 'var(--accent-warning)', border: '1px solid rgba(234,179,8,0.3)', borderRadius: '12px', padding: '4px 12px', fontSize: '0.75rem', fontWeight: 700 }}>Vence pronto</span></td>
              <td style={{ padding: '16px 24px', color: 'var(--text-secondary)', cursor: 'pointer' }} onClick={() => {
                setConfirmState({
                  isOpen: true,
                  title: 'Eliminar Producto',
                  message: `¿Seguro que deseas eliminar ${p.name}?`,
                  confirmLabel: 'Eliminar',
                  variant: 'danger',
                  onConfirm: () => {
                    setConfirmState(prev => ({...prev, isOpen: false}));
                  apiPost(`/products/${p.id}`, {}).then(r => {
                    if (r.ok) { addToast(`${p.name} eliminado.`, 'success'); fetchProducts(); }
                    else addToast('Error al eliminar.', 'error');
                  }).catch(() => addToast('Error de conexion.', 'error'));
                  }
                });
              }}><Icons.Trash /></td>
            </>
          )}
        />
        <AlertAccordion
          icon={Icons.Box} title="Sin Stock" subtitle={`${emptyStock.length} productos sin stock`}
          isOpen={openAccordion === 'empty'} onToggle={() => toggleAccordion('empty')}
          data={emptyStock} columns={['Producto', 'Código', 'Categoría', 'Stock', 'Estado']}
          renderRow={(p) => (
            <>
              <td style={{ padding: '16px 24px', fontWeight: 600 }}>{p.name}</td>
              <td style={{ padding: '16px 24px', color: 'var(--text-secondary)', fontFamily: 'var(--font-mono)' }}>{p.code}</td>
              <td style={{ padding: '16px 24px' }}><span style={{ background: 'rgba(255,255,255,0.05)', color: 'var(--text-secondary)', borderRadius: '12px', padding: '4px 10px', fontSize: '0.75rem', fontWeight: 600 }}>{p.category_name || 'Varios'}</span></td>
              <td style={{ padding: '16px 24px', color: 'var(--accent-danger)', fontWeight: 800 }}>0 u</td>
              <td style={{ padding: '16px 24px' }}><span style={{ background: 'rgba(239,68,68,0.1)', color: 'var(--accent-danger)', border: '1px solid rgba(239,68,68,0.3)', borderRadius: '12px', padding: '4px 12px', fontSize: '0.75rem', fontWeight: 700 }}>Agotado</span></td>
            </>
          )}
        />
        <AlertAccordion
          icon={Icons.Warning} title="Alertas de Stock" subtitle={`${lowStock.length} productos con stock bajo`}
          isOpen={openAccordion === 'low'} onToggle={() => toggleAccordion('low')}
          data={lowStock} columns={['Producto', 'Código', 'Cantidad Actual', 'Mínimo', 'Estado']}
          renderRow={(p) => (
            <>
              <td style={{ padding: '16px 24px', fontWeight: 600 }}>{p.name}</td>
              <td style={{ padding: '16px 24px', color: 'var(--text-secondary)', fontFamily: 'var(--font-mono)' }}>{p.code}</td>
              <td style={{ padding: '16px 24px', color: 'var(--text-primary)', fontWeight: 700 }}>{p.stock ?? 0} u</td>
              <td style={{ padding: '16px 24px', color: 'var(--text-secondary)' }}>{p.min_stock ?? 0} u</td>
              <td style={{ padding: '16px 24px' }}><span style={{ background: 'rgba(234,179,8,0.1)', color: 'var(--accent-warning)', border: '1px solid rgba(234,179,8,0.3)', borderRadius: '12px', padding: '4px 12px', fontSize: '0.75rem', fontWeight: 700 }}>Crítico</span></td>
            </>
          )}
        />
        <AlertAccordion
          icon={Icons.Trash} title="Stock Muerto" subtitle={`${deadStock.length} productos sin ventas en 30 días`}
          isOpen={openAccordion === 'dead'} onToggle={() => toggleAccordion('dead')}
          data={deadStock} columns={['Producto', 'Código', 'Categoría', 'Stock Estancado', 'Precio']}
          renderRow={(p) => (
            <>
              <td style={{ padding: '16px 24px', fontWeight: 600 }}>{p.name}</td>
              <td style={{ padding: '16px 24px', color: 'var(--text-secondary)', fontFamily: 'var(--font-mono)' }}>{p.code}</td>
              <td style={{ padding: '16px 24px' }}>{p.category_name}</td>
              <td style={{ padding: '16px 24px', color: 'var(--text-primary)', fontWeight: 800 }}>{p.stock ?? 0} u</td>
              <td style={{ padding: '16px 24px', color: 'var(--text-secondary)' }}>${p.price ?? 0}</td>
            </>
          )}
        />
      </div>

      {/* MODAL NUEVO PRODUCTO */}
      {showNuevoProducto && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(30,58,95,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
          <div style={{ background: 'var(--bg-main)', border: '1px solid var(--border-color)', borderRadius: '16px', padding: '32px', width: '480px', maxHeight: '90vh', overflowY: 'auto', boxShadow: '0 10px 25px rgba(30,58,95,0.5)' }}>
            <h2 style={{ fontSize: '1.5rem', fontWeight: 800, margin: '0 0 24px 0', color: 'var(--text-primary)' }}>Nuevo Producto</h2>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px' }}>
              {[{ label: 'Código', key: 'code', type: 'text' }, { label: 'Nombre', key: 'name', type: 'text' },
                { label: 'Precio Venta ($)', key: 'price', type: 'number' }, { label: 'Precio Costo ($)', key: 'cost_price', type: 'number' },
                { label: 'Stock', key: 'stock', type: 'number' }, { label: 'Stock Mínimo', key: 'min_stock', type: 'number' },
              ].map(f => (
                <div key={f.key}>
                  <label style={{ display: 'block', color: 'var(--text-secondary)', fontSize: '0.85rem', marginBottom: '6px', fontWeight: 600 }}>{f.label}</label>
                  <input type={f.type} value={newProduct[f.key]} onChange={e => setNewProduct({ ...newProduct, [f.key]: e.target.value })}
                    style={{ width: '100%', padding: '10px 12px', background: 'var(--bg-card)', border: '1px solid var(--border-color)', color: 'var(--text-primary)', borderRadius: '8px', outline: 'none', fontSize: '0.95rem', boxSizing: 'border-box' }} />
                </div>
              ))}
              <div>
                <label style={{ display: 'block', color: 'var(--text-secondary)', fontSize: '0.85rem', marginBottom: '6px', fontWeight: 600 }}>IVA</label>
                <select value={newProduct.iva} onChange={e => setNewProduct({ ...newProduct, iva: e.target.value })}
                  style={{ width: '100%', padding: '10px 12px', background: 'var(--bg-card)', border: '1px solid var(--border-color)', color: 'var(--text-primary)', borderRadius: '8px', outline: 'none', fontSize: '0.95rem', boxSizing: 'border-box' }}>
                  <option value="21%">21%</option><option value="10.5%">10.5%</option><option value="0%">0%</option>
                </select>
              </div>
              <div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '6px' }}>
                  <label style={{ display: 'block', color: 'var(--text-secondary)', fontSize: '0.85rem', fontWeight: 600 }}>Categoría</label>
                  <button onClick={() => setShowNewCategory(true)} style={{ background: 'transparent', border: 'none', color: 'var(--accent-primary)', fontSize: '0.8rem', fontWeight: 600, cursor: 'pointer', padding: 0 }}>+ Nueva</button>
                </div>
                <select value={newProduct.category_id} onChange={e => setNewProduct({ ...newProduct, category_id: e.target.value })}
                  style={{ width: '100%', padding: '10px 12px', background: 'var(--bg-card)', border: '1px solid var(--border-color)', color: 'var(--text-primary)', borderRadius: '8px', outline: 'none', fontSize: '0.95rem', boxSizing: 'border-box' }}>
                  <option value="">Sin categoría</option>
                  {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
              </div>
            </div>
            <div style={{ display: 'flex', gap: '12px', justifyContent: 'flex-end', marginTop: '24px' }}>
              <button onClick={() => { setShowNuevoProducto(false); setNewProduct({ code: '', name: '', price: '', cost_price: '', stock: '', min_stock: '5', iva: '21%', category_id: '' }); }}
                style={{ background: 'transparent', border: 'none', color: 'var(--text-secondary)', padding: '10px 16px', borderRadius: '8px', cursor: 'pointer', fontWeight: 600 }}>Cancelar</button>
              <button onClick={handleCreateProduct}
                style={{ background: 'var(--gradient-primary)', border: 'none', color: 'white', padding: '10px 24px', borderRadius: '8px', cursor: 'pointer', fontWeight: 700 }}>
                Crear Producto
              </button>
            </div>
          </div>
        </div>
      )}

      {/* MODAL AUMENTO MASIVO */}
      {showAumentoMasivo && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(30,58,95,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
          <div style={{ background: 'var(--bg-main)', border: '1px solid var(--border-color)', borderRadius: '16px', padding: '32px', width: '400px', boxShadow: '0 10px 25px rgba(30,58,95,0.5)' }}>
            <h2 style={{ fontSize: '1.5rem', fontWeight: 800, margin: '0 0 16px 0', color: 'var(--text-primary)' }}>Aumento Masivo de Precios</h2>
            <p style={{ color: 'var(--text-secondary)', marginBottom: '24px', fontSize: '0.95rem' }}>
              Ingresa el porcentaje de inflación para actualizar todos los precios de venta automáticamente.
            </p>
            <div style={{ marginBottom: '24px' }}>
              <label style={{ display: 'block', color: 'var(--text-secondary)', fontSize: '0.9rem', marginBottom: '8px', fontWeight: 600 }}>Porcentaje de Aumento (%)</label>
              <input 
                type="number" 
                value={aumentoPorcentaje}
                onChange={e => setAumentoPorcentaje(e.target.value)}
                placeholder="Ej: 15"
                autoFocus
                style={{ width: '100%', padding: '12px 16px', background: 'var(--bg-card)', border: '1px solid var(--border-color)', color: 'var(--text-primary)', borderRadius: '8px', fontSize: '1.1rem', fontWeight: 700, outline: 'none' }}
              />
            </div>
            <div style={{ marginBottom: '24px' }}>
              <label style={{ display: 'block', color: 'var(--text-secondary)', fontSize: '0.9rem', marginBottom: '8px', fontWeight: 600 }}>Categoria (opcional — deja vacio para todos)</label>
              <select value={filterCategory} onChange={e => setFilterCategory(e.target.value)} style={{ width: '100%', padding: '12px 16px', background: 'var(--bg-card)', border: '1px solid var(--border-color)', color: 'var(--text-primary)', borderRadius: '8px', fontSize: '1rem', outline: 'none' }}>
                <option value="">Todas las categorias</option>
                {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>
            <div style={{ display: 'flex', gap: '12px', justifyContent: 'flex-end' }}>
              <button onClick={() => setShowAumentoMasivo(false)} style={{ background: 'transparent', border: 'none', color: 'var(--text-secondary)', padding: '10px 16px', borderRadius: '8px', cursor: 'pointer', fontWeight: 600 }}>Cancelar</button>
              <button onClick={handleAumentoMasivo} disabled={!aumentoPorcentaje} style={{ background: 'var(--accent-danger)', border: 'none', color: 'white', padding: '10px 24px', borderRadius: '8px', cursor: !aumentoPorcentaje ? 'not-allowed' : 'pointer', fontWeight: 700, opacity: !aumentoPorcentaje ? 0.5 : 1 }}>
                Aplicar Aumento
              </button>
            </div>
          </div>
        </div>
      )}

      <ConfirmModal
        isOpen={confirmState.isOpen}
        title={confirmState.title}
        message={confirmState.message}
        onClose={() => setConfirmState(prev => ({...prev, isOpen: false}))}
        onConfirm={confirmState.onConfirm}
        confirmLabel={confirmState.confirmLabel}
        variant={confirmState.variant}
      />

      {showNewCategory && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(30,58,95,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1100 }}>
          <div style={{ background: 'var(--bg-main)', border: '1px solid var(--border-color)', borderRadius: '16px', padding: '24px', width: '300px' }}>
            <h3 style={{ margin: '0 0 16px 0', color: 'var(--text-primary)' }}>Nueva Categoría</h3>
            <input type="text" value={newCategoryName} onChange={e => setNewCategoryName(e.target.value)} autoFocus
                   placeholder="Nombre de categoría"
                   style={{ width: '100%', padding: '10px', background: 'var(--bg-card)', border: '1px solid var(--border-color)', color: 'var(--text-primary)', borderRadius: '8px', marginBottom: '16px', outline: 'none', boxSizing: 'border-box' }} />
            <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end' }}>
              <button onClick={() => { setShowNewCategory(false); setNewCategoryName(''); }} style={{ background: 'transparent', border: 'none', color: 'var(--text-secondary)', padding: '8px 12px', borderRadius: '8px', cursor: 'pointer' }}>Cancelar</button>
              <button onClick={handleCreateCategory} style={{ background: 'var(--gradient-primary)', border: 'none', color: 'white', padding: '8px 12px', borderRadius: '8px', cursor: 'pointer' }}>Crear</button>
            </div>
          </div>
        </div>
      )}
      {promptState.isOpen && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(30,58,95,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1100 }}>
          <div style={{ background: 'var(--bg-main)', border: '1px solid var(--border-color)', borderRadius: '16px', padding: '24px', width: '320px', boxShadow: '0 10px 25px rgba(0,0,0,0.5)' }}>
            <h3 style={{ margin: '0 0 16px 0', color: 'var(--text-primary)', fontSize: '1.1rem', fontWeight: 700 }}>{promptState.title}</h3>
            <input 
              type="number" 
              step="any" 
              value={promptState.value} 
              onChange={e => setPromptState({...promptState, value: e.target.value})} 
              autoFocus
              onKeyDown={e => {
                if (e.key === 'Enter') promptState.onConfirm(promptState.value);
                if (e.key === 'Escape') setPromptState({...promptState, isOpen: false});
              }}
              style={{ width: '100%', padding: '12px 16px', background: 'var(--bg-card)', border: '1px solid var(--border-color)', color: 'var(--text-primary)', borderRadius: '8px', marginBottom: '24px', outline: 'none', boxSizing: 'border-box', fontSize: '1.2rem', fontWeight: 800, textAlign: 'center' }} 
            />
            <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end' }}>
              <button onClick={() => setPromptState({...promptState, isOpen: false})} style={{ background: 'transparent', border: 'none', color: 'var(--text-secondary)', padding: '10px 16px', borderRadius: '8px', cursor: 'pointer', fontWeight: 600 }}>Cancelar</button>
              <button onClick={() => promptState.onConfirm(promptState.value)} style={{ background: 'var(--gradient-primary)', border: 'none', color: 'white', padding: '10px 24px', borderRadius: '8px', cursor: 'pointer', fontWeight: 700 }}>Guardar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useCallback } from 'react';
import { apiPost } from '../services/apiClient';

const K_OPERATOR = 'minegocio_current_operator';
const K_TURN_ID = 'minegocio_current_turn_id';
const K_TURN_OPENED = 'minegocio_turn_opened_at';

export default function useAuth(addToast) {
  const [isSaaSAuthenticated, setIsSaaSAuthenticated] = useState(
    !!localStorage.getItem('saas_token') || localStorage.getItem('saas_mode') === 'offline'
  );
  const [saasMode, setSaasMode] = useState(localStorage.getItem('saas_mode') || 'online');
  const [isAuthenticated, setIsAuthenticated] = useState(!!localStorage.getItem(K_TURN_ID));
  const [currentOperator, setCurrentOperator] = useState(() => {
    try {
      const raw = localStorage.getItem(K_OPERATOR);
      return raw ? JSON.parse(raw) : null;
    } catch { return null; }
  });
  const [currentTurnId, setCurrentTurnId] = useState(localStorage.getItem(K_TURN_ID) || null);
  const [turnOpenedAt, setTurnOpenedAt] = useState(localStorage.getItem(K_TURN_OPENED) || null);
  const [initialCash, setInitialCash] = useState(0);
  const [pin, setPin] = useState('');

  const handlePin = async (e) => {
    e.preventDefault();
    if (pin.length === 0) return;
    try {
      const res = await apiPost(`/login`, { pin, mode: saasMode });
      if (res.ok) {
        const data = await res.json();
        const operatorObj = data.operator_id
          ? { id: data.operator_id, name: data.name || data.operator_name || 'Dueño', role: data.role || 'admin' }
          : { name: data.name || 'Dueño', role: 'admin' };
        setCurrentOperator(operatorObj);
        setCurrentTurnId(data.turn_id);
        if (data.turn_opened_at) {
          setTurnOpenedAt(data.turn_opened_at);
          localStorage.setItem(K_TURN_OPENED, data.turn_opened_at);
        } else {
          setTurnOpenedAt(null);
          localStorage.removeItem(K_TURN_OPENED);
        }
        localStorage.setItem(K_OPERATOR, JSON.stringify(operatorObj));
        localStorage.setItem(K_TURN_ID, String(data.turn_id || ''));
        localStorage.removeItem('minegocio_onboarding_pin');
        if (data.turn_auto_opened) {
          localStorage.setItem('minegocio_onboarding_pending', 'true');
        }
        setIsAuthenticated(true);
      } else {
        addToast('PIN incorrecto', 'error');
        setPin('');
      }
    } catch {
      addToast('Error de conexion con el servidor', 'error');
    }
  };

  const handleSaaSCallback = (data) => {
    setIsSaaSAuthenticated(true);
    if (data.mode) setSaasMode(data.mode);
  };

  return {
    isSaaSAuthenticated, setIsSaaSAuthenticated,
    saasMode, setSaasMode,
    isAuthenticated, setIsAuthenticated,
    currentOperator, setCurrentOperator,
    currentTurnId, setCurrentTurnId,
    turnOpenedAt, setTurnOpenedAt,
    initialCash, setInitialCash,
    pin, setPin,
    handlePin,
    handleSaaSCallback,
  };
}

import { useState, useEffect, useCallback } from 'react';
import { apiGet, apiPost, apiPatch, SERVER_URL } from '../services/apiClient';

export default function useBackend(currentOperator, currentTurnId, currentSucursalId, addToast) {
  const [productsDB, setProductsDB] = useState([]);
  const [backendError, setBackendError] = useState(false);
  const [backendDetailedError, setBackendDetailedError] = useState(false);
  const [backendStatus, setBackendStatus] = useState(null);
  const [backendLastOk, setBackendLastOk] = useState(null);
  const [pendingSync, setPendingSync] = useState(0);
  const [todaySalesTotal, setTodaySalesTotal] = useState(0);
  const [operators, setOperators] = useState([]);
  const [sucursales, setSucursales] = useState([]);
  const [businessConfig, setBusinessConfig] = useState({});
  const [stockAlerts, setStockAlerts] = useState(null);
  const [showEgreso, setShowEgreso] = useState(false);
  const [egresoMonto, setEgresoMonto] = useState('');
  const [egresoMotivo, setEgresoMotivo] = useState('');
  const [egresoType, setEgresoType] = useState('gasto');
  const [showResumen, setShowResumen] = useState(false);
  const [resumenData, setResumenData] = useState(null);
  const [showDevolucionItems, setShowDevolucionItems] = useState(false);
  const [devolucionQtys, setDevolucionQtys] = useState({});
  const [isReverting, setIsReverting] = useState(false);
  const [backupLoading, setBackupLoading] = useState(false);
  const [showBackupRestore, setShowBackupRestore] = useState(false);
  const [backupList, setBackupList] = useState([]);
  const [restoring, setRestoring] = useState(false);
  const [mpQrData, setMpQrData] = useState(null);
  const [mpPaymentUrl, setMpPaymentUrl] = useState('');
  const [mpLoading, setMpLoading] = useState(false);
  const [mpPaymentStatus, setMpPaymentStatus] = useState('pending');
  const [mpIntentId, setMpIntentId] = useState('');
  const [expiryAlerts, setExpiryAlerts] = useState(null);
  const [showExpiryAlerts, setShowExpiryAlerts] = useState(false);
  const [showLogs, setShowLogs] = useState(false);
  const [sysLogs, setSysLogs] = useState([]);
  const [showHelp, setShowHelp] = useState(false);
  const [showCierres, setShowCierres] = useState(false);
  const [cierresData, setCierresData] = useState([]);
  const [showPendingModal, setShowPendingModal] = useState(false);
  const [showPriceCheck, setShowPriceCheck] = useState(false);
  const [priceCheckQuery, setPriceCheckQuery] = useState('');
  const [priceCheckResults, setPriceCheckResults] = useState([]);
  const [showDuplicateCodeModal, setShowDuplicateCodeModal] = useState(false);
  const [duplicateCodeMatches, setDuplicateCodeMatches] = useState([]);
  const [customers, setCustomers] = useState([]);

  const fetchProductsDB = useCallback(() => {
    apiGet(`/products?limit=5000&sucursal_id=${currentSucursalId}`)
      .then(r => r.json())
      .then(data => setProductsDB(Array.isArray(data) ? data : []))
      .catch(() => {});
  }, [currentSucursalId]);

  const notifyTabs = useCallback((msg) => {
    try { new BroadcastChannel('minegocio-sync').postMessage(msg); } catch {}
  }, []);

  const handleUnpack = useCallback(async (productId) => {
    try {
      const res = await apiPost(`/products/${productId}/unpack?operator=${currentOperator?.name}`, {});
      const data = await res.json();
      addToast(`✅ Desempaquetado: ${data.message || 'OK'}`, 'success');
      fetchProductsDB();
    } catch { addToast('Error al desempaquetar', 'error'); }
  }, [currentOperator, addToast, fetchProductsDB]);

  const handleDevolucionItem = useCallback(async (productId, productName, lastSaleId, devolucionQtysLocal, supervisorPin) => {
    try {
      const qty = parseFloat(devolucionQtysLocal?.[productId]) || 1;
      const res = await apiPatch(`/sales/${lastSaleId}/revert-item`, {
        product_id: productId,
        quantity: qty,
        operator: currentOperator?.name || 'Sistema',
        supervisor_pin: supervisorPin || '',
      });
      if (res.ok) {
        addToast(`✅ ${productName} devuelto`, 'success');
        fetchProductsDB();
        return true;
      }
      const err = await res.json().catch(() => ({}));
      addToast(err.detail || 'Error al devolver', 'error');
      return false;
    } catch { addToast('Error de conexión', 'error'); return false; }
  }, [currentOperator, addToast, fetchProductsDB]);

  const handleDevolucion = useCallback(async (lastSaleId, supervisorPin) => {
    if (!lastSaleId) return false;
    setIsReverting(true);
    try {
      const res = await apiPatch(`/sales/${lastSaleId}/revert?operator=${currentOperator?.name || 'Sistema'}`, {
        supervisor_pin: supervisorPin || '',
      });
      if (res.ok) {
        addToast('✅ Venta anulada completamente', 'success');
        fetchProductsDB();
        return true;
      }
      const err = await res.json().catch(() => ({}));
      addToast(err.detail || 'Error al anular', 'error');
      return false;
    } catch { addToast('Error de conexión', 'error'); return false; }
    finally { setIsReverting(false); }
  }, [currentOperator, addToast, fetchProductsDB]);

  const handleManualSync = useCallback(async () => {
    const pendingStr = localStorage.getItem('minegocio_pending_sales');
    if (!pendingStr) { addToast('No hay pendientes', 'info'); return; }
    const pending = JSON.parse(pendingStr);
    if (pending.length === 0) { addToast('No hay pendientes', 'info'); return; }
    addToast(`Sincronizando ${pending.length} ventas...`, 'info');
    const batch = [...pending];
    const results = await Promise.allSettled(
      batch.map(item => apiPost(`/sales?idempotency_key=${item.idempotencyKey}`, item.payload))
    );
    const ok = results.filter(r => r.status === 'fulfilled' && r.value.ok).length;
    const remaining = results
      .map((r, i) => r.status === 'fulfilled' && r.value.ok ? null : batch[i])
      .filter(Boolean);
    localStorage.setItem('minegocio_pending_sales', JSON.stringify(remaining));
    setPendingSync(remaining.length);
    addToast(`${ok} sincronizadas, ${remaining.length} pendientes`, ok > 0 ? 'success' : 'error');
  }, [addToast]);

  const submitEgreso = useCallback(async () => {
    if (!egresoMonto || !egresoMotivo) return;
    try {
      const res = await apiPost('/egresos', {
        turn_id: currentTurnId,
        amount: parseFloat(egresoMonto),
        reason: egresoMotivo,
        type: egresoType,
        operator: currentOperator?.name || 'Sistema',
      });
      if (res.ok) {
        addToast(`✅ ${egresoType === 'gasto' ? 'Gasto' : 'Retiro'} registrado`, 'success');
        setShowEgreso(false);
        setEgresoMonto('');
        setEgresoMotivo('');
        setEgresoType('gasto');
      } else {
        const err = await res.json().catch(() => ({}));
        addToast(err.detail || 'Error', 'error');
      }
    } catch { addToast('Error de conexión', 'error'); }
  }, [egresoMonto, egresoMotivo, egresoType, currentTurnId, currentOperator, addToast]);

  const handleBackup = useCallback(async () => {
    setBackupLoading(true);
    try {
      const res = await apiPost('/backup', {});
      if (res.ok) { addToast('✅ Backup creado', 'success'); }
      else { addToast('Error al hacer backup', 'error'); }
    } catch { addToast('Error de conexión', 'error'); }
    setBackupLoading(false);
  }, [addToast]);

  const getPendingData = useCallback(() => {
    try {
      const raw = localStorage.getItem('minegocio_pending_sales');
      const arr = raw ? JSON.parse(raw) : [];
      const total = arr.reduce((s, item) => s + (item.payload?.total || 0), 0);
      return { count: arr.length, total };
    } catch { return { count: 0, total: 0 }; }
  }, []);

  useEffect(() => {
    fetchProductsDB();
    apiGet('/config').then(r => r.json()).then(d => setBusinessConfig(d)).catch(() => {});
    apiGet('/operators').then(r => r.json()).then(d => setOperators(Array.isArray(d) ? d : [])).catch(() => {});
    apiGet('/sucursales').then(r => r.json()).then(d => setSucursales(Array.isArray(d) ? d : [])).catch(() => {});
    apiGet('/customers').then(r => r.json()).then(d => setCustomers(Array.isArray(d) ? d : [])).catch(() => {});
    // Item 13: SSE - Escuchar eventos en tiempo real
    const baseUrl = SERVER_URL.replace('/api', '');
    let retryDelay = 1000;
    let evtSource;

    const connectSSE = () => {
      if (evtSource) evtSource.close();
      const sseToken = localStorage.getItem('saas_token');
      const validToken = sseToken && sseToken !== 'demo-token' && sseToken !== 'preview-token';
      const sseUrl = validToken
        ? `${baseUrl}/api/events?token=${encodeURIComponent(sseToken)}`
        : `${baseUrl}/api/events`;
      evtSource = new EventSource(sseUrl);
      evtSource.addEventListener('product-changed', () => fetchProductsDB());
      evtSource.addEventListener('sale-created', () => {
        fetchProductsDB();
        apiGet(`/sales/today?sucursal_id=${currentSucursalId}`).then(r => r.json()).then(d => {
          setTodaySalesTotal((d.total_efectivo || 0) + (d.total_tarjeta || 0) + (d.total_transferencia || 0) + (d.total_mp || 0) + (d.total_fiado || 0));
          setResumenData(d);
        }).catch(() => {});
      });
      evtSource.onerror = () => {
        evtSource.close();
        clearTimeout(evtSource._reconnectTimer);
        evtSource._reconnectTimer = setTimeout(() => {
          fetchProductsDB();
          connectSSE();
        }, retryDelay);
        retryDelay = Math.min(retryDelay * 2, 30000);
      };
      evtSource.onopen = () => { retryDelay = 1000; };
    };
    connectSSE();

    const bc = typeof BroadcastChannel !== 'undefined' ? new BroadcastChannel('minegocio-sync') : null;
    if (bc) {
      bc.onmessage = (e) => {
        if (e.data === 'products-changed') fetchProductsDB();
        if (e.data === 'config-changed') apiGet('/config').then(r => r.json()).then(d => setBusinessConfig(d)).catch(() => {});
        if (e.data === 'sale-made') {
          fetchProductsDB();
          apiGet(`/sales/today?sucursal_id=${currentSucursalId}`).then(r => r.json()).then(d => {
            setTodaySalesTotal((d.total_efectivo || 0) + (d.total_tarjeta || 0) + (d.total_transferencia || 0) + (d.total_mp || 0) + (d.total_fiado || 0));
            setResumenData(d);
          }).catch(() => {});
        }
      };
    }
    const handleFocus = () => { fetchProductsDB(); };
    window.addEventListener('focus', handleFocus);

    return () => {
      if (evtSource) evtSource.close();
      if (bc) bc.close();
      window.removeEventListener('focus', handleFocus);
    };
  }, [fetchProductsDB, currentSucursalId]);

  useEffect(() => {
    const checkRealHealth = async () => {
      try {
        const res = await apiGet('/health');
        if (res.ok) {
          setBackendError(false);
          setBackendDetailedError(false);
          setBackendStatus({ status: 'ok' });
          setBackendLastOk(Date.now());
          try {
            const todayRes = await apiGet(`/sales/today?sucursal_id=${currentSucursalId}`);
            const todayData = await todayRes.json();
            setTodaySalesTotal((todayData.total_efectivo || 0) + (todayData.total_tarjeta || 0) + (todayData.total_transferencia || 0) + (todayData.total_mp || 0) + (todayData.total_fiado || 0));
            setResumenData(todayData);
          } catch (e) { console.error(e) }
        } else {
          setBackendError(true);
          setBackendStatus({ status: 'error', code: res.status });
        }
      } catch {
        setBackendError(true);
        setBackendStatus({ status: 'error', code: 0 });
      }
    };
    checkRealHealth();
    const interval = setInterval(checkRealHealth, 15000);
    return () => clearInterval(interval);
  }, [currentSucursalId]);

  useEffect(() => {
    const syncPending = async () => {
      try {
        const pendingStr = localStorage.getItem('minegocio_pending_sales');
        if (!pendingStr) { setPendingSync(0); return; }
        const pending = JSON.parse(pendingStr);
        if (pending.length === 0) { setPendingSync(0); return; }
        setPendingSync(pending.length);
        const batch = pending.slice(0, 10);
        const remaining = pending.slice(10);
        let synced = 0;
        const failedItems = [];
        for (const item of batch) {
          if ((item._retries || 0) > 5) {
            failedItems.push(item);
            continue;
          }
          try {
            const res = await apiPost(`/sales?idempotency_key=${item.idempotencyKey}`, item.payload);
            if (res.ok) { synced++; }
            else { item._retries = (item._retries || 0) + 1; failedItems.push(item); }
          } catch { item._retries = (item._retries || 0) + 1; failedItems.push(item); }
        }
        const newPending = [...remaining, ...failedItems];
        localStorage.setItem('minegocio_pending_sales', JSON.stringify(newPending));
        setPendingSync(newPending.length);
        if (synced > 0) { fetchProductsDB(); }
        if (newPending.length === 0 && synced > 0) {
          localStorage.removeItem('minegocio_inventario_cache');
        }
      } catch (e) { console.error(e) }
    };
    const interval = setInterval(syncPending, 10000);
    return () => clearInterval(interval);
  }, [fetchProductsDB]);

  // Operator restoration from localStorage is handled in useAuth

  return {
    productsDB, setProductsDB,
    fetchProductsDB,
    backendError, setBackendError,
    backendDetailedError, setBackendDetailedError,
    backendStatus, setBackendStatus,
    backendLastOk, setBackendLastOk,
    pendingSync, setPendingSync,
    todaySalesTotal, setTodaySalesTotal,
    operators, setOperators,
    sucursales, setSucursales,
    businessConfig, setBusinessConfig,
    stockAlerts, setStockAlerts,
    showEgreso, setShowEgreso,
    egresoMonto, setEgresoMonto,
    egresoMotivo, setEgresoMotivo,
    egresoType, setEgresoType,
    showResumen, setShowResumen,
    resumenData, setResumenData,
    showDevolucionItems, setShowDevolucionItems,
    devolucionQtys, setDevolucionQtys,
    isReverting, setIsReverting,
    backupLoading, setBackupLoading,
    showBackupRestore, setShowBackupRestore,
    backupList, setBackupList,
    restoring, setRestoring,
    mpQrData, setMpQrData,
    mpPaymentUrl, setMpPaymentUrl,
    mpLoading, setMpLoading,
    mpPaymentStatus, setMpPaymentStatus,
    mpIntentId, setMpIntentId,
    expiryAlerts, setExpiryAlerts,
    showExpiryAlerts, setShowExpiryAlerts,
    showLogs, setShowLogs,
    sysLogs, setSysLogs,
    showHelp, setShowHelp,
    showCierres, setShowCierres,
    cierresData, setCierresData,
    showPendingModal, setShowPendingModal,
    showPriceCheck, setShowPriceCheck,
    priceCheckQuery, setPriceCheckQuery,
    priceCheckResults, setPriceCheckResults,
    showDuplicateCodeModal, setShowDuplicateCodeModal,
    duplicateCodeMatches, setDuplicateCodeMatches,
    customers, setCustomers,
    handleUnpack,
    handleDevolucionItem, handleDevolucion,
    handleManualSync,
    submitEgreso,
    handleBackup,
    getPendingData,
  };
}

import { useState, useCallback, useMemo, useRef, useEffect } from 'react';

export default function useCart(productsDB, ivaRate, playBeep) {
  const [cart, setCart] = useState(() => {
    try {
      const saved = localStorage.getItem('minegocio_cart');
      if (saved) {
        const ts = localStorage.getItem('minegocio_cart_ts');
        if (ts) {
          const age = Date.now() - parseInt(ts);
          if (age > 86400000) { localStorage.removeItem('minegocio_cart'); localStorage.removeItem('minegocio_cart_ts'); return []; }
        }
        return JSON.parse(saved);
      }
    } catch {}
    return [];
  });
  const [search, setSearch] = useState('');
  const [searchError, setSearchError] = useState(false);
  const [flash, setFlash] = useState(false);
  const [itemDiscounts, setItemDiscounts] = useState({});
  const [discountInputActive, setDiscountInputActive] = useState(null);
  const [adjustedTotal, setAdjustedTotal] = useState(null);
  const [editingTotal, setEditingTotal] = useState(false);
  const [payment, setPayment] = useState('');
  const [paymentMethod, setPaymentMethod] = useState('efectivo');
  const [useSplitPayment, setUseSplitPayment] = useState(false);
  const [splitPayments, setSplitPayments] = useState([{ method: 'efectivo', amount: '' }]);
  const [clientCuit, setClientCuit] = useState('');
  const [vueltoEnCuenta, setVueltoEnCuenta] = useState(false);
  const [clienteVuelto, setClienteVuelto] = useState('');
  const [emitirFactura, setEmitirFactura] = useState(false);
  const [tipoFactura, setTipoFactura] = useState('C');
  const [autoPrint, setAutoPrint] = useState(false);
  const [isCancelConfirm, setIsCancelConfirm] = useState(false);
  const [promotionSavings, setPromotionSavings] = useState(0);
  const addLockRef = useRef(false);
  const debounceRef = useRef(null);

  // Persist cart to localStorage with debounce
  useEffect(() => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => {
      try {
        localStorage.setItem('minegocio_cart', JSON.stringify(cart));
        localStorage.setItem('minegocio_cart_ts', String(Date.now()));
      } catch {}
      try {
        const bc = typeof BroadcastChannel !== 'undefined' ? new BroadcastChannel('minegocio-cart') : null;
        if (bc) { bc.postMessage('cart-updated'); bc.close(); }
      } catch {}
    }, 250);
    return () => { if (debounceRef.current) clearTimeout(debounceRef.current); };
  }, [cart]);

  // Listen for cart changes from other tabs
  useEffect(() => {
    const bc = typeof BroadcastChannel !== 'undefined' ? new BroadcastChannel('minegocio-cart') : null;
    if (!bc) return;
    const handler = () => {
      try {
        const saved = localStorage.getItem('minegocio_cart');
        if (saved) {
          const parsed = JSON.parse(saved);
          if (Array.isArray(parsed) && parsed.length > 0) setCart(parsed);
        }
      } catch {}
    };
    bc.onmessage = handler;
    return () => bc.close();
  }, []);

  const handleQuickAdd = useCallback((code, name, price, extra) => {
    if (addLockRef.current) return;
    addLockRef.current = true;
    const product = productsDB.find(p => p.code === code);
    if (!product && !extra) { addLockRef.current = false; return; }
    setCart(prev => {
      const ex = prev.find(item => item.code === code);
      if (ex) return prev.map(item => item.code === code ? { ...item, qty: item.qty + 1 } : item);
      const itemId = product?.id || (extra?.id || code);
      return [...prev, { id: itemId, code, name, price, stock: product?.stock || 0, qty: 1, ...extra }];
    });
    setTimeout(() => { addLockRef.current = false; }, 300);
    if (playBeep) playBeep();
  }, [productsDB, playBeep]);

  const updateQty = useCallback((id, delta) => {
    setCart(prev => prev.map(item => item.id === id ? { ...item, qty: Math.max(0.01, item.qty + delta) } : item));
  }, []);

  const setItemQty = useCallback((id, val) => {
    setCart(prev => prev.map(item => item.id === id ? { ...item, qty: val } : item));
  }, []);

  const removeItem = useCallback((id) => {
    setCart(prev => prev.filter(item => item.id !== id));
  }, []);

  const clearCart = useCallback(() => {
    setCart([]);
    setPayment('');
    setPaymentMethod('efectivo');
    setUseSplitPayment(false);
    setSplitPayments([{ method: 'efectivo', amount: '' }]);
    setClientCuit('');
    setAdjustedTotal(null);
    setEditingTotal(false);
    setItemDiscounts({});
    setDiscountInputActive(null);
    setVueltoEnCuenta(false);
    setClienteVuelto('');
    setEmitirFactura(false);
    setTipoFactura('C');
  }, []);

  const ivaMultiplier = 1 + ivaRate / 100;

  const calculateTotals = useCallback(() => {
    const rawTotal = cart.reduce((acc, item) => acc + (item.price * item.qty), 0);
    const totalItemDiscount = Object.values(itemDiscounts).reduce((acc, d) => acc + (parseFloat(d) || 0), 0);
    const totalBeforePromo = Math.max(0, rawTotal - totalItemDiscount);
    const total = Math.max(0, totalBeforePromo - promotionSavings);
    const subtotal = Math.round((total / ivaMultiplier) * 100) / 100;
    const iva = Math.round((total - subtotal) * 100) / 100;
    const discount = Math.round((totalItemDiscount + promotionSavings) * 100) / 100;
    return { rawTotal: Math.round(rawTotal * 100) / 100, total: Math.round(total * 100) / 100, subtotal, iva, discount };
  }, [cart, itemDiscounts, promotionSavings, ivaMultiplier]);

  const totals = useMemo(() => calculateTotals(), [calculateTotals]);
  const { rawTotal, total, subtotal, iva, discount } = totals;
  const sanitizedAdjusted = adjustedTotal != null && !isNaN(adjustedTotal) && adjustedTotal >= 0 ? adjustedTotal : null;
  const effectiveTotal = sanitizedAdjusted ?? total;
  const change = (payment != null && payment !== '') ? Math.max(0, parseFloat(payment) - effectiveTotal) : 0;

  return {
    cart, setCart,
    search, setSearch,
    searchError, setSearchError,
    flash, setFlash,
    itemDiscounts, setItemDiscounts,
    discountInputActive, setDiscountInputActive,
    adjustedTotal, setAdjustedTotal,
    editingTotal, setEditingTotal,
    payment, setPayment,
    paymentMethod, setPaymentMethod,
    useSplitPayment, setUseSplitPayment,
    splitPayments, setSplitPayments,
    clientCuit, setClientCuit,
    vueltoEnCuenta, setVueltoEnCuenta,
    clienteVuelto, setClienteVuelto,
    emitirFactura, setEmitirFactura,
    tipoFactura, setTipoFactura,
    autoPrint, setAutoPrint,
    isCancelConfirm, setIsCancelConfirm,
    promotionSavings, setPromotionSavings,
    handleQuickAdd,
    updateQty,
    setItemQty,
    removeItem,
    clearCart,
    rawTotal, total, subtotal, iva, discount, effectiveTotal,
    change, ivaRate,
  };
}

import { useMemo, useState, useEffect, useCallback } from 'react';
import { getDaysSince, formatDate } from '../utils/dateUtils';
import { apiGet } from '../services/apiClient';

function getStoredPlan() {
  try {
    const cached = localStorage.getItem('saas_plan_cache');
    if (cached) {
      const parsed = JSON.parse(cached);
      if (parsed && parsed.plan) return parsed;
    }
  } catch {}
  try {
    const raw = localStorage.getItem('saas_business');
    if (raw) {
      const biz = JSON.parse(raw);
      if (biz && biz.plan) return { plan: biz.plan, created_at: null };
    }
  } catch {}
  return null;
}

export default function usePlan(businessConfig) {
  const [serverData, setServerData] = useState(() => getStoredPlan());
  // true una vez que el servidor respondió — evita redirecciones prematuras
  const [planLoaded, setPlanLoaded] = useState(false);
  const [retries, setRetries] = useState(0);

  const fetchPlan = useCallback(() => {
    apiGet('/auth/me')
      .then(r => r.ok ? r.json() : null)
      .then(data => {
        if (data) {
          setServerData(data);
          // Actualizar cache con el plan real del servidor
          try {
            localStorage.setItem('saas_plan_cache', JSON.stringify({
              plan: data.plan,
              created_at: data.created_at,
            }));
          } catch {}
        }
        // Marcar como cargado incluso si falla — para no bloquear UI
        setPlanLoaded(true);
      })
      .catch(() => {
        setPlanLoaded(true);
      });
  }, []);

  useEffect(() => {
    fetchPlan();
  }, [fetchPlan]);

  useEffect(() => {
    if (!serverData && !planLoaded) {
      const timer = setTimeout(() => {
        if (retries < 5) {
          setRetries(r => r + 1);
          fetchPlan();
        }
      }, 2000 * (retries + 1));
      return () => clearTimeout(timer);
    }
  }, [serverData, planLoaded, retries, fetchPlan]);

  return useMemo(() => {
    const storedFallback = serverData?.plan ? serverData.plan : (getStoredPlan()?.plan || 'trial');
    const currentPlan = serverData?.plan || storedFallback;
    const planStartDate = serverData?.created_at || businessConfig?.plan_start_date || new Date().toISOString();
    const daysSinceStart = getDaysSince(planStartDate);
    const isTrialExpired = currentPlan === 'trial' && daysSinceStart > 7;
    const trialDaysRemaining = currentPlan === 'trial' ? Math.max(0, 7 - daysSinceStart) : 0;
    const trialEndDate = currentPlan === 'trial' ? new Date(new Date(planStartDate).getTime() + 7 * 86400000) : null;
    const trialEndDateFormatted = trialEndDate ? formatDate(trialEndDate) : '';

    const planLabel = { trial: 'Trial', simple: 'Simple', pro: 'Pro', ia: 'IA' }[currentPlan] || 'Trial';
    const canAccessIA = currentPlan === 'ia' || (currentPlan === 'trial' && !isTrialExpired);
    const isPaid = currentPlan === 'simple' || currentPlan === 'pro' || currentPlan === 'ia';
    const showGate = currentPlan === 'trial' && isTrialExpired && !isPaid;

    return {
      currentPlan, planStartDate, daysSinceStart, isTrialExpired,
      trialDaysRemaining, trialEndDate, trialEndDateFormatted,
      planLabel, canAccessIA, isPaid, showGate,
      planLoaded,
    };
  }, [businessConfig?.plan_start_date, serverData, planLoaded]);
}

import { useState, useCallback, useRef } from 'react';
import { apiGet, apiPost } from '../services/apiClient';

export default function useSales(cart, effectiveTotal, payment, paymentMethod, useSplitPayment, splitPayments, clientCuit, emitirFactura, tipoFactura, vueltoEnCuenta, clienteVuelto, adjustedTotal, currentTurnId, currentOperator, setCart, clearCart, setPayment, setPaymentMethod, setUseSplitPayment, setSplitPayments, setClientCuit, setAdjustedTotal, setEditingTotal, setItemDiscounts, setDiscountInputActive, setVueltoEnCuenta, setClienteVuelto, setEmitirFactura, setTipoFactura, mpPaymentStatus, addToast) {
  const [isCharging, setIsCharging] = useState(false);
  const [lastSale, setLastSale] = useState(null);
  const [lastSaleId, setLastSaleId] = useState(null);
  const [ticketNumber, setTicketNumber] = useState(1);
  const [saleConfirm, setSaleConfirm] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isFiadoOpen, setIsFiadoOpen] = useState(false);
  const [fiadoName, setFiadoName] = useState('');
  const closeTurnStats = useRef({ total_tickets: 0, total_fiado: 0, top_products: [] });
  const processingRef = useRef(false);
  const fiadoRef2 = useRef(false);

  const generateTicketText = useCallback((saleCart, saleTotal, salePayment, saleChange, facturaTipo, afip) => {
    const now = new Date();
    const dateStr = now.toLocaleDateString('es-AR') + ' ' + now.toLocaleTimeString('es-AR');
    let text = '';
    text += 'MiNegocio POS\n';
    text += 'Ticket de Venta\n';
    text += dateStr + '\n';
    text += 'Cajero: ' + (currentOperator?.name || 'Sistema') + '\n';
    text += 'Ticket N°: ' + ticketNumber + '\n';
    if (facturaTipo && afip) {
      text += 'Factura ' + facturaTipo + '\n';
      text += 'CAE: ' + (afip.cae || '') + '\n';
    }
    text += '-'.repeat(32) + '\n';
    saleCart.forEach(item => {
      text += item.qty + 'x ' + item.name.substring(0, 20).padEnd(20) + ' $' + (item.price * item.qty).toFixed(2) + '\n';
    });
    text += '-'.repeat(32) + '\n';
    text += 'TOTAL: $' + saleTotal.toFixed(2) + '\n';
    if (salePayment > 0) text += 'Pagó: $' + salePayment.toFixed(2) + '\n';
    if (saleChange > 0) text += 'Vuelto: $' + saleChange.toFixed(2) + '\n';
    text += '\n¡Gracias por su compra!';
    return text;
  }, [currentOperator, ticketNumber]);

  const confirmCharge = useCallback(async () => {
    if (processingRef.current) return;
    processingRef.current = true;
    setIsProcessing(true);
    const saleCart = [...cart];
    const saleTotal = effectiveTotal ?? (cart.reduce((acc, item) => acc + (item.price * item.qty), 0));
    const effectivePayments = useSplitPayment
      ? splitPayments.filter(p => p.method && parseFloat(p.amount) > 0).map(p => ({ method: p.method, amount: parseFloat(p.amount) }))
      : [{ method: paymentMethod, amount: paymentMethod === 'efectivo' ? ((payment !== '' && !isNaN(parseFloat(payment))) ? parseFloat(payment) : saleTotal) : saleTotal }];
    const totalPaid = effectivePayments.reduce((sum, p) => sum + p.amount, 0);
    const salePayment = totalPaid;
    const saleChange = effectivePayments.length === 1 && effectivePayments[0].method === 'efectivo'
      ? (salePayment < saleTotal ? 0 : salePayment - saleTotal) : 0;
    const salePayload = {
      turn_id: currentTurnId,
      total: saleTotal,
      payment: salePayment,
      change_given: saleChange,
      operator: currentOperator?.name || 'Sistema',
      is_fiado: false,
      payment_method: useSplitPayment ? 'split' : paymentMethod,
      client_cuit: clientCuit,
      facturar: emitirFactura,
      tipo_factura: tipoFactura,
      vuelto_en_cuenta: vueltoEnCuenta,
      cliente_vuelto: clienteVuelto,
      payments: useSplitPayment ? effectivePayments : [],
      items: saleCart.map(i => ({
        product_id: typeof i.id === 'number' ? i.id : null,
        product_name: i.name,
        quantity: i.qty,
        unit_price: i.price,
        is_virtual: i.is_virtual || typeof i.id !== 'number',
        item_discount: 0,
      })),
    };

    const idempotencyKey = crypto.randomUUID();
    let afipResponse = null;
    try {
      const res = await apiPost(`/sales?idempotency_key=${idempotencyKey}`, salePayload);
      if (!res.ok) {
        // HTTP error (4xx/5xx) — show the actual error message, do NOT save offline
        const errData = await res.json().catch(() => ({}));
        const msg = errData.detail || `Error ${res.status} al procesar la venta`;
        addToast(`Error: ${msg}`, 'error');
        setIsProcessing(false);
        processingRef.current = false;
        return;
      }
      const data = await res.json();
      afipResponse = data.afip;
      try {
        const tRes = await apiGet('/sales/today');
        const tData = await tRes.json();
        setTicketNumber((tData.total_tickets || 0) + 1);
      } catch {
        setTicketNumber(prev => prev + 1);
      }
      setLastSaleId(data.id);
    } catch (err) {
      // Network error (fetch itself threw) — save offline
      console.error('Red inaccesible, guardando en pendientes:', err);
      const pendingStr = localStorage.getItem('minegocio_pending_sales');
      const pending = pendingStr ? JSON.parse(pendingStr) : [];
      pending.push({ payload: salePayload, idempotencyKey });
      localStorage.setItem('minegocio_pending_sales', JSON.stringify(pending));
      addToast('⚠️ Venta guardada sin conexión. Se sincronizará automáticamente.', 'info');
      setIsProcessing(false);
      processingRef.current = false;
      localStorage.removeItem('minegocio_cart');
      setLastSale({ cart: saleCart, total: saleTotal, payment: salePayment, change: saleChange, tipoFactura: emitirFactura ? tipoFactura : 'C', afip: null, paymentMethod: useSplitPayment ? 'split' : paymentMethod });
      clearCart();
      setIsCharging(false);
      return;
    }
    setIsProcessing(false);
    processingRef.current = false;

    localStorage.removeItem('minegocio_cart');
    setLastSale({ cart: saleCart, total: saleTotal, payment: salePayment, change: saleChange, tipoFactura: emitirFactura ? tipoFactura : 'C', afip: afipResponse, paymentMethod: useSplitPayment ? 'split' : paymentMethod });
    clearCart();
    setIsCharging(false);
    setSaleConfirm(true);
    setTimeout(() => setSaleConfirm(false), 2500);
    return { saleCart, saleTotal, salePayment, saleChange, afipResponse, effectivePayments };
  }, [isProcessing, cart, adjustedTotal, effectiveTotal, useSplitPayment, splitPayments, paymentMethod, payment, currentTurnId, currentOperator, clientCuit, emitirFactura, tipoFactura, vueltoEnCuenta, clienteVuelto, clearCart, setTicketNumber]);

  const confirmFiado = useCallback(async (partialAmount) => {
    if (!fiadoName) return;
    const cartTotal = effectiveTotal ?? (cart.reduce((acc, item) => acc + (item.price * item.qty), 0));

    let saleTotal, fiadoAmount, paymentAmount;
    if (cartTotal > 0) {
      // Fiar el carrito: monto parcial (<= total) o total completo
      fiadoAmount = (partialAmount && partialAmount > 0 && partialAmount <= cartTotal) ? partialAmount : cartTotal;
      paymentAmount = cartTotal - fiadoAmount;
      saleTotal = cartTotal;
    } else {
      // Deuda manual sin productos en el carrito (anotar cuánto debe)
      fiadoAmount = (partialAmount && partialAmount > 0) ? partialAmount : 0;
      paymentAmount = 0;
      saleTotal = fiadoAmount;
    }

    if (!fiadoAmount || fiadoAmount <= 0) {
      addToast('Ingresá un monto a fiar mayor a cero', 'error');
      return;
    }

    const salePayload = {
      turn_id: currentTurnId,
      total: saleTotal,
      payment: paymentAmount,
      change_given: 0,
      operator: currentOperator?.name || 'Sistema',
      is_fiado: true,
      fiado_name: fiadoName.trim(),
      payment_method: paymentAmount > 0 ? 'split' : 'fiado',
      client_cuit: '',
      items: cart.map(i => ({
        product_id: typeof i.id === 'number' ? i.id : null,
        product_name: i.name,
        quantity: i.qty,
        unit_price: i.price,
        is_virtual: i.is_virtual || typeof i.id !== 'number',
        item_discount: 0,
      })),
    };
    const idempotencyKey = crypto.randomUUID();
    try {
      const res = await apiPost(`/sales?idempotency_key=${idempotencyKey}`, salePayload);
      if (!res.ok) throw new Error("Error al procesar venta fiada");
      const data = await res.json();
      addToast(`✅ Fiado registrado a nombre de ${fiadoName}`, 'success');
      setLastSaleId(data.id);
    } catch {
      const pendingStr = localStorage.getItem('minegocio_pending_sales');
      const pending = pendingStr ? JSON.parse(pendingStr) : [];
      pending.push({ payload: salePayload, idempotencyKey });
      localStorage.setItem('minegocio_pending_sales', JSON.stringify(pending));
      addToast('Venta fiada guardada para sincronizar', 'info');
    }
    clearCart();
    setIsFiadoOpen(false);
    setFiadoName('');
  }, [fiadoName, adjustedTotal, effectiveTotal, cart, currentTurnId, currentOperator, addToast, clearCart]);

  return {
    isCharging, setIsCharging,
    lastSale, setLastSale,
    lastSaleId, setLastSaleId,
    ticketNumber, setTicketNumber,
    saleConfirm, setSaleConfirm,
    isProcessing, setIsProcessing,
    isFiadoOpen, setIsFiadoOpen,
    fiadoName, setFiadoName,
    closeTurnStats,
    generateTicketText,
    confirmCharge,
    confirmFiado,
  };
}

import { useState, useMemo } from 'react';

export default function useSortable(data, defaultKey = null) {
  const [sortKey, setSortKey] = useState(defaultKey);
  const [sortDir, setSortDir] = useState('asc');

  const toggleSort = (key) => {
    if (sortKey === key) {
      setSortDir(prev => prev === 'asc' ? 'desc' : 'asc');
    } else {
      setSortKey(key);
      setSortDir('asc');
    }
  };

  const sorted = useMemo(() => {
    if (!sortKey) return data;
    return [...data].sort((a, b) => {
      const aVal = a[sortKey];
      const bVal = b[sortKey];
      if (aVal == null) return 1;
      if (bVal == null) return -1;
      let cmp = 0;
      if (typeof aVal === 'number' && typeof bVal === 'number') {
        cmp = aVal - bVal;
      } else if (typeof aVal === 'string' && typeof bVal === 'string') {
        cmp = aVal.localeCompare(bVal, 'es', { numeric: true });
      } else {
        cmp = String(aVal).localeCompare(String(bVal), 'es', { numeric: true });
      }
      return sortDir === 'asc' ? cmp : -cmp;
    });
  }, [data, sortKey, sortDir]);

  const SortIcon = ({ columnKey }) => {
    if (sortKey !== columnKey) {
      return <span style={{ opacity: 0.3, marginLeft: 4, fontSize: '0.7rem' }}>↕</span>;
    }
    return <span style={{ marginLeft: 4, fontSize: '0.7rem' }}>{sortDir === 'asc' ? '↑' : '↓'}</span>;
  };

  return { sorted, sortKey, sortDir, toggleSort, SortIcon };
}

