            {(detail.business_type || detail.objective || detail.needs_arca || detail.prior_pos || detail.source) && (
              <div style={{ marginTop: 16, padding: '14px 16px', background: 'rgba(96,165,250,0.04)', borderRadius: 10, border: '1px solid rgba(96,165,250,0.12)' }}>
                <div style={{ color: '#94A3B8', fontSize: '0.7rem', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.5px', marginBottom: 10 }}>Qué dijo en el onboarding</div>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 7 }}>
                  {[['Rubro', detail.business_type], ['Quiere resolver', detail.objective], ['Facturación', detail.needs_arca], ['Experiencia previa', detail.prior_pos], ['Cómo llegó', detail.source]].filter(([, v]) => v).map(([l, v]) => (
                    <div key={l} style={{ display: 'flex', justifyContent: 'space-between', gap: 12, fontSize: '0.8rem' }}>
                      <span style={{ color: MUTED, flexShrink: 0 }}>{l}</span>
                      <span style={{ color: TEXT, fontWeight: 600, textAlign: 'right' }}>{v}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}
            <div style={{ marginTop: 16, padding: '14px 16px', background: 'rgba(20,187,166,0.03)', borderRadius: 10, border: '1px solid rgba(20,187,166,0.1)' }}>
              <div style={{ color: '#94A3B8', fontSize: '0.7rem', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.5px', marginBottom: 10 }}>Extender prueba / plan</div>
              <div style={{ display: 'flex', gap: 8 }}>
                {[7, 15, 30].map(d => (
                  <button key={d} onClick={() => extendPlan(detail.id, d)} style={{ ...S.ghostBtn, flex: 1, justifyContent: 'center', color: ACCENT, background: 'rgba(20,187,166,0.06)', borderColor: 'rgba(20,187,166,0.18)', fontWeight: 700 }}>+{d} días</button>
                ))}
              </div>
            </div>
            <button onClick={() => setDetail(null)} style={{ ...S.primaryBtn, width: '100%', marginTop: 12, justifyContent: 'center', padding: '11px' }}>Cerrar</button>
          </div>
        </div>
      )}
    </div>
  );
}


/* ─── Insights del Onboarding ─── */
function DistribCard({ title, subtitle, rows }) {
  const total = (rows || []).reduce((s, r) => s + (r.count || 0), 0) || 1;
  const colors = ['#14BBA6', '#3B82F6', '#F59E0B', '#10B981', '#8B5CF6', '#EC4899', '#F97316', '#06B6D4'];
  return (
    <div style={S.card}>
      <div style={{ marginBottom: 16 }}>
        <h3 style={{ fontSize: '0.95rem', fontWeight: 700, color: '#F1F5F9', margin: 0 }}>{title}</h3>
        {subtitle && <p style={{ color: MUTED, fontSize: '0.76rem', margin: '3px 0 0' }}>{subtitle}</p>}
      </div>
      {(!rows || rows.length === 0) ? (
        <div style={{ color: MUTED, fontSize: '0.82rem', padding: '20px 0', textAlign: 'center' }}>Sin datos todavía</div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 11 }}>
          {rows.map((r, i) => {
            const pct = Math.round((r.count / total) * 100);
            const isEmpty = r.label === 'Sin completar';
            const color = isEmpty ? MUTED : colors[i % colors.length];
            return (
              <div key={r.label}>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 4, fontSize: '0.82rem' }}>
                  <span style={{ color: isEmpty ? MUTED : TEXT, fontWeight: 600, fontStyle: isEmpty ? 'italic' : 'normal' }}>{r.label}</span>
                  <span style={{ color: MUTED, fontWeight: 600 }}>{r.count} · {pct}%</span>
                </div>
                <div style={{ height: 7, background: 'rgba(255,255,255,0.04)', borderRadius: 4, overflow: 'hidden' }}>
                  <div style={{ height: '100%', width: `${pct}%`, background: color, borderRadius: 4, transition: 'width 0.4s ease' }} />
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

function Insights({ token }) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let alive = true;
    (async () => {
      setLoading(true);
      try {
        const res = await fetchAdmin(`${API}/insights`, token);
        if (res.ok && alive) setData(await res.json());
      } catch {}
      if (alive) setLoading(false);
    })();
    return () => { alive = false; };
  }, [token]);

  if (loading) return <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))', gap: 18 }}>{Array.from({ length: 4 }).map((_, i) => <div key={i} style={{ ...S.card, height: 200 }} />)}</div>;

  return (
    <div>
      <div style={{ marginBottom: 20 }}>
        <h2 style={{ fontSize: '1.1rem', fontWeight: 700, color: '#F1F5F9', margin: 0 }}>Qué quieren los negocios</h2>
        <p style={{ color: MUTED, fontSize: '0.82rem', margin: '4px 0 0' }}>Basado en lo que completan las personas durante el onboarding.</p>
      </div>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))', gap: 18 }}>
        <DistribCard title="Rubros" subtitle="Tipo de negocio que abren" rows={data?.by_type} />
        <DistribCard title="Qué buscan resolver" subtitle="Su objetivo principal" rows={data?.by_objective} />
        <DistribCard title="Necesidad de facturar" subtitle="¿Necesitan ARCA / AFIP?" rows={data?.by_arca} />
        <DistribCard title="Experiencia previa" subtitle="¿Usaron un sistema antes?" rows={data?.by_prior_pos} />
        <DistribCard title="Canal de origen" subtitle="De dónde llegaron al registrarse" rows={data?.by_source} />
      </div>
    </div>
  );
}


/* ─── Audit ─── */
function Audit({ token }) {
  const [logs, setLogs] = useState([]);
  const [days, setDays] = useState(60);
  useEffect(() => {
    fetchAdmin(`${API}/audit-log?days=${days}`, token)
      .then(r => r.ok ? r.json() : [])
      .then(d => setLogs(Array.isArray(d) ? d : []))
      .catch(() => setLogs([]));
  }, [token, days]);

  const getActionBadge = (action) => {
    const a = action || '';
    if (a.includes('plan')) return <span style={S.pill('#F59E0B')}>Plan</span>;
    if (a.includes('status')) return <span style={S.pill('#3B82F6')}>Estado</span>;
    return <span style={S.pill(ACCENT)}>{a || '—'}</span>;
  };

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 22 }}>
        <h2 style={{ fontSize: '1.2rem', fontWeight: 700, color: '#F1F5F9', margin: 0 }}>Registro de auditoria</h2>
        <select value={days} onChange={e => setDays(Number(e.target.value))} style={S.select}>
          <option value={7}>7 dias</option><option value={30}>30 dias</option><option value={60}>60 dias</option><option value={365}>1 ano</option>
        </select>
      </div>
      <div style={{ ...S.card, padding: 0, overflow: 'hidden' }}>
        {logs.length === 0 ? (
          <div style={{ padding: 60, textAlign: 'center', color: MUTED }}>
            <div style={{ fontSize: '2rem', marginBottom: 12 }}>📋</div>
            <div style={{ fontSize: '0.9rem' }}>Sin actividad registrada en este periodo</div>
          </div>
        ) : (
          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.84rem' }}>
            <thead>
              <tr>
                <th style={S.tableTh}>Fecha</th>
                <th style={S.tableTh}>Admin</th>
                <th style={S.tableTh}>Negocio</th>
                <th style={S.tableTh}>Accion</th>
              </tr>
            </thead>
            <tbody>
              {logs.map(l => (
                <tr key={l.id} style={{ transition: 'background 0.12s' }}
                  onMouseEnter={e => e.currentTarget.style.background = 'rgba(255,255,255,0.01)'} onMouseLeave={e => e.currentTarget.style.background = 'transparent'}>
                  <td style={{...S.tableTd, color: MUTED, fontSize: '0.8rem', whiteSpace: 'nowrap'}}>{fmtDate(l.timestamp)} {fmtTime(l.timestamp)}</td>
                  <td style={{...S.tableTd, color: '#94A3B8'}}>{l.superadmin_email || '—'}</td>
                  <td style={{...S.tableTd, color: TEXT, fontWeight: 500}}>{l.business_name || l.business_id?.slice(0, 8)}</td>
                  <td style={S.tableTd}>{getActionBadge(l.action)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import ConfigPrinting from '../components/pos/ConfigPrinting';
import { usePanelContext } from '../context/PanelContext';
import { apiGet, apiPut } from '../services/apiClient';
import { Icons } from '../components/ui/Icons';

const FIELDS = [
  { key: 'nombre',         label: 'Nombre del negocio',    placeholder: 'Kiosco Don Julio' },
  { key: 'subtitulo',      label: 'Subtítulo / Slogan',    placeholder: 'Atención 7 días de la semana' },
  { key: 'direccion',      label: 'Dirección',             placeholder: 'Av. Corrientes 1234, CABA' },
  { key: 'telefono',       label: 'Teléfono',              placeholder: '011-4855-0000' },
  { key: 'cuit',           label: 'CUIT / CUIL',           placeholder: '20-12345678-9' },
  { key: 'condicion_iva',  label: 'Condición IVA',         placeholder: 'Monotributista', options: ['Monotributista', 'Responsable Inscripto', 'Exento', 'Consumidor Final'] },
  { key: 'numero_caja',    label: 'Nombre de la caja',     placeholder: 'CAJA 1' },
  { key: 'mensaje_ticket', label: 'Mensaje final del ticket', placeholder: '¡Gracias por su compra!' },
  { key: 'iva_rate',       label: 'IVA % por defecto',     placeholder: '21', options: ['21', '10.5', '27', '0'] },
  { key: 'mp_access_token',label: 'Access Token de Mercado Pago', placeholder: 'APP_USR-...', type: 'password' },
  { key: 'mp_collector_id',label: 'Alias / ID de Cobro de Mercado Pago', placeholder: 'TuAliasMP o ID de caja', type: 'password' },
];

const inputStyle = {
  width: '100%', background: 'var(--bg-main)', border: '1px solid var(--border-color)',
  color: 'var(--text-primary)', padding: '12px 16px', borderRadius: '8px',
  fontSize: '1rem', outline: 'none', fontFamily: 'var(--font-main)',
};

export default function ConfigPage() {
  const { backend, addToast, printing } = usePanelContext();
  const [config, setConfig] = useState({});
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);
  const [operators, setOperators] = useState([]);
  const [showMpToken, setShowMpToken] = useState(false);

  useEffect(() => {
    apiGet('/config')
      .then(r => r.json())
      .then(d => { setConfig(d); setLoading(false); })
      .catch(() => {
        setConfig({
          nombre: 'Kiosco El Barrio', subtitulo: 'Atención 7 días',
          direccion: '', telefono: '', cuit: '', condicion_iva: 'Monotributista',
          numero_caja: 'CAJA 1', mensaje_ticket: '¡Gracias por su compra!',
        });
        setLoading(false);
      });
    apiGet('/operators')
      .then(r => r.json())
      .then(d => setOperators(Array.isArray(d) ? d : []))
      .catch(() => {});
  }, []);

  const handleSave = async () => {
    setSaving(true);
    try {
      await Promise.all([
        apiPut('/config', config),
        apiPut('/operators', operators),
      ]);
      backend.setBusinessConfig(config);
      backend.setOperators(operators);
      setSaved(true);
      addToast('Configuración guardada', 'success');
      setTimeout(() => setSaved(false), 2000);
    } catch {
      addToast('Error al guardar configuración', 'error');
    }
    setSaving(false);
  };

  return (
    <div style={{ padding: '12px 20px', width: '100%', height: '100%', overflowY: 'auto', boxSizing: 'border-box' }}>
      <div style={{ maxWidth: '800px', margin: '0 auto', background: 'var(--bg-card)', padding: '24px', borderRadius: '16px', boxShadow: '0 4px 20px rgba(0,0,0,0.2)', border: '1px solid var(--border-color)' }}>
        <h2 style={{ fontSize: '1.3rem', color: 'var(--text-primary)', marginBottom: '8px' }}><Icons.Settings /> Ajustes y Configuración</h2>
        <p style={{ color: 'var(--text-secondary)', textAlign: 'center', marginBottom: '24px', fontSize: '0.9rem' }}>
          Estos datos aparecen en los tickets impresos y en el encabezado del sistema.
        </p>

        {loading ? (
          <div style={{ textAlign: 'center', padding: '32px', color: 'var(--text-secondary)' }}>Cargando...</div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
            {FIELDS.map(f => (
              <div key={f.key}>
                <label style={{ display: 'block', fontSize: '0.875rem', fontWeight: 600, color: 'var(--text-secondary)', marginBottom: '6px' }}>
                  {f.label}
                </label>
                {f.options ? (
                  <select
                    value={config[f.key] || ''}
                    onChange={e => setConfig(prev => ({ ...prev, [f.key]: e.target.value }))}
                    style={{ ...inputStyle, cursor: 'pointer', transition: 'all 0.15s' }}
                  >
                    {f.options.map(o => <option key={o} value={o}>{o}</option>)}
                  </select>
                ) : (
                  <div style={{ position: 'relative' }}>
                    <input
                      type={f.type === 'password' ? (showMpToken ? 'text' : 'password') : 'text'}
                      value={config[f.key] || ''}
                      placeholder={f.key === 'mp_access_token' && config.mp_access_token_set
                        ? '•••••••• ya configurado (dejá vacío para no cambiarlo)'
                        : f.placeholder}
                      onChange={e => setConfig(prev => ({ ...prev, [f.key]: e.target.value }))}
                      style={inputStyle}
                    />
                    {f.type === 'password' && (
                      <span onClick={() => setShowMpToken(!showMpToken)} style={{ position: 'absolute', right: 12, top: '50%', transform: 'translateY(-50%)', cursor: 'pointer', color: 'var(--text-secondary)', fontSize: '0.8rem', userSelect: 'none' }}>
                        {showMpToken ? 'Ocultar' : 'Mostrar'}
                      </span>
                    )}
                  </div>
                )}
              </div>
            ))}

            <div style={{ background: 'var(--bg-main)', border: '1px dashed var(--border-color)', borderRadius: '8px', padding: '16px', marginTop: '8px' }}>
              <div style={{ fontSize: '0.75rem', color: 'var(--text-secondary)', marginBottom: '8px', textTransform: 'uppercase', letterSpacing: '1px' }}>
                Preview del ticket (encabezado)
              </div>
              <pre style={{ fontFamily: 'var(--font-mono)', fontSize: '0.75rem', color: 'var(--text-primary)', lineHeight: 1.6, margin: 0 }}>
{`══════════════════════════════════════════
${(config.nombre || 'NOMBRE').toUpperCase().padStart(21 + Math.floor((config.nombre || '').length / 2))}
${(config.subtitulo || '').padStart(21 + Math.floor((config.subtitulo || '').length / 2))}
${(config.direccion || '').padStart(21 + Math.floor((config.direccion || '').length / 2))}
Tel: ${config.telefono || '---'}
══════════════════════════════════════════
CUIT: ${config.cuit || '---'}  ${config.condicion_iva || '---'}`}
              </pre>
            </div>

            <div style={{ marginTop: '24px', borderTop: '1px solid var(--border-color)', paddingTop: '20px' }}>
              <h3 style={{ fontSize: '1.1rem', fontWeight: 700, marginBottom: '16px', color: 'var(--text-primary)' }}><Icons.Users /> Operadores</h3>
              {operators && operators.map((op, i) => (
                <div key={i} style={{ display: 'flex', gap: '12px', marginBottom: '12px', alignItems: 'center' }}>
                  <div style={{ flex: 1 }}>
                    <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 600, color: 'var(--text-secondary)', marginBottom: '4px' }}>Nombre</label>
                    <input
                      type="text"
                      value={op.name}
                      onChange={e => {
                        const nuevos = [...operators];
                        nuevos[i] = { ...nuevos[i], name: e.target.value };
                        setOperators(nuevos);
                      }}
                      style={inputStyle}
                    />
                  </div>
                  <div style={{ width: '120px' }}>
                    <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 600, color: 'var(--text-secondary)', marginBottom: '4px' }}>PIN</label>
                    <input
                      type="text"
                      maxLength={4}
                      value={op.pin}
                      onChange={e => {
                        const nuevos = [...operators];
                        nuevos[i] = { ...nuevos[i], pin: e.target.value.replace(/[^0-9]/g, '').slice(0, 4) };
                        setOperators(nuevos);
                      }}
                      style={{ ...inputStyle, fontFamily: 'var(--font-mono)', textAlign: 'center' }}
                    />
                  </div>
                  <span style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', whiteSpace: 'nowrap' }}>({op.role})</span>
                </div>
              ))}
            </div>

            <div style={{ marginTop: '24px', borderTop: '1px solid var(--border-color)', paddingTop: '20px' }}>
              <h3 style={{ fontSize: '1.1rem', fontWeight: 700, marginBottom: '16px', color: 'var(--text-primary)' }}><Icons.Settings /> Impresión</h3>
              <ConfigPrinting printConfig={printing.printConfig} setPrintConfig={printing.setPrintConfig}
                qzConnected={printing.qzConnected} setQzConnected={printing.setQzConnected}
                addToast={addToast} />
            </div>

            <div style={{ marginTop: '24px', borderTop: '1px solid var(--border-color)', paddingTop: '20px' }}>
              <h3 style={{ fontSize: '1.1rem', fontWeight: 700, marginBottom: '8px', color: 'var(--text-primary)' }}><Icons.Activity /> Facturación ARCA (AFIP)</h3>
              <p style={{ color: 'var(--text-secondary)', fontSize: '0.85rem', marginBottom: '16px' }}>
                Habilitar emisión automática de facturas electrónicas con CAE. Requiere validación manual de certificados.
              </p>
              
              <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                <input 
                  type="checkbox" 
                  checked={false} 
                  onChange={(e) => {
                    e.preventDefault();
                    if (window.confirm("🏛️ Configuración de ARCA Requerida\n\nPara emitir facturas legales, necesitamos dar de alta tus Certificados Digitales por seguridad. Este trámite debe ser configurado manualmente por Soporte.\n\n¿Contactar a Soporte por WhatsApp ahora?")) {
                      window.open('https://wa.me/5491144276384?text=Hola,%20quiero%20habilitar%20la%20facturaci%C3%B3n%20con%20ARCA%20en%20mi%20cuenta', '_blank');
                    }
                  }} 
                  style={{ cursor: 'pointer', width: '20px', height: '20px' }}
                />
                <span style={{ fontSize: '0.9rem', color: 'var(--text-primary)', fontWeight: 600 }}>
                  Habilitar Facturación Electrónica ARCA
                </span>
              </div>
            </div>
          </div>
        )}

        <div style={{ marginTop: '32px', display: 'flex', justifyContent: 'flex-end' }}>
          <button
            className="btn btn-modal-confirm"
            onClick={handleSave}
            disabled={saving}
            style={{ width: '200px', opacity: saving ? 0.7 : 1, cursor: 'pointer', transition: 'all 0.15s' }}
          >
            {saved ? <><Icons.Check /> Guardado</> : saving ? 'Guardando...' : 'Guardar Cambios'}
          </button>
        </div>
      </div>
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { API_ROOT } from '../config';

const Svg = {
