};

export default function ContactoPage() {
  const navigate = useNavigate();
  const [sent, setSent] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({ nombre: '', contacto: '', mensaje: '' });

  useEffect(() => {
    document.body.classList.add('landing-open');
    window.scrollTo(0, 0);
    return () => document.body.classList.remove('landing-open');
  }, []);

  const handleSend = async () => {
    if (!formData.nombre || !formData.contacto || !formData.mensaje) {
      setErrorMsg('Por favor, completa todos los campos.');
      return;
    }
    setErrorMsg('');
    setLoading(true);
    try {
      const res = await fetch(`${API_ROOT}/api/send-contact-email`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      });
      if (res.ok) {
        setSent(true);
        setFormData({ nombre: '', contacto: '', mensaje: '' });
      } else {
        setErrorMsg('Hubo un error al enviar el mensaje. Reintenta por favor.');
      }
    } catch (error) {
      console.error(error);
      setErrorMsg('Error de red. Asegurate de tener conexion.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="lp-noise" style={{ fontFamily: 'var(--lp-font-body)', color: 'var(--lp-text)', minHeight: '100vh', position: 'relative', padding: '40px 24px' }}>
      <div className="lp-canvas" />
      <div className="lp-orb lp-orb--1" />
      <div className="lp-orb lp-orb--2" />

      <div style={{ maxWidth: 900, margin: '0 auto', position: 'relative', zIndex: 10 }}>
        <button onClick={() => navigate('/')} style={{ background: 'transparent', border: 'none', color: 'var(--lp-text-muted)', fontSize: '0.9rem', cursor: 'pointer', display: 'inline-flex', alignItems: 'center', gap: 8, marginBottom: 32, transition: 'color 0.2s' }} onMouseEnter={e => e.target.style.color = '#fff'} onMouseLeave={e => e.target.style.color = 'var(--lp-text-muted)'}>
          <Svg.ArrowLeft /> Volver a Inicio
        </button>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: 32 }}>
          
          {/* Info de contacto */}
          <div>
            <h1 style={{ fontSize: '2.2rem', fontWeight: 800, letterSpacing: '-1px', marginBottom: 16, color: '#fff' }}>Contacto</h1>
            <p style={{ fontSize: '0.95rem', lineHeight: 1.5, color: 'rgba(230,255,251,0.7)', marginBottom: 32 }}>
              ¿Tenés dudas sobre nuestros planes personalizados o querés una demostración en vivo? Escribinos y un especialista se pondrá en contacto con vos a la brevedad.
            </p>

            <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                <div style={{ padding: 10, background: 'rgba(20,187,166,0.1)', borderRadius: 10 }}>
                  <Svg.Mail />
                </div>
                <div>
                  <div style={{ fontSize: '0.75rem', color: 'var(--lp-text-muted)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: 1 }}>Email</div>
                  <div style={{ fontSize: '0.95rem', color: '#fff', fontWeight: 500 }}>upcodednow@gmail.com</div>
                </div>
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                <div style={{ padding: 10, background: 'rgba(20,187,166,0.1)', borderRadius: 10 }}>
                  <Svg.Phone />
                </div>
                <div>
                  <div style={{ fontSize: '0.75rem', color: 'var(--lp-text-muted)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: 1 }}>WhatsApp</div>
                  <div style={{ fontSize: '0.95rem', color: '#fff', fontWeight: 500 }}>+54 9 11 4427-6384</div>
                </div>
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                <div style={{ padding: 10, background: 'rgba(20,187,166,0.1)', borderRadius: 10 }}>
                  <Svg.MapPin />
                </div>
                <div>
                  <div style={{ fontSize: '0.75rem', color: 'var(--lp-text-muted)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: 1 }}>Oficinas</div>
                  <div style={{ fontSize: '0.95rem', color: '#fff', fontWeight: 500 }}>Buenos Aires, Argentina</div>
                </div>
              </div>
            </div>
          </div>

          {/* Formulario */}
          <div className="lp-glass" style={{ padding: '32px', borderRadius: 20, border: '1px solid rgba(255,255,255,0.1)', background: 'rgba(35,65,105,0.85)' }}>
            {sent ? (
              <div style={{ textAlign: 'center', padding: '32px 0' }}>
                <div style={{ width: 56, height: 56, background: 'rgba(16,185,129,0.1)', color: '#10b981', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 16px' }}>
                  <svg width="28" height="28" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg>
                </div>
                <h3 style={{ fontSize: '1.3rem', color: '#fff', marginBottom: 8 }}>¡Mensaje enviado!</h3>
                <p style={{ color: 'var(--lp-text-muted)', fontSize: '0.9rem' }}>Nos pondremos en contacto con vos en las próximas horas.</p>
                <button onClick={() => setSent(false)} className="lp-btn lp-btn--ghost" style={{ marginTop: 20, padding: '8px 20px', fontSize: '0.85rem' }}>Enviar otro</button>
              </div>
            ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                {errorMsg && <div style={{ background: 'rgba(239,68,68,0.1)', color: '#ef4444', padding: '10px 14px', borderRadius: 8, fontWeight: 500, fontSize: '0.85rem' }}>{errorMsg}</div>}
                <div>
                  <label style={{ fontSize: '0.8rem', color: 'rgba(255,255,255,0.8)', fontWeight: 500, display: 'block', marginBottom: 6 }}>Nombre completo</label>
                  <input type="text" value={formData.nombre} onChange={e => setFormData({...formData, nombre: e.target.value})} placeholder="Tu nombre" style={{ width: '100%', padding: '10px 14px', background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 8, color: '#fff', outline: 'none', fontSize: '0.9rem', transition: 'all 0.2s' }} onFocus={e => e.target.style.borderColor = 'var(--lp-primary)'} onBlur={e => e.target.style.borderColor = 'rgba(255,255,255,0.1)'} />
                </div>
                <div>
                  <label style={{ fontSize: '0.8rem', color: 'rgba(255,255,255,0.8)', fontWeight: 500, display: 'block', marginBottom: 6 }}>Email o Teléfono</label>
                  <input type="text" value={formData.contacto} onChange={e => setFormData({...formData, contacto: e.target.value})} placeholder="Para contactarte" style={{ width: '100%', padding: '10px 14px', background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 8, color: '#fff', outline: 'none', fontSize: '0.9rem', transition: 'all 0.2s' }} onFocus={e => e.target.style.borderColor = 'var(--lp-primary)'} onBlur={e => e.target.style.borderColor = 'rgba(255,255,255,0.1)'} />
                </div>
                <div>
                  <label style={{ fontSize: '0.8rem', color: 'rgba(255,255,255,0.8)', fontWeight: 500, display: 'block', marginBottom: 6 }}>Mensaje</label>
                  <textarea value={formData.mensaje} onChange={e => setFormData({...formData, mensaje: e.target.value})} placeholder="¿En qué te podemos ayudar?" rows="4" style={{ width: '100%', padding: '10px 14px', background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 8, color: '#fff', outline: 'none', fontSize: '0.9rem', transition: 'all 0.2s', resize: 'none' }} onFocus={e => e.target.style.borderColor = 'var(--lp-primary)'} onBlur={e => e.target.style.borderColor = 'rgba(255,255,255,0.1)'} />
                </div>
                <button onClick={handleSend} disabled={loading} style={{ width: '100%', padding: '12px 0', borderRadius: 8, border: 'none', background: loading ? 'rgba(255,255,255,0.1)' : 'linear-gradient(90deg, var(--lp-primary), var(--lp-secondary))', color: loading ? 'var(--lp-text-muted)' : '#fff', fontSize: '0.95rem', fontWeight: 700, cursor: loading ? 'not-allowed' : 'pointer', marginTop: 8, boxShadow: loading ? 'none' : '0 8px 24px rgba(20,187,166, 0.3)', transition: 'all 0.2s' }}>
                  {loading ? 'Enviando...' : 'Enviar Mensaje'}
                </button>
              </div>
            )}
          </div>

        </div>
      </div>
    </div>
  );
}

import React from 'react';
import { useNavigate } from 'react-router-dom';
import { usePanelContext } from '../context/PanelContext';
import { Icons } from '../components/ui/Icons';
import { formatMoney } from '../utils/format';
import { apiGet } from '../services/apiClient';

function ResumenIA() {
  const [texto, setTexto] = React.useState('');
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState('');

  const cargar = React.useCallback(() => {
    setLoading(true);
    setError('');
    apiGet('/ai/resumen')
      .then(r => r.ok ? r.json() : Promise.reject(r))
      .then(d => setTexto(d.texto || ''))
      .catch(() => setError('No se pudo generar el resumen ahora. Probá de nuevo en un rato.'))
      .finally(() => setLoading(false));
  }, []);

  React.useEffect(() => { cargar(); }, [cargar]);

  return (
    <div style={{ background: 'linear-gradient(135deg, rgba(124,58,237,0.10), rgba(20,187,166,0.06))', border: '1px solid rgba(165,180,252,0.25)', borderRadius: 16, padding: '18px 22px', marginBottom: 16 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, color: '#c4b5fd', fontWeight: 800, fontSize: '0.92rem' }}>
          <svg width="18" height="18" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z"/></svg>
          Tu resumen del día con IA
        </div>
        <button onClick={cargar} disabled={loading} title="Actualizar" style={{ background: 'transparent', border: '1px solid rgba(165,180,252,0.3)', color: '#c4b5fd', borderRadius: 8, padding: '4px 10px', fontSize: '0.78rem', fontWeight: 700, cursor: loading ? 'default' : 'pointer' }}>
          {loading ? 'Pensando…' : '↻ Actualizar'}
        </button>
      </div>
      {loading ? (
        <div style={{ color: 'var(--text-secondary)', fontSize: '0.95rem' }}>Analizando las ventas de hoy…</div>
      ) : error ? (
        <div style={{ color: 'var(--text-secondary)', fontSize: '0.92rem' }}>{error}</div>
      ) : (
        <p style={{ color: 'var(--text-primary)', fontSize: '1rem', lineHeight: 1.6, margin: 0 }}>{texto}</p>
      )}
    </div>
  );
}

function StatCard({ label, value, sub, color, icon }) {
  return (
    <div style={{ flex: 1, minWidth: 200, background: 'var(--bg-card)', border: '1px solid var(--border-color)', borderRadius: 16, padding: '20px 22px', position: 'relative', overflow: 'hidden' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
        <div style={{ color: 'var(--text-secondary)', fontSize: '0.8rem', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.4px' }}>{label}</div>
        <div style={{ color, opacity: 0.85 }}>{icon}</div>
      </div>
      <div style={{ fontSize: '2rem', fontWeight: 800, color, fontFamily: 'var(--font-mono)', marginTop: 8, letterSpacing: '-0.5px' }}>{value}</div>
      {sub && <div style={{ color: 'var(--text-secondary)', fontSize: '0.82rem', marginTop: 2 }}>{sub}</div>}
    </div>
  );
}

export default function InicioPage() {
  const navigate = useNavigate();
  const { backend, auth, currentPlan } = usePanelContext();

  // Reloj liviano: refresca saludo y fecha cada minuto (cubre el paso día→tarde→noche)
  const [now, setNow] = React.useState(() => new Date());
  React.useEffect(() => {
    const t = setInterval(() => setNow(new Date()), 60000);
    return () => clearInterval(t);
  }, []);

  const r = backend.resumenData || {};
  const vendido = r.total_vendido ?? ((r.total_efectivo || 0) + (r.total_tarjeta || 0) + (r.total_transferencia || 0) + (r.total_mp || 0) + (r.total_fiado || 0));
  const tickets = r.total_tickets || 0;
  const efectivo = r.total_efectivo || 0;
  const fiado = r.total_fiado || 0;
  const promedio = tickets > 0 ? vendido / tickets : 0;

  const operador = auth.currentOperator?.name || 'Dueño';
  const negocio = backend.businessConfig?.nombre || 'tu negocio';
  const hora = now.getHours();
  const saludoHora = hora < 12 ? 'buen día' : hora < 20 ? 'buenas tardes' : 'buenas noches';
  const hoy = now.toLocaleDateString('es-AR', { weekday: 'long', day: 'numeric', month: 'long' });

  const sa = backend.stockAlerts?.stock || {};
  const porAgotarse = [
    ...(sa.empty || []).map(p => ({ ...p, estado: 'SIN STOCK', danger: true })),
    ...(sa.low || []).map(p => ({ ...p, estado: `Quedan ${p.stock}`, danger: false })),
  ].slice(0, 6);

  return (
    <div style={{ padding: '20px 24px', width: '100%', height: '100%', overflowY: 'auto', boxSizing: 'border-box' }}>
      {/* Saludo */}
      <div style={{ marginBottom: 20 }}>
        <h1 style={{ fontSize: '1.6rem', fontWeight: 800, margin: 0, color: 'var(--text-primary)', letterSpacing: '-0.4px' }}>
          Hola {operador}, {saludoHora}
        </h1>
        <p style={{ color: 'var(--text-secondary)', fontSize: '0.9rem', margin: '4px 0 0', textTransform: 'capitalize' }}>{hoy} · {negocio}</p>
      </div>

      {/* Resumen del día con IA (solo Plan IA) */}
      {currentPlan === 'ia' && <ResumenIA />}

      {/* Números del día */}
      <div style={{ display: 'flex', gap: 16, flexWrap: 'wrap', marginBottom: 16 }}>
        <StatCard label="Ventas de hoy" value={formatMoney(vendido)} sub={`${tickets} ${tickets === 1 ? 'venta' : 'ventas'}`} color="var(--accent-success)" icon={<Icons.Chart />} />
        <StatCard label="Efectivo en caja" value={formatMoney(efectivo)} sub="Lo que entró en mano" color="var(--accent-primary)" icon={<Icons.ShoppingCart />} />
        <StatCard label="Fiado de hoy" value={formatMoney(fiado)} sub="Anotado en cuentas" color="var(--accent-warning)" icon={<Icons.Book />} />
        <StatCard label="Ticket promedio" value={formatMoney(promedio)} sub="Por venta" color="var(--text-primary)" icon={<Icons.Tag />} />
      </div>

      {/* CTA + Por agotarse */}
      <div style={{ display: 'flex', gap: 16, flexWrap: 'wrap', alignItems: 'stretch' }}>
        {/* Ir a vender */}
        <div style={{ flex: '1 1 280px', background: 'var(--gradient-card)', border: '1px solid var(--border-color)', borderRadius: 16, padding: 24, display: 'flex', flexDirection: 'column', justifyContent: 'center', gap: 12 }}>
          <div>
            <h2 style={{ margin: 0, fontSize: '1.2rem', fontWeight: 800, color: 'var(--text-primary)' }}>¿Arrancamos a vender?</h2>
            <p style={{ color: 'var(--text-secondary)', fontSize: '0.88rem', margin: '6px 0 0' }}>Escaneá un código o buscá un producto. El vuelto se calcula solo.</p>
          </div>
          <button onClick={() => navigate('/panel/ventas')} style={{ background: 'var(--gradient-primary)', color: '#fff', border: 'none', padding: '16px', borderRadius: 12, fontSize: '1.05rem', fontWeight: 800, cursor: 'pointer', boxShadow: '0 8px 24px rgba(20,187,166,0.3)', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8 }}>
            <Icons.ShoppingCart /> Ir a vender
          </button>
        </div>

        {/* Productos por agotarse */}
        <div style={{ flex: '1 1 320px', background: 'var(--bg-card)', border: '1px solid var(--border-color)', borderRadius: 16, padding: 20 }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
            <h2 style={{ margin: 0, fontSize: '1rem', fontWeight: 800, color: 'var(--text-primary)' }}>Por agotarse</h2>
            <button onClick={() => navigate('/panel/inventario')} style={{ background: 'transparent', border: 'none', color: 'var(--accent-primary)', fontWeight: 700, fontSize: '0.82rem', cursor: 'pointer' }}>Ver inventario →</button>
          </div>
          {porAgotarse.length === 0 ? (
            <div style={{ color: 'var(--text-secondary)', fontSize: '0.88rem', padding: '20px 0', textAlign: 'center' }}>
              Todo en orden. No hay productos por agotarse. ✅
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
              {porAgotarse.map(p => (
                <div key={p.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '8px 12px', background: 'rgba(255,255,255,0.02)', borderRadius: 8, border: '1px solid var(--border-color)' }}>
                  <span style={{ color: 'var(--text-primary)', fontSize: '0.88rem', fontWeight: 600, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', maxWidth: '60%' }}>{p.name}</span>
                  <span style={{ color: p.danger ? 'var(--accent-danger)' : 'var(--accent-warning)', fontSize: '0.78rem', fontWeight: 700 }}>{p.estado}</span>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

