import { useState, useEffect } from 'react';

const Svg = {
  X: () => <svg width="22" height="22" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M6 18L18 6M6 6l12 12" /></svg>,
};

export default function LandingLoginModal({
  showLoginModal, setShowLoginModal, setShowForgotPassword,
  loginName, setLoginName, loginEmail, setLoginEmail,
  loginPassword, setLoginPassword, showPassword, setShowPassword,
  loginLoading, loginError, handleAuthSubmit, goOnboard, navigate
}) {
  const [termsAccepted, setTermsAccepted] = useState(false);

  // Resetear checkbox al cambiar entre login/register
  useEffect(() => {
    setTermsAccepted(false);
  }, [showLoginModal]);

  if (!showLoginModal) return null;

  const isRegister = showLoginModal === 'register';
  const canSubmit = !loginLoading && (!isRegister || termsAccepted);

  return (
    <div
      style={{ position: 'fixed', inset: 0, zIndex: 9999, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', background: 'rgba(30,58,95,0.85)', backdropFilter: 'blur(20px)', padding: 20, animation: 'fadeIn 0.2s ease' }}
      onMouseDown={(e) => { if (e.target === e.currentTarget) setShowLoginModal(false); }}
      onKeyDown={(e) => { if (e.key === 'Escape') setShowLoginModal(false); }}
    >
      <div
        onMouseDown={e => e.stopPropagation()}
        onClick={e => e.stopPropagation()}
        style={{ width: '100%', maxWidth: 460, background: 'linear-gradient(145deg, rgba(11,19,43,0.95) 0%, rgba(30,58,95,0.95) 100%)', border: '1px solid rgba(20,187,166,0.3)', borderRadius: 24, padding: '40px 40px 32px', position: 'relative', boxShadow: '0 30px 60px rgba(0,0,0,0.6)' }}
      >
        <button
          onClick={() => setShowLoginModal(false)}
          style={{ position: 'absolute', top: 20, right: 20, background: 'rgba(255,255,255,0.05)', border: 'none', color: 'var(--lp-text-muted)', width: 32, height: 32, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', transition: 'all 0.2s' }}
          onMouseEnter={e => { e.currentTarget.style.color = '#fff'; e.currentTarget.style.background = 'rgba(255,255,255,0.1)'; }}
          onMouseLeave={e => { e.currentTarget.style.color = 'var(--lp-text-muted)'; e.currentTarget.style.background = 'rgba(255,255,255,0.05)'; }}
        >
          <Svg.X />
        </button>

        <div style={{ display: 'flex', alignItems: 'center', gap: 16, marginBottom: 8 }}>
          <div style={{ width: 48, height: 48, borderRadius: 12, background: 'rgba(20,187,166,0.15)', display: 'flex', alignItems: 'center', justifyContent: 'center', border: '1px solid rgba(20,187,166,0.3)' }}>
            <svg width="24" height="24" fill="none" stroke="var(--lp-primary)" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
          </div>
          <div>
            <h2 style={{ color: '#ffffff', fontSize: '1.6rem', fontWeight: 800, letterSpacing: '-0.5px', lineHeight: 1 }}>
              {isRegister ? 'Creá tu cuenta' : 'Bienvenido'}
            </h2>
            <p style={{ color: 'var(--lp-text-muted)', fontSize: '0.9rem', marginTop: 4 }}>
              O{' '}
              <span
                onClick={() => setShowLoginModal(isRegister ? 'login' : 'register')}
                style={{ color: 'var(--lp-primary)', cursor: 'pointer', fontWeight: 600, textDecoration: 'underline', textUnderlineOffset: 2 }}
              >
                {isRegister ? 'iniciá sesión' : 'registrate gratis'}
              </span>
            </p>
          </div>
        </div>

        <div style={{ marginTop: 32 }}>
          {loginError && (
            <div style={{ background: 'rgba(239,68,68,0.1)', color: '#ef4444', padding: '12px', borderRadius: '8px', marginBottom: '16px', fontWeight: 600, textAlign: 'center', fontSize: '0.9rem' }}>
              {loginError}
            </div>
          )}

          <div style={{ display: 'flex', flexDirection: 'column', gap: 6, marginBottom: 20 }}>
            {isRegister && (
              <div style={{ marginBottom: 14 }}>
                <label style={{ fontSize: '0.85rem', color: 'rgba(255,255,255,0.8)', fontWeight: 500 }}>Tu Nombre</label>
                <input
                  type="text" value={loginName} onChange={e => setLoginName(e.target.value)} placeholder="Ej: Carlos"
                  style={{ width: '100%', padding: '14px 16px', marginTop: 6, background: 'rgba(30,58,95,0.3)', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 12, color: '#fff', outline: 'none', fontSize: '0.95rem', transition: 'all 0.2s', boxShadow: 'inset 0 2px 4px rgba(30,58,95,0.1)' }}
                  onFocus={e => { e.target.style.borderColor = 'var(--lp-primary)'; e.target.style.background = 'rgba(30,58,95,0.5)'; }}
                  onBlur={e => { e.target.style.borderColor = 'rgba(255,255,255,0.1)'; e.target.style.background = 'rgba(30,58,95,0.3)'; }}
                />
              </div>
            )}
            <label style={{ fontSize: '0.85rem', color: 'rgba(255,255,255,0.8)', fontWeight: 500 }}>Correo electrónico</label>
            <input
              type="email" value={loginEmail} onChange={e => setLoginEmail(e.target.value)} placeholder="nombre@kiosco.com"
              style={{ width: '100%', padding: '14px 16px', background: 'rgba(30,58,95,0.3)', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 12, color: '#fff', outline: 'none', fontSize: '0.95rem', transition: 'all 0.2s', boxShadow: 'inset 0 2px 4px rgba(30,58,95,0.1)' }}
              onFocus={e => { e.target.style.borderColor = 'var(--lp-primary)'; e.target.style.background = 'rgba(30,58,95,0.5)'; }}
              onBlur={e => { e.target.style.borderColor = 'rgba(255,255,255,0.1)'; e.target.style.background = 'rgba(30,58,95,0.3)'; }}
            />
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', gap: 6, marginBottom: isRegister ? 20 : 32 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <label style={{ fontSize: '0.85rem', color: 'rgba(255,255,255,0.8)', fontWeight: 500 }}>Contraseña</label>
              {!isRegister && (
                <span
                  onClick={() => { setShowLoginModal(false); setShowForgotPassword(true); }}
                  style={{ color: 'var(--lp-primary)', fontSize: '0.8rem', cursor: 'pointer', fontWeight: 500 }}
                >
                  ¿Olvidaste tu contraseña?
                </span>
              )}
            </div>
            <div style={{ position: 'relative' }}>
              <input
                type={showPassword ? 'text' : 'password'} value={loginPassword} onChange={e => setLoginPassword(e.target.value)} placeholder="••••••••"
                style={{ width: '100%', padding: '14px 16px', background: 'rgba(30,58,95,0.3)', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 12, color: '#fff', outline: 'none', fontSize: '0.95rem', transition: 'all 0.2s', boxShadow: 'inset 0 2px 4px rgba(30,58,95,0.1)' }}
                onFocus={e => { e.target.style.borderColor = 'var(--lp-primary)'; e.target.style.background = 'rgba(30,58,95,0.5)'; }}
                onBlur={e => { e.target.style.borderColor = 'rgba(255,255,255,0.1)'; e.target.style.background = 'rgba(30,58,95,0.3)'; }}
              />
              <div
